    group = "Weibull Family", categoria = "Weibull models", label = "Weibull Model (+, from 0 to Ce)",
    formula = "Ce * (1 - exp(-((x / alpha)^beta)))",
    display = "Active function: y = Ce * (1 - exp(-((x / alpha)^beta)))",
    guess = "Ce=10[0,], alpha=2[0.001,], beta=1.5[0.001,]",
