  # ---- Kinetic Reactions ----
  "arrhenius" = list(
    group = "Kinetic Reactions", categoria = "Reaction Kinetics", label = "Arrhenius Equation",
    # Classic form of the Arrhenius equation (reaction rate as a
    # function of the absolute temperature), not the "shelf-life" form
