                   column(3, selectInput("ni_lty_iso", "Isothermal Curve Line Type:", choices = c("Solid" = "1", "Dashed" = "2", "Dotted" = "3", "Dot-dash" = "4"), selected = if(is.null(input$ni_lty_iso)) "2" else input$ni_lty_iso)),
