  CONFIG_CAMPI_TEXT <- c(
    "ni_secondario_formula_custom", "ni_secondario_guess_custom",
    "mcni_secondario_formula_custom", "mcni_secondario_guess_custom",
    "ni_profilo_formula_custom", "ni_profilo_guess_custom",
