  output$salva_configurazione <- downloadHandler(
    filename = function() {
      nome_pulito <- trimws(input$nome_file_configurazione)
      if (nchar(nome_pulito) == 0) nome_pulito <- paste0("nlr_config_", format(Sys.time(), "%Y%m%d_%H%M"))
      # Removes characters that are not safe for a file name, keeps only
      # letters/numbers/underscore/hyphen
      nome_pulito <- gsub("[^A-Za-z0-9_-]", "_", nome_pulito)
      paste0(nome_pulito, ".rconfig")
    },
    content = function(file) {
      configurazione <- list(
        tipo_modello = input$tipo_modello,
        formula_custom = input$formula_custom,
        guess_iniziali = input$guess_iniziali,
        tipo_loss = input$tipo_loss,
        ponderazione = input$ponderazione,
        ponderazione_zeta = input$ponderazione_zeta,
        batch_zeta_modo = input$batch_zeta_modo,
        algoritmo = input$algoritmo,
        metodo_errore = input$metodo_errore,
        n_boot = input$n_boot,
        tipo_rumore_mc = input$tipo_rumore_mc,
        label_x = input$label_x,
        label_y = input$label_y,
        applica_limiti_predefiniti = input$applica_limiti_predefiniti
      )
      # Adds all the aesthetic customization controls, by type
      for (id in CONFIG_CAMPI_SELECT) configurazione[[id]] <- input[[id]]
      for (id in CONFIG_CAMPI_SLIDER) configurazione[[id]] <- input[[id]]
      for (id in CONFIG_CAMPI_CHECKBOX) configurazione[[id]] <- input[[id]]
      for (id in CONFIG_CAMPI_NUMERIC) configurazione[[id]] <- input[[id]]
      for (id in CONFIG_CAMPI_TEXT) configurazione[[id]] <- input[[id]]
      dput(configurazione, file = file)
    }
  )
  
  observeEvent(input$carica_configurazione, {
    file_caricato <- input$carica_configurazione
    configurazione <- tryCatch(dget(file_caricato$datapath), error = function(e) NULL)
    if (is.null(configurazione) || !is.list(configurazione)) {
      showNotification("Could not read this configuration file \u2014 it may be corrupted or not a valid configuration.", type = "error")
      return()
    }
    # Updates each field ONLY if present in the loaded file, so a file
    # saved by a previous version of the app (with fewer fields) does not
    # cause errors on the missing fields.
    if (!is.null(configurazione$tipo_modello)) updateSelectInput(session, "tipo_modello", selected = configurazione$tipo_modello)
    if (!is.null(configurazione$formula_custom)) updateTextInput(session, "formula_custom", value = configurazione$formula_custom)
    if (!is.null(configurazione$tipo_loss)) updateSelectInput(session, "tipo_loss", selected = configurazione$tipo_loss)
    if (!is.null(configurazione$ponderazione)) updateSelectInput(session, "ponderazione", selected = configurazione$ponderazione)
    if (!is.null(configurazione$ponderazione_zeta)) updateNumericInput(session, "ponderazione_zeta", value = configurazione$ponderazione_zeta)
    if (!is.null(configurazione$batch_zeta_modo)) updateRadioButtons(session, "batch_zeta_modo", selected = configurazione$batch_zeta_modo)
    if (!is.null(configurazione$algoritmo)) updateSelectInput(session, "algoritmo", selected = configurazione$algoritmo)
    if (!is.null(configurazione$metodo_errore)) updateSelectInput(session, "metodo_errore", selected = configurazione$metodo_errore)
    if (!is.null(configurazione$n_boot)) updateNumericInput(session, "n_boot", value = configurazione$n_boot)
    if (!is.null(configurazione$tipo_rumore_mc)) updateSelectInput(session, "tipo_rumore_mc", selected = configurazione$tipo_rumore_mc)
    if (!is.null(configurazione$label_x)) updateTextInput(session, "label_x", value = configurazione$label_x)
    if (!is.null(configurazione$label_y)) updateTextInput(session, "label_y", value = configurazione$label_y)
    if (!is.null(configurazione$applica_limiti_predefiniti)) updateCheckboxInput(session, "applica_limiti_predefiniti", value = configurazione$applica_limiti_predefiniti)
    # Restores all the aesthetic customization controls, by type -
    # same "only if present in the file" logic as above.
    for (id in CONFIG_CAMPI_SELECT) if (!is.null(configurazione[[id]])) updateSelectInput(session, id, selected = configurazione[[id]])
    for (id in CONFIG_CAMPI_SLIDER) if (!is.null(configurazione[[id]])) updateSliderInput(session, id, value = configurazione[[id]])
    for (id in CONFIG_CAMPI_CHECKBOX) if (!is.null(configurazione[[id]])) updateCheckboxInput(session, id, value = configurazione[[id]])
    for (id in CONFIG_CAMPI_NUMERIC) if (!is.null(configurazione[[id]])) updateNumericInput(session, id, value = configurazione[[id]])
    if (!is.null(configurazione$esponente_tolleranza) && !is.null(configurazione$algoritmo) && !identical(configurazione$algoritmo, isolate(input$algoritmo))) {
      tolleranza_in_attesa(configurazione$esponente_tolleranza)
    }
    for (id in CONFIG_CAMPI_TEXT) if (!is.null(configurazione[[id]])) updateTextInput(session, id, value = configurazione[[id]])
    # Changing tipo_modello above triggers an automatic reset of the
    # guess field (another observer, same mechanism as the model selector) - but
    # that observer fires at the NEXT reactive cycle, not immediately: if
    # we wrote the loaded guess here, it would be overwritten AFTERWARDS by that
    # automatic reset, not before. session$onFlushed() instead guarantees that
    # our update happens AFTER the reactive cycle (including
    # that reset) has already stabilized.
    guess_da_ripristinare <- configurazione$guess_iniziali
    if (!is.null(guess_da_ripristinare)) {
      session$onFlushed(function() {
        updateTextInput(session, "guess_iniziali", value = guess_da_ripristinare)
      }, once = TRUE)
    }
    showNotification("Configuration loaded successfully.", type = "message")
  })
  
  observeEvent(input$aggiungi_simbolo, {
    nome <- trimws(input$simbolo_par_nome)
    display <- trimws(input$simbolo_par_display)
    if (nchar(nome) == 0 || nchar(display) == 0) {
      showNotification("Enter both a parameter name and a display symbol.", type = "error")
      return()
    }
    mappa <- simboli_parametri()
    mappa[[nome]] <- display
    simboli_parametri(mappa)
    updateTextInput(session, "simbolo_par_nome", value = "")
    updateTextInput(session, "simbolo_par_display", value = "")
  })
  
  observeEvent(input$svuota_simboli, {
    simboli_parametri(list())
    showNotification("All display symbols cleared.", type = "message")
  })
  
  output$tabella_simboli_parametri <- renderTable({
    mappa <- simboli_parametri()
    if (length(mappa) == 0) return(data.frame(Message = "No custom display symbols defined yet."))
    data.frame(Parameter = names(mappa), `Display Symbol` = unlist(mappa, use.names = FALSE), stringsAsFactors = FALSE, check.names = FALSE)
  }, striped = TRUE, hover = TRUE, bordered = TRUE)
  
  # Automatic fallback for parameters WITHOUT an explicit mapping in the
  # registry (field "simboli") - still recognizes two common patterns:
  # 1) the name, made lowercase, is a known lowercase Greek letter (e.g.
  #    "MU" or "Mu" -> "mu", which plotmath automatically draws as mu)
  #    - I first check the EXACT name among the keys of GRECO_HTML, so
  #    a hypothetical parameter literally called "Gamma" (UPPERCASE Greek
  #    letter Gamma, a distinct key in GRECO_HTML) is not
  #    confused with lowercase "gamma".
  # 2) the name ends with one or more digits (e.g. "n1", "k12", "b2") -
  #    rewritten in plotmath subscript notation, e.g. "n[1]", "k[12]".
  # For very long formulas (e.g. Integrated Baranyi), instead of
  # shrinking the font more than necessary on a single line, I look for a
  # safe point to break it onto two lines: a "+"/"-" at a level
  # NOT nested inside parentheses (depth 0), as close as
  # possible to the centre of the string. I never choose a unary sign
  # (e.g. the "-" inside "exp(-MU*x)", or right after another operator) -
  # only a true binary operator, recognizable by the fact that the
  # previous non-space character is the end of a complete term
  # (letter, digit, or closing parenthesis), not another operator or "(".
  trova_punto_split_formula <- function(formula_stringa) {
    n <- nchar(formula_stringa)
    centro <- n %/% 2
    profondita <- 0
    candidati <- integer(0)
    for (i in seq_len(n)) {
      carattere <- substr(formula_stringa, i, i)
      if (carattere == "(") {
        profondita <- profondita + 1
      } else if (carattere == ")") {
        profondita <- profondita - 1
      } else if (profondita == 0 && carattere %in% c("+", "-") && i > 1 && i < n) {
        j <- i - 1
        while (j >= 1 && substr(formula_stringa, j, j) == " ") j <- j - 1
        precedente <- if (j >= 1) substr(formula_stringa, j, j) else ""
        if (precedente != "" && !(precedente %in% c("+", "-", "*", "/", "("))) {
          candidati <- c(candidati, i)
        }
      }
    }
    if (length(candidati) == 0) return(NULL)
    candidati[which.min(abs(candidati - centro))]
  }
  
  # Applies the split only beyond a length threshold (60 characters,
  # deliberately higher than the threshold of 40 used for the font
  # shrinking alone) - moderately long formulas stay
  # on one line with a slight shrinking, already acceptable; the
  # real need to break the line is felt only for the very long ones.
  # If no valid split point exists (e.g. the whole formula is
  # enclosed in a single outer function), it falls back to the single line.
  dividi_formula_lunga <- function(formula_stringa, soglia = 140) {
    if (nchar(formula_stringa) <= soglia) return(list(riga1 = formula_stringa, riga2 = NULL))
    pos <- trova_punto_split_formula(formula_stringa)
    if (is.null(pos)) return(list(riga1 = formula_stringa, riga2 = NULL))
    list(riga1 = trimws(substr(formula_stringa, 1, pos - 1)),
         riga2 = trimws(substr(formula_stringa, pos, nchar(formula_stringa))))
  }
  
  simbolo_automatico_pedice <- function(nome) {
    if (nome %in% names(GRECO_HTML)) return(nome)
    nomi_greci_minuscoli <- names(GRECO_HTML)[names(GRECO_HTML) == tolower(names(GRECO_HTML))]
    if (tolower(nome) %in% nomi_greci_minuscoli) return(tolower(nome))
    m <- regmatches(nome, regexec("^([A-Za-z]+)([0-9]+)$", nome))[[1]]
    if (length(m) == 3) {
      base <- m[2]; pedice <- m[3]
      base_finale <- if (tolower(base) %in% nomi_greci_minuscoli) tolower(base) else base
      return(paste0(base_finale, "[", pedice, "]"))
    }
    nome
  }
  
  # Resolves the display symbol for a parameter, falling back to its raw name
  # if no custom symbol has been defined for it.
  simbolo_visualizzazione <- function(nome_parametro) {
    mappa <- simboli_parametri()
    if (!is.null(mappa[[nome_parametro]])) mappa[[nome_parametro]] else simbolo_automatico_pedice(nome_parametro)
  }
  
  # Builds a plotmath legend from a vector of parameter
  # names, applying their Display Symbols (if defined). If no
  # special symbol is defined for any of them, it simply returns
  # the original text vector (no difference with respect
  # to before); otherwise it builds a true mixed expression() object
  # (plain text + plotmath notation), which legend()/plot() already know
  # how to interpret correctly element by element.
  costruisci_legenda_simboli <- function(nomi_parametri) {
    etichette <- lapply(nomi_parametri, function(n) interpreta_etichetta(simbolo_visualizzazione(n)))
    if (all(sapply(etichette, is.character))) {
      unlist(etichette)
    } else {
      do.call(expression, etichette)
    }
  }
  
  # ---- HTML rendering of parameter symbols in real tables ----
  # Plotmath (used for graphics/plots) is a DIFFERENT rendering engine than
  # HTML, and doesn't apply inside a renderTable() output - this is a
  # separate, purpose-built translator from the same "plotmath-like" typed
  # syntax (e.g. "mu[max]", "sigma^2") into safe HTML markup, used only for
  # the Parameter Estimation Results table.
  GRECO_HTML <- c(
    alpha = "\u03b1", beta = "\u03b2", gamma = "\u03b3", delta = "\u03b4", epsilon = "\u03b5",
    zeta = "\u03b6", eta = "\u03b7", theta = "\u03b8", iota = "\u03b9", kappa = "\u03ba",
    lambda = "\u03bb", mu = "\u03bc", nu = "\u03bd", xi = "\u03be", pi = "\u03c0",
    rho = "\u03c1", sigma = "\u03c3", tau = "\u03c4", upsilon = "\u03c5", phi = "\u03c6",
    chi = "\u03c7", psi = "\u03c8", omega = "\u03c9",
    Gamma = "\u0393", Delta = "\u0394", Theta = "\u0398", Lambda = "\u039b", Xi = "\u039e",
    Pi = "\u03a0", Sigma = "\u03a3", Upsilon = "\u03a5", Phi = "\u03a6", Psi = "\u03a8", Omega = "\u03a9"
  )
  
  # Escapes HTML-meaningful characters. Applied to EVERY piece of raw text
  # before it's placed inside constructed HTML, so nothing typed by the user
  # ever ends up as literal, unescaped HTML in the page - only the specific
  # <sub>/<sup> tags WE build ourselves below are ever emitted unescaped.
  escape_html <- function(testo) {
    testo <- gsub("&", "&amp;", testo, fixed = TRUE)
    testo <- gsub("<", "&lt;", testo, fixed = TRUE)
    testo <- gsub(">", "&gt;", testo, fixed = TRUE)
    testo
  }
  
  # Translates a single display-symbol string ("mu[max]", "sigma^2", "mu",
  # or plain text) into safe HTML. Anything not matching a recognized
  # pattern falls back to plain (HTML-escaped) text - same "safe by
  # default" philosophy as interpreta_etichetta() for plots.
  # Replaces EVERY parameter ACTUALLY present in the model (read
  # from its own "guess" field in the registry through parse_guesses, not a
  # generic recognition of Greek words in the text) with its
  # correct HTML symbol - uses the SAME registry mapping
  # (simbolo_visualizzazione, with the same automatic fallback for
  # Greek letters written in uppercase and numeric subscripts) already used for the
  # Fitted Model Equation, so sidebar, selection cards and equation
  # after the fit are always consistent with each other instead of using
  # different, unconnected mechanisms (the original problem: a parameter
  # such as "L", mapped to "lambda" ONLY in the registry of that specific
  # model, was never recognized by a generic
  # search for Greek words already spelled out in the text).
  abbellisci_formula_html <- function(id_modello) {
    info_modello <- MODEL_REGISTRY[[id_modello]]
    if (is.null(info_modello) || is.null(info_modello$display)) return("")
    testo <- info_modello$display
    if (is.null(info_modello$guess)) return(escape_html(testo))
    
    guesses_raw <- tryCatch(parse_guesses(info_modello$guess), error = function(e) NULL)
    if (is.null(guesses_raw) || length(guesses_raw$tutti_nomi) == 0) return(escape_html(testo))
    
    # Symbol mapping OF THIS SPECIFIC MODEL (id_modello), read
    # directly from the registry - NOT through simbolo_visualizzazione(),
    # which instead reads simboli_parametri() (the state of the model
    # CURRENTLY selected in the sidebar). For the "Choose a Model" popup,
    # which generates a card for EVERY model (not only the current one),
    # using simbolo_visualizzazione() would apply the wrong mapping
    # (or an empty one) to all the cards other than that of the model already chosen -
    # exactly the reason why "L" remained unchanged in the popup: the
    # L->lambda mapping of the CURRENT model was ignored for every
    # OTHER model of the list, which does not necessarily share that same
    # naming convention.
    # as.list() is necessary: $simboli in the registry is always a named
    # vector (created with c(...), never list()) - on a vector, [[ with an
    # absent name throws an error ("subscript out of bounds") instead of
    # returning NULL as a list would.
    mappa_propria <- as.list(info_modello$simboli)
    
    # Decreasing order of length, to avoid a shorter name
    # (e.g. "N") being replaced BEFORE a longer one that contains it
    # (e.g. "N0"), corrupting the subsequent replacement.
    nomi_parametri <- guesses_raw$tutti_nomi[order(-nchar(guesses_raw$tutti_nomi))]
    
    testo_escaped <- escape_html(testo)
    for (nome in nomi_parametri) {
      simbolo <- if (!is.null(mappa_propria) && !is.null(mappa_propria[[nome]])) mappa_propria[[nome]] else simbolo_automatico_pedice(nome)
      simbolo_html <- simbolo_a_html(simbolo)
      testo_escaped <- gsub(paste0("\\b", nome, "\\b"), simbolo_html, testo_escaped)
    }
    gsub("\\*", "&times;", testo_escaped)
  }
  
  simbolo_a_html <- function(testo) {
    if (is.null(testo) || nchar(trimws(testo)) == 0) return(testo)
    
    m_sub <- regmatches(testo, regexec("^([A-Za-z]+)\\[([^]]+)\\]$", testo))[[1]]
    if (length(m_sub) == 3) {
      base <- m_sub[2]; pedice <- m_sub[3]
      base_html <- if (base %in% names(GRECO_HTML)) GRECO_HTML[[base]] else escape_html(base)
      return(paste0(base_html, "<sub>", escape_html(pedice), "</sub>"))
    }
    
    m_sup <- regmatches(testo, regexec("^([A-Za-z]+)\\^\\{?([^}]+)\\}?$", testo))[[1]]
    if (length(m_sup) == 3) {
      base <- m_sup[2]; apice <- m_sup[3]
      base_html <- if (base %in% names(GRECO_HTML)) GRECO_HTML[[base]] else escape_html(base)
      return(paste0(base_html, "<sup>", escape_html(apice), "</sup>"))
    }
    
    if (testo %in% names(GRECO_HTML)) return(GRECO_HTML[[testo]])
    
    escape_html(testo)
  }
  
  # Translates a symbol into PLAIN Unicode text (no HTML markup, no
  # plotmath syntax) - for the contexts that support neither one nor
  # the other: persp() (official documentation: "expressions are not
  # accepted" for xlab/ylab/zlab) and HTML drop-down menus (the text inside
  # <option> never interprets markup). Greek letters become the real
  # Unicode character (no markup is needed for that); numeric subscripts
  # become Unicode subscript digits (e.g. "N[0]" -> "N\u2080"); non-numeric
  # subscripts (e.g. "max") have no real Unicode equivalent, so
  # they fall back to a readable underscore only for the letters without a
  # real dedicated Unicode subscript (e.g. "mu[b...]" with uncovered letters).
  CIFRE_PEDICE <- c("0"="\u2080","1"="\u2081","2"="\u2082","3"="\u2083","4"="\u2084",
                     "5"="\u2085","6"="\u2086","7"="\u2087","8"="\u2088","9"="\u2089")
  # Unicode has dedicated subscripts only for 17 lowercase Latin letters out of 26
  # (b,c,d,f,g,q,w,y,z are missing) - for these the fallback remains the
  # underscore. E.g. "max" (m,a,x all covered) -> real subscript "\u2098\u2090\u2093".
  LETTERE_PEDICE <- c(a="\u2090", e="\u2091", h="\u2095", i="\u1d62", j="\u2c7c",
                       k="\u2096", l="\u2097", m="\u2098", n="\u2099", o="\u2092",
                       p="\u209a", r="\u1d63", s="\u209b", t="\u209c", u="\u1d64",
                       v="\u1d65", x="\u2093")
  
  simbolo_a_testo_semplice <- function(testo) {
    if (is.null(testo) || nchar(trimws(testo)) == 0) return(testo)
    
    m_sub <- regmatches(testo, regexec("^([A-Za-z]+)\\[([^]]+)\\]$", testo))[[1]]
    if (length(m_sub) == 3) {
      base <- m_sub[2]; pedice <- m_sub[3]
      base_txt <- if (base %in% names(GRECO_HTML)) GRECO_HTML[[base]] else base
      if (grepl("^[0-9]+$", pedice)) {
        cifre <- strsplit(pedice, "")[[1]]
        return(paste0(base_txt, paste0(CIFRE_PEDICE[cifre], collapse = "")))
      }
      if (grepl("^[A-Za-z]+$", pedice)) {
        lettere <- strsplit(tolower(pedice), "")[[1]]
        # If EVERY letter has a real Unicode subscript, it uses that (e.g. "max" ->
        # real subscript); if even a single letter is not covered (e.g. "b",
        # "c"...), it falls back to the underscore for the whole word instead of
        # a "mixed" result (partly real subscript, partly not) that would be
        # visually inconsistent.
        if (all(lettere %in% names(LETTERE_PEDICE))) {
          return(paste0(base_txt, paste0(LETTERE_PEDICE[lettere], collapse = "")))
        }
      }
      return(paste0(base_txt, "_", pedice))
    }
    
    m_sup <- regmatches(testo, regexec("^([A-Za-z]+)\\^\\{?([^}]+)\\}?$", testo))[[1]]
    if (length(m_sup) == 3) {
      base <- m_sup[2]; apice <- m_sup[3]
      base_txt <- if (base %in% names(GRECO_HTML)) GRECO_HTML[[base]] else base
      return(paste0(base_txt, "^", apice))
    }
    
    if (testo %in% names(GRECO_HTML)) return(GRECO_HTML[[testo]])
    
    testo
  }
  
  # ---- Enriched, plotmath-rendered model formula ----
  # Builds an R language object (usable as a plot title/label) from the raw
  # formula string, substituting each parameter's raw name with its Display
  # Symbol (if one is defined) before parsing. Layered fallback: if the
  # substituted version fails to parse (e.g. a malformed custom symbol), try
  # the raw formula instead; if even that fails, return NULL (caller falls
  # back to plain text).
  costruisci_testo_formula_sostituita <- function(res) {
    if (is.null(res) || !isTRUE(res$successo) || is.null(res$formula)) return(NULL)
    
    nomi_parametri <- names(res$parametri)
    if (!is.null(res$fissi) && length(res$fissi) > 0) nomi_parametri <- c(nomi_parametri, names(res$fissi))
    # Sorts by decreasing length: replaces the longest names first,
    # so a name like "A0" is not spoiled by a replacement made
    # earlier on "A" alone.
    nomi_parametri <- nomi_parametri[order(-nchar(nomi_parametri))]
    
    mappa_propria <- if (!is.null(res$tipo_modello_usato)) as.list(MODEL_REGISTRY[[res$tipo_modello_usato]]$simboli) else NULL
    
    formula_sostituita <- res$formula
    # R's plotmath engine natively recognizes the words "gamma" and
    # "beta" as the corresponding Greek letters in ANY expression
    # parsed with str2expression(), regardless of the symbol
    # mapping above - a problem for the Gamma Distribution and the Beta
    # Distribution, where gamma(k)/beta(a,b) are the mathematical FUNCTIONS
    # (generalization of the factorial / Euler's Beta function), not
    # Greek letters. I enclose them in a literal string before
    # parsing, which plotmath draws as text instead of as a symbol -
    # only when the word is IMMEDIATELY followed by an opening
    # parenthesis (a true function call), so a model such as
    # Weibull, where "beta" is a genuine parameter written as a bare
    # word (never followed by a parenthesis), is not touched.
    formula_sostituita <- gsub("\\bgamma\\(", "\"Gamma\"(", formula_sostituita)
    formula_sostituita <- gsub("\\bbeta\\(", "\"Beta\"(", formula_sostituita)
    for (nome in nomi_parametri) {
      simbolo <- if (!is.null(mappa_propria) && !is.null(mappa_propria[[nome]])) mappa_propria[[nome]] else simbolo_automatico_pedice(nome)
      if (!identical(simbolo, nome)) {
        formula_sostituita <- gsub(paste0("\\b", nome, "\\b"), simbolo, formula_sostituita)
      }
    }
    formula_sostituita
  }
# ============================
# COMPUTATION ENGINE
# ============================
simulazione_dati <- reactive({
  # The dependency on valori_guess_correnti() (which reads the sliders of the
  # parameters) makes this reactive "live": it recomputes itself at every
  # movement of a slider, or at the click of "Load Current Sidebar Guesses",
  # without needing to press any separate "Simulate" button.
  valori_correnti <- valori_guess_correnti()
  if (is.null(valori_correnti)) {
    return(list(successo = FALSE, messaggio = "Click \u201cLoad Current Sidebar Guesses\u201d above first."))
  }
  
  formula_stringa <- costruisci_formula(input$tipo_modello, input$formula_custom)
  guesses_raw <- tryCatch(parse_guesses(input$guess_iniziali), error = function(e) {
    return(list(successo = FALSE, messaggio = paste("Parameter Error:", e$message)))
  })
  if (is.list(guesses_raw) && !is.null(guesses_raw$successo) && !guesses_raw$successo) return(guesses_raw)
  fissi <- guesses_raw$fissi
  if (!valida_formula(formula_stringa, guesses_raw$tutti_nomi)) {
    return(list(successo = FALSE, messaggio = "Security Error: Invalid formula or undeclared parameter names detected."))
  }
  
  df_punti <- tryCatch(dati(), error = function(e) NULL)
  valori_x_base <- if (!is.null(df_punti) && nrow(df_punti) > 0) df_punti$x else c(0, 10)
  limiti_x <- calcola_limiti(input$range_x_min_sim, input$range_x_max_sim, valori_x_base)
  x_griglia <- seq(limiti_x[1], limiti_x[2], length.out = 300)
  
  y_griglia <- tryCatch({
    env <- as.list(c(valori_correnti, fissi))
    env$x <- x_griglia
    res_y <- eval(parse(text = formula_stringa), envir = env)
    if (any(!is.finite(res_y))) stop("Mathematical calculation yielded non-finite values (Inf / NaN).")
    res_y
  }, error = function(e) {
    return(list(successo = FALSE, messaggio = paste("Mathematical Model Error:", e$message)))
  })
  if (is.list(y_griglia) && !is.null(y_griglia$successo) && !y_griglia$successo) return(y_griglia)
  
  return(list(successo = TRUE, x = x_griglia, y = y_griglia, formula = formula_stringa, punti_exp = df_punti))
})

elaborazione <- eventReactive(input$esegui, {
  # Does not run the fit if the button was pressed while on the
  # Batch Elaboration tab (where this same button makes no
  # sense, since that tab has its own "Run Batch Elaboration" on
  # completely different data) - it really prevents the execution, it does not only warn,
  # so a click there does not accidentally overwrite the results of the single
  # fit already computed with wrong data.
  if (identical(input$main_tabs, "tab_batch")) {
    return(list(successo = FALSE, messaggio = "This button doesn't run anything on the Batch Elaboration tab. Use 'Run Batch Elaboration' instead."))
  }
  df <- dati()
  # The RMSLE is defined only for non-negative values: the observed
  # (and predicted) values below zero are treated as 0 in the computation of the loss.
  # Previously this happened silently: now the user is warned.
  if (identical(input$tipo_loss, "rmsle") && !is.null(df) && any(df$y < 0, na.rm = TRUE)) {
    showNotification(sprintf("RMSLE is defined only for non-negative values: %d observed value(s) below zero are treated as 0 in the loss.", sum(df$y < 0, na.rm = TRUE)), type = "warning", duration = 10)
  }
  if (nrow(df) < 3) {
    showNotification("✗ Optimization Failed: Insufficient data for complete diagnostic calculations (at least 3 data points required).", type = "error", duration = 8)
    return(list(successo = FALSE, messaggio = "Insufficient data for complete diagnostic calculations."))
  }
  
  guesses_raw <- tryCatch(parse_guesses(input$guess_iniziali), error = function(e) e)
  if (inherits(guesses_raw, "error")) {
    showNotification(paste("✗ Optimization Failed: Error parsing initial guesses:", conditionMessage(guesses_raw)), type = "error", duration = 8)
    return(list(successo = FALSE, messaggio = paste("Error parsing initial guesses:", conditionMessage(guesses_raw))))
  }
  guesses <- guesses_raw$guess
  fissi <- guesses_raw$fissi
  limiti_inferiori <- guesses_raw$lower
  limiti_superiori <- guesses_raw$upper
  p <- length(guesses)
  if (nrow(df) <= p) {
    msg <- paste0("Not enough data points (", nrow(df), ") for the number of free parameters being estimated (", p,
                  "). At least ", p + 1, " data points are required so the residual degrees of freedom (n - p) stay positive.")
    showNotification(paste("✗ Optimization Failed:", msg), type = "error", duration = 8)
    return(list(successo = FALSE, messaggio = msg))
  }
  formula_stringa <- costruisci_formula(input$tipo_modello, input$formula_custom)
  if (!valida_formula(formula_stringa, guesses_raw$tutti_nomi)) {
    showNotification("✗ Optimization Failed: Invalid or unsafe formula.", type = "error", duration = 8)
    return(list(successo = FALSE, messaggio = "Invalid or unsafe formula."))
  }
  
  maxiter_scelto <- if (is.null(input$maxiter_ottimizzazione) || is.na(input$maxiter_ottimizzazione) || input$maxiter_ottimizzazione <= 0) 200 else input$maxiter_ottimizzazione
  # Server-side safety constraint: min/max of numericInput are only
  # HTML hints, they do not prevent manually typing a value
  # out of range. An extreme maxiter, especially combined with many Monte Carlo
  # iterations, would risk making the computation impractically slow.
  maxiter_scelto <- min(max(maxiter_scelto, 50), 2000)
  algoritmo <- algoritmo_effettivo(input$algoritmo, input$tipo_loss)
  esponente_tol <- esponente_tolleranza(input$esponente_tolleranza, algoritmo)
  tolleranza <- 10^esponente_tol
  accetta_non_conv <- isTRUE(input$accetta_non_convergenti)
  # Nelder-Mead restarts (checkbox in section 5, on by default).
  ripartenze_nm <- !isFALSE(input$nm_ripartenze)
  ripartenze_usate <- NULL
  
  # ---- Weighted regression (least squares only, MSE loss) ----
  # Weights w_i = 1/yhat_i^zeta, variance model var(y) = sigma^2 f^zeta,
  # estimated with iteratively reweighted least squares (further below). zeta
  # from the user (1, 2 or a value), or zeta = 2b from the replicates (same
  # computation as the SD vs mean plot). Without weights pesi_radice stays NULL and
  # the computation is identical to the usual one.
  schema_pesi <- if (is.null(input$ponderazione)) "nessuna" else input$ponderazione
  pond <- list(attiva = FALSE, schema = "nessuna", zeta = 0)
  pesi_radice <- NULL; pesi <- NULL
  if (!identical(schema_pesi, "nessuna")) {
    if (!identical(input$tipo_loss, "mse")) {
      showNotification(paste0("Weighting applies only to least squares (MSE loss): it is ignored with the ", toupper(input$tipo_loss), " loss."), type = "warning", duration = 8)
    } else {
      stima_b <- NULL
      zeta <- switch(schema_pesi, zeta1 = 1, zeta2 = 2,
                     personalizzato = suppressWarnings(as.numeric(input$ponderazione_zeta)),
                     repliche = { stima_b <- stima_potenza_varianza(df$x, df$y); if (isTRUE(stima_b$disponibile)) 2 * stima_b$b else NA_real_ },
                     NA_real_)
      if (length(zeta) != 1 || !is.finite(zeta)) {
        msg <- if (identical(schema_pesi, "repliche")) paste0("Weighting: zeta cannot be estimated from the replicates (", if (!is.null(stima_b$motivo)) stima_b$motivo else "not enough replicates", "). Choose a fixed zeta or no weighting.")
               else "Weighting: enter a valid value of zeta."
        showNotification(paste("\u2717 Optimization Failed:", msg), type = "error", duration = 10)
        return(list(successo = FALSE, messaggio = msg))
      }
      pond <- list(attiva = TRUE, schema = schema_pesi, zeta = zeta,
                   b = if (!is.null(stima_b)) stima_b$b else NA_real_, b_ci = if (!is.null(stima_b)) stima_b$ci else c(NA_real_, NA_real_))
    }
  }
  
  valuta_modello <- function(parametri, x) {
    env <- as.list(c(parametri, fissi))
    env$x <- x
    eval(parse(text = formula_stringa), envir = env)
  }
  
  calcola_loss_personalizzata <- function(parametri, x, y) {
    y_pred <- valuta_modello(parametri, x)
    if (any(!is.finite(y_pred))) return(1e10) 
    errori <- y - y_pred
    res_loss <- switch(input$tipo_loss,
                       "mse" = if (is.null(pesi_radice)) sum(errori^2, na.rm = TRUE) else sum((pesi_radice * errori)^2, na.rm = TRUE),
                       "mae" = sum(abs(errori), na.rm = TRUE),
                       "huber" = {
                         delta <- 1.345 * mad(errori, na.rm = TRUE) 
                         if(is.na(delta) || delta == 0) delta <- 1.0
                         condizione <- abs(errori) <= delta
                         sum(ifelse(condizione, 0.5 * (errori^2), delta * (abs(errori) - 0.5 * delta)), na.rm = TRUE)
                       },
                       "log10cosh" = {
                         log_cosh <- ifelse(abs(errori) < 20, log(cosh(errori)), abs(errori) - log(2))
                         sum(log_cosh / log(10), na.rm = TRUE)
                       },
                       "rmsle" = {
                         y_safe <- ifelse(y < 0, 0, y)
                         y_pred_safe <- ifelse(y_pred < 0, 0, y_pred)
                         sum((log1p(y_safe) - log1p(y_pred_safe))^2, na.rm = TRUE)
                       }
    )
    return(res_loss)
  }
  
  # Analytical Jacobian of the model (deriv(), numerical fallback if needed),
  # passed to Levenberg-Marquardt and used for the covariance. The residual is
  # y - f, so its Jacobian is -J; where the model is not finite the
  # residual equals a constant (1e5), so its Jacobian is zero.
  jacobiano_modello <- crea_jacobiano_modello(formula_stringa, names(guesses))
  jacobiano_residui_lm <- function(parametri, x, y) {
    J <- -jacobiano_modello(parametri, x, fissi)
    J[!is.finite(J)] <- 0
    if (!is.null(pesi_radice)) J <- J * pesi_radice
    J
  }
  
  residui_lm <- function(parametri, x, y) {
    y_pred <- valuta_modello(parametri, x)
    if (any(!is.finite(y_pred))) return(rep(1e5, length(y))) 
    if (is.null(pesi_radice)) y - y_pred else pesi_radice * (y - y_pred)
  }
  
  fit_successo <- FALSE
  parametri_ottimi <- NULL
  hessiano_finale <- NULL
  messaggio_stato <- ""
  iterazioni <- NA
  
  convergenza_vera <- TRUE
  tryCatch({
    if (algoritmo == "LM" && input$tipo_loss == "mse") {
      fit <- nls.lm(par = guesses, fn = residui_lm, jac = jacobiano_residui_lm, x = df$x, y = df$y,
                    lower = limiti_inferiori, upper = limiti_superiori,
                    control = controllo_lm(maxiter_scelto, length(guesses), tolleranza))
      parametri_ottimi <- fit$par
      hessiano_finale <- fit$hessian
      iterazioni <- fit$niter
      # info %in% 1:4 = true convergence reached (one of the ftol/ptol/gtol criteria
      # met); info == 5 or negative = iteration limit reached
      # without really converging (MINPACK still returns the best estimate
      # found, but it is not guaranteed to be the true minimum).
      convergenza_vera <- fit$info %in% 1:4
      if (convergenza_vera) {
        fit_successo <- TRUE
        messaggio_stato <- "Levenberg-Marquardt optimization successfully completed."
      } else if (accetta_non_conv) {
        fit_successo <- TRUE
        messaggio_stato <- paste0("Levenberg-Marquardt did NOT fully converge (info=", fit$info, "), but results are shown because \"Accept non-converged results\" is enabled. These estimates may not be a true minimum.")
      } else {
        messaggio_stato <- paste0("Levenberg-Marquardt did not fully converge within the iteration limit (info=", fit$info, "). Try different initial guesses, add boundaries, switch algorithm, increase Max Iterations, or enable \"Accept non-converged results\" if you understand the risk.")
      }
    } else if (algoritmo == "L-BFGS-B") {
      fit <- optim(par = guesses, fn = calcola_loss_personalizzata, x = df$x, y = df$y, 
                   method = "L-BFGS-B", lower = limiti_inferiori, upper = limiti_superiori, hessian = TRUE,
                   control = controllo_optim("L-BFGS-B", maxiter_scelto, guesses, tolleranza))
      parametri_ottimi <- fit$par
      hessiano_finale <- fit$hessian
      iterazioni <- fit$counts["function"]
      convergenza_vera <- fit$convergence == 0
      if (convergenza_vera) {
        fit_successo <- TRUE
        messaggio_stato <- "Optimization successfully completed via: L-BFGS-B"
      } else if (accetta_non_conv) {
        fit_successo <- TRUE
        messaggio_stato <- paste0("L-BFGS-B did NOT fully converge (code=", fit$convergence, "), but results are shown because \"Accept non-converged results\" is enabled. These estimates may not be a true minimum.")
      } else {
        messaggio_stato <- paste("Optimization failed to converge. Error code:", fit$convergence, "- try increasing Max Iterations or enabling \"Accept non-converged results\".")
      }
    } else {
      fit <- optim_con_ripartenze(par = guesses, fn = calcola_loss_personalizzata, x = df$x, y = df$y, method = algoritmo, hessian = TRUE,
                   control = controllo_optim(algoritmo, maxiter_scelto, guesses, tolleranza), ripartenze = ripartenze_nm)
      ripartenze_usate <- fit$ripartenze
      parametri_ottimi <- fit$par
      hessiano_finale <- fit$hessian
      iterazioni <- fit$counts["function"]
      convergenza_vera <- fit$convergence == 0
      if (convergenza_vera) {
        fit_successo <- TRUE
        messaggio_stato <- paste("Optimization successfully completed via:", algoritmo)
      } else if (accetta_non_conv) {
        fit_successo <- TRUE
        messaggio_stato <- paste0(algoritmo, " did NOT fully converge (code=", fit$convergence, "), but results are shown because \"Accept non-converged results\" is enabled. These estimates may not be a true minimum.")
      } else {
        messaggio_stato <- paste("Optimization failed to converge. Error code:", fit$convergence, "- try increasing Max Iterations or enabling \"Accept non-converged results\".")
      }
    }
  }, error = function(e) { messaggio_stato <<- paste("Error:", e$message) })
  
  if (!fit_successo || is.null(parametri_ottimi)) {
    showNotification(paste("✗ Optimization Failed:", messaggio_stato), type = "error", duration = 10)
    return(list(successo = FALSE, messaggio = messaggio_stato))
  }
  
  # Iteratively reweighted least squares: starting from the unweighted fit, the
  # weights 1/yhat^zeta are computed, the model is refitted with fixed weights and this is repeated until
  # the relative change of the parameters falls below 1e-9 (at most 30 cycles).
  # The final weights, computed from the final fit, remain fixed for inference.
  iterazioni_irls <- 0
  if (pond$attiva) {
    esegui_fit_pesato <- function(partenza) tryCatch({
      if (algoritmo == "LM") {
        f <- nls.lm(par = partenza, fn = residui_lm, jac = jacobiano_residui_lm, x = df$x, y = df$y, lower = limiti_inferiori, upper = limiti_superiori,
                    control = controllo_lm(maxiter_scelto, length(partenza), tolleranza))
        list(par = f$par, iter = f$niter, conv = f$info %in% 1:4)
      } else if (algoritmo == "L-BFGS-B") {
        f <- optim(par = partenza, fn = calcola_loss_personalizzata, x = df$x, y = df$y, method = "L-BFGS-B", lower = limiti_inferiori, upper = limiti_superiori,
                   control = controllo_optim("L-BFGS-B", maxiter_scelto, partenza, tolleranza))
        list(par = f$par, iter = f$counts["function"], conv = f$convergence == 0)
      } else {
        f <- optim_con_ripartenze(par = partenza, fn = calcola_loss_personalizzata, x = df$x, y = df$y, method = algoritmo,
                   control = controllo_optim(algoritmo, maxiter_scelto, partenza, tolleranza), ripartenze = ripartenze_nm)
        list(par = f$par, iter = f$counts["function"], conv = f$convergence == 0)
      }
    }, error = function(e) NULL)
    fallisci_pesi <- function(msg) {
      showNotification(paste("✗ Optimization Failed:", msg), type = "error", duration = 10)
      list(successo = FALSE, messaggio = msg)
    }
    msg_positivi <- "Weighting 1/\u0177^\u03b6 requires positive predicted values at all data points; this model gives zero or negative predictions. Use no weighting."
    variazione <- Inf
    for (ciclo in 1:30) {
      y_corrente <- valuta_modello(parametri_ottimi, df$x)
      if (any(!is.finite(y_corrente)) || any(y_corrente <= 0)) return(fallisci_pesi(msg_positivi))
      pesi_radice <- sqrt(1 / y_corrente^pond$zeta)
      f <- esegui_fit_pesato(parametri_ottimi)
      if (is.null(f)) return(fallisci_pesi("the weighted fit failed. Try different initial guesses or no weighting."))
      variazione <- max(abs(f$par - parametri_ottimi) / pmax(abs(parametri_ottimi), 1e-12))
      parametri_ottimi <- f$par; iterazioni <- f$iter; convergenza_vera <- isTRUE(f$conv); iterazioni_irls <- ciclo
      if (is.finite(variazione) && variazione < 1e-9) break
    }
    y_corrente <- valuta_modello(parametri_ottimi, df$x)
    if (any(!is.finite(y_corrente)) || any(y_corrente <= 0)) return(fallisci_pesi(msg_positivi))
    pesi <- 1 / y_corrente^pond$zeta; pesi_radice <- sqrt(pesi)
    if (!convergenza_vera && !accetta_non_conv) return(fallisci_pesi("the weighted fit did not fully converge. Try different initial guesses, increase Max Iterations, or enable \"Accept non-converged results\"."))
    if (!is.finite(variazione) || variazione >= 1e-6) showNotification(sprintf("Weighting: the weights did not fully stabilize after %d reweighting cycles (relative change %.1e).", iterazioni_irls, variazione), type = "warning", duration = 10)
    pond$iterazioni_irls <- iterazioni_irls
  }
  
  limiti_x_griglia <- calcola_limiti(input$range_x_min, input$range_x_max, df$x)
  x_griglia_estesa <- seq(limiti_x_griglia[1], limiti_x_griglia[2], length.out = 200)
  
  n <- length(df$x)
  df_residual <- n - p
  y_pred <- valuta_modello(parametri_ottimi, df$x)
  residui_vettore <- df$y - y_pred
  
  sse <- sum(residui_vettore^2, na.rm = TRUE)
  sst <- sum((df$y - mean(df$y, na.rm = TRUE))^2, na.rm = TRUE)
  mse <- sse / df_residual
  rmse <- sqrt(mse)
  
  media_y_osservata <- mean(df$y, na.rm = TRUE)
  cv_rmse <- ifelse(media_y_osservata != 0, (rmse / media_y_osservata) * 100, NA)
  
  r_corr <- tryCatch(cor(df$y, y_pred, use = "complete.obs"), error = function(e) NA)
  r2 <- ifelse(sst > 0, 1 - (sse / sst), NA)
  r2_adj <- ifelse(sst > 0 && df_residual > 0, 1 - ((1 - r2) * (n - 1) / df_residual), NA)
  
  ic <- criteri_informazione(sse, n, p, input$tipo_loss)
  aic <- ic$aic; aicc <- ic$aicc; bic <- ic$bic
  # With weights: weighted sum of squares (SSE_w), sigma = sqrt(SSE_w/(n-p)),
  # weighted R^2 with respect to the weighted mean, criteria with the term sum(ln w).
  # CV(RMSE) makes no sense with a relative sigma and is not reported.
  if (pond$attiva) {
    sse <- sum(pesi * residui_vettore^2, na.rm = TRUE)
    media_pesata <- sum(pesi * df$y) / sum(pesi)
    sst <- sum(pesi * (df$y - media_pesata)^2)
    mse <- sse / df_residual; rmse <- sqrt(mse); cv_rmse <- NA
    r2 <- ifelse(sst > 0, 1 - (sse / sst), NA)
    r2_adj <- ifelse(sst > 0 && df_residual > 0, 1 - ((1 - r2) * (n - 1) / df_residual), NA)
    ic <- criteri_informazione(sse, n, p, input$tipo_loss, sum(log(pesi)))
    aic <- ic$aic; aicc <- ic$aicc; bic <- ic$bic
  }
  
  errori_standard <- rep(NA, p)
  names(errori_standard) <- names(parametri_ottimi)
  errori_standard_bootstrap <- rep(NA, p)
  names(errori_standard_bootstrap) <- names(parametri_ottimi)
  matrice_cov <- matrix(0, nrow=p, ncol=p)
  matrice_curve_boot <- matrix(NA, nrow = 1, ncol = length(x_griglia_estesa))
  matrice_pred_boot <- matrix(NA, nrow = 1, ncol = length(x_griglia_estesa))
  matrice_boot_parametri <- NULL
  
  covarianza_problematica <- FALSE
  # "Classic" standard errors (Linear method): valid ONLY for least
  # squares. The formula s^2 (J^T J)^-1 derives from the SSE loss; with MAE,
  # Huber, log10cosh or RMSLE applying it (as was done before, on the Hessian
  # of the chosen loss) gave plausible but wrong numbers. With these losses
  # they are not computed: the Monte Carlo method is suggested, whose empirical
  # intervals are valid with any loss.
  errori_non_disponibili_per_loss <- !identical(input$tipo_loss, "mse")
  if (errori_non_disponibili_per_loss) {
    matrice_cov <- NULL
  } else if (!is.null(hessiano_finale)) {
    esito_cov <- try({
      if (algoritmo != "LM" || pond$attiva) {
        # Least squares with BFGS / L-BFGS-B / Nelder-Mead: covariance from the
        # Jacobian of the model, s^2 (J^T J)^-1, not from the numerical Hessian of
        # optim (see jacobiano_numerico in rendering_output.R). With weights,
        # for every algorithm: s^2 (J^T W J)^-1 with the weighted Jacobian.
        J <- jacobiano_modello(parametri_ottimi, df$x, fissi)
        if (pond$attiva) J <- J * pesi_radice
        matrice_cov <- mse * inverti_hessiana(crossprod(J))
      } else {
        # Levenberg-Marquardt: minpack.lm already returns J^T J.
        matrice_cov <- mse * inverti_hessiana(hessiano_finale)
      }
      errori_standard <- sqrt(diag(matrice_cov))
    }, silent = TRUE)
    # The message for the user is given together with the one on convergence,
    # further below, so as not to show two contradictory notifications.
    covarianza_problematica <- inherits(esito_cov, "try-error") || any(!is.finite(errori_standard))
  } else {
    matrice_cov <- NULL
  }
  # Never return an invalid covariance: previously the initial matrix of
  # zeros remained (or one with negative variances), and the downstream plots
  # used it, drawing confidence bands of zero width, null intervals
  # in Inverse Prediction and invalid correlations. NULL is handled by
  # all of them (bands, correlation, Inverse Prediction, Shelf-Life).
  if (covarianza_problematica || errori_non_disponibili_per_loss) {
    matrice_cov <- NULL
    errori_standard[] <- NA
  }
  
  sigma_mc_usato <- NA
  n_boot_successo <- NA
  n_boot_totale <- NA
  if (input$metodo_errore == "monte_carlo") {
    n_sim <- if (is.null(input$n_boot) || is.na(input$n_boot) || input$n_boot <= 0) 100 else input$n_boot
    # Same server-side safety constraint: the number of Monte Carlo
    # iterations is brought back within the range declared in the UI, even if
    # the user manually types an out-of-scale value.
    n_sim <- min(max(round(n_sim), 10), 5000)
    mat_boot <- matrix(NA, n_sim, p)
    matrice_curve_boot <- matrix(NA, nrow = n_sim, ncol = length(x_griglia_estesa))
    matrice_pred_boot <- matrix(NA, nrow = n_sim, ncol = length(x_griglia_estesa))
    
    if (input$tipo_rumore_mc == "gaussiano") {
      sigma_mc_usato <- if (is.null(input$sigma_gaussiano) || is.na(input$sigma_gaussiano) || input$sigma_gaussiano <= 0) rmse else input$sigma_gaussiano
    }
    # Residuals to be resampled (Davison & Hinkley, 1997; option on by default).
    residui_modificati_attivi <- is.null(input$residui_modificati) || isTRUE(input$residui_modificati)
    J_boot <- if (identical(input$tipo_loss, "mse")) tryCatch(jacobiano_modello(parametri_ottimi, df$x, fissi), error = function(e) NULL) else NULL
    # With weights: weighted residuals sqrt(w)(y - yhat) (constant variance) and leverages
    # from the weighted Jacobian; the extracted noise is then brought back to the scale
    # of each point by dividing by sqrt(w), i.e. multiplying by yhat^(zeta/2).
    if (pond$attiva && !is.null(J_boot)) J_boot <- J_boot * pesi_radice
    residui_boot <- residui_per_bootstrap(if (pond$attiva) residui_vettore * pesi_radice else residui_vettore, J_boot, residui_modificati_attivi)
    if (pond$attiva) { y_griglia_fit <- valuta_modello(parametri_ottimi, x_griglia_estesa); scala_griglia <- sqrt(ifelse(y_griglia_fit > 0, y_griglia_fit^pond$zeta, NA_real_)) }
    
    withProgress(message = 'Running Monte Carlo Simulations...', value = 0, {
      for(i in 1:n_sim) {
        rumore_campionato <- if (input$tipo_rumore_mc == "gaussiano") {
          rnorm(n, mean = 0, sd = sigma_mc_usato)
        } else {
          sample(residui_boot, replace=TRUE)
        }
        if (pond$attiva) rumore_campionato <- rumore_campionato / pesi_radice
        y_f <- y_pred + rumore_campionato
        try({
          if (algoritmo == "LM" && input$tipo_loss == "mse") {
            fit_boot <- nls.lm(par = parametri_ottimi, fn = residui_lm, jac = jacobiano_residui_lm, x = df$x, y = y_f,
                               lower = limiti_inferiori, upper = limiti_superiori,
                               control = controllo_lm(maxiter_scelto, length(parametri_ottimi), tolleranza))
            # Discards this iteration if it does not really converge, UNLESS
            # the user has explicitly chosen to accept non-converged
            # results (same choice applied to the main fit).
            if (!(fit_boot$info %in% 1:4) && !accetta_non_conv) stop("Bootstrap iteration did not converge within the iteration limit.")
            p_boot <- fit_boot$par
          } else if (algoritmo == "L-BFGS-B") {
            fit_boot <- optim(par = parametri_ottimi, fn = calcola_loss_personalizzata, x = df$x, y = y_f,
                              method = "L-BFGS-B", lower = limiti_inferiori, upper = limiti_superiori,
                              control = controllo_optim("L-BFGS-B", maxiter_scelto, parametri_ottimi, tolleranza))
            if (fit_boot$convergence != 0 && !accetta_non_conv) stop("Bootstrap iteration did not converge within the iteration limit.")
            p_boot <- fit_boot$par
          } else {
            fit_boot <- optim_con_ripartenze(par = parametri_ottimi, fn = calcola_loss_personalizzata, x = df$x, y = y_f, method = algoritmo,
                              control = controllo_optim(algoritmo, maxiter_scelto, parametri_ottimi, tolleranza), ripartenze = ripartenze_nm)
            if (fit_boot$convergence != 0 && !accetta_non_conv) stop("Bootstrap iteration did not converge within the iteration limit.")
            p_boot <- fit_boot$par
          }
          mat_boot[i,] <- p_boot
          y_linea_media <- valuta_modello(p_boot, x_griglia_estesa)
          matrice_curve_boot[i,] <- y_linea_media
          rumore_predittivo <- if (input$tipo_rumore_mc == "gaussiano") {
            rnorm(length(x_griglia_estesa), mean = 0, sd = sigma_mc_usato)
          } else {
            sample(residui_boot, length(x_griglia_estesa), replace=TRUE)
          }
          if (pond$attiva) rumore_predittivo <- rumore_predittivo * scala_griglia
          matrice_pred_boot[i,] <- y_linea_media + rumore_predittivo
        }, silent=TRUE)
        incProgress(1/n_sim)
      }
    })
    # BUG FIXED: previously this line overwrote errori_standard (the
    # same variable as the classic Hessian-based computation, lines
    # above), erasing its value every time Monte Carlo was the
    # chosen method - "Std Error"/"CI Parametric" in the results table,
    # the CSV/Excel export, and (more seriously) any
    # downstream use of res$errori in the Grid Search engine (t-plot,
    # profile trace) silently received the bootstrap SD
    # passed off as the classic value, instead of the true Hessian standard
    # error - verified by comparison with the NIST certified values
    # for the Rat43/Richards dataset: the classic value (16.302297817)
    # matched exactly BEFORE Monte Carlo overwrote it.
    # Now they are two distinct variables, neither overwrites the other.
    errori_standard_bootstrap <- apply(mat_boot, 2, sd, na.rm=TRUE)
    names(errori_standard_bootstrap) <- names(parametri_ottimi)
    colnames(mat_boot) <- names(parametri_ottimi)
    matrice_boot_parametri <- mat_boot
    # A row of mat_boot is either completely valid (all p parameters
    # written together in one go) or completely NA (failed
    # iteration: error caught by try() or non-converging fit
    # discarded) - so it is enough to check the first column to count the
    # iterations that actually succeeded.
    n_boot_successo <- sum(!is.na(mat_boot[, 1]))
    n_boot_totale <- n_sim
    if (n_boot_successo < MINIMO_ITERAZIONI_MC) {
      # Too few successful iterations: no Monte Carlo result. The
      # plot, the results table and the other sections automatically return
      # to the classic method (standard errors from the covariance).
      matrice_boot_parametri <- NULL
      matrice_curve_boot <- NULL
      matrice_pred_boot <- NULL
      errori_standard_bootstrap[] <- NA
      showNotification(paste0("Only ", n_boot_successo, " of ", n_boot_totale, " Monte Carlo iterations succeeded (at least ", MINIMO_ITERAZIONI_MC,
                              " are needed): Monte Carlo results are not shown", if (errori_non_disponibili_per_loss) "." else ", classic standard errors and bands are shown instead.",
                              " Try increasing Max Iterations, enabling \"Accept non-converged results\", or improving the initial guesses."),
                       type = "warning", duration = 12)
    }
  }
  
  valore_loss_finale <- calcola_loss_personalizzata(parametri_ottimi, df$x, df$y)
  # With Monte Carlo below the threshold only the warning given above applies (no
  # Monte Carlo result): no contradictory messages.
  mc_insufficiente <- identical(input$metodo_errore, "monte_carlo") && is.null(matrice_boot_parametri)
  if (errori_non_disponibili_per_loss && !mc_insufficiente) {
    if (identical(input$metodo_errore, "monte_carlo")) {
      showNotification(paste0("Classic (Jacobian-based) standard errors and parametric CIs are not shown with the ", toupper(input$tipo_loss),
                              " loss: that formula is valid only for least squares (MSE). The Monte Carlo (empirical) intervals are valid with any loss."),
                       type = "message", duration = 10)
    } else {
      showNotification(paste0("Standard errors are not computed with the ", toupper(input$tipo_loss),
                              " loss: the Jacobian-based formula is valid only for least squares (MSE). Select the Monte Carlo method to obtain standard errors and confidence intervals."),
                       type = "warning", duration = 12)
    }
  }
  if (convergenza_vera && !covarianza_problematica) {
    showNotification("✓ Modeling Successful! Parameter estimation and model convergence completed successfully.", type = "message", duration = 4)
  } else if (convergenza_vera && covarianza_problematica) {
    # NIST validation: from certain starting points (e.g. BoxBOD, MGH17 start 1)
    # the optimizer declares convergence at a degenerate point (flat
    # region, parameters not determinable) far from the true minimum; the
    # signal is precisely the singular covariance matrix.
    showNotification("⚠️ The optimizer reports convergence, but the covariance matrix is singular at this solution, so standard errors cannot be computed. This is often a degenerate point (e.g. a flat region where some parameters are not identifiable) rather than a proper minimum: try different initial guesses and check the fit visually.",
                     type = "warning", duration = 12)
  } else {
    showNotification("⚠️ Fit accepted WITHOUT full convergence (see warning in results). Interpret with caution.", type = "warning", duration = 8)
  }
  
  list(successo=TRUE, parametri=parametri_ottimi, errori=errori_standard, errori_bootstrap=errori_standard_bootstrap,
       formula=formula_stringa, valuta=valuta_modello, residui=residui_vettore, 
       x=df$x, y_pred=y_pred, cov=matrice_cov, sigma=rmse, 
       obs=n, df=df_residual, sse=sse, mse=mse, rmse=rmse, cv_rmse=cv_rmse,
       r_corr=r_corr, r2=r2, r2_adj=r2_adj, aic=aic, aicc=aicc, bic=bic, criteri_non_disponibili=!identical(input$tipo_loss, "mse"), iter=iterazioni,
       curve_boot=matrice_curve_boot, pred_boot=matrice_pred_boot,
       mat_boot_params=matrice_boot_parametri, residui_modificati=if (exists("residui_modificati_attivi")) residui_modificati_attivi else NA, loss_valore=valore_loss_finale, esponente_tolleranza=esponente_tol, 
       x_griglia=x_griglia_estesa, df_originale=df,
       tipo_rumore_mc=if(input$metodo_errore=="monte_carlo") input$tipo_rumore_mc else NA,
       sigma_mc=sigma_mc_usato, fissi=fissi, convergenza_vera=convergenza_vera,
       n_boot_successo=n_boot_successo, n_boot_totale=n_boot_totale,
       tipo_modello_usato=input$tipo_modello, ponderazione=pond, pesi=pesi,
       ripartenze_nm = if (identical(algoritmo, "Nelder-Mead")) list(attive = ripartenze_nm, usate = ripartenze_usate) else NULL)
})
# ============================
# OUTPUT RENDERING
# ============================
dpi_attivo <- function() {
  if (is.null(input$jpeg_dpi) || is.na(input$jpeg_dpi) || input$jpeg_dpi <= 0) 200 else input$jpeg_dpi
}

# Shared helper: reads the global "Export Width/Height (px)" fields (sidebar)
# and returns both the dimensions in pixels (used directly by jpeg(), whose
# default is units="px") and in inches (required by pdf(), which only
# accepts inches) using the current DPI as the conversion factor. If the
# fields aren't valid, it falls back to a 2000x1400px default.
dimensioni_esportazione <- function() {
  dpi <- dpi_attivo()
  larghezza_px <- if (is.null(input$export_width_px) || is.na(input$export_width_px) || input$export_width_px <= 0) 2000 else input$export_width_px
  altezza_px <- if (is.null(input$export_height_px) || is.na(input$export_height_px) || input$export_height_px <= 0) 1400 else input$export_height_px
  # Server-side safety limit: the min/max attributes of numericInput in the
  # UI are only HTML hints, they don't prevent manually typing an extreme
  # value. A user could type e.g. 1 million pixels, risking a huge memory
  # allocation inside the WASM sandbox (limited memory).
  larghezza_px <- min(larghezza_px, 10000)
  altezza_px <- min(altezza_px, 10000)
  list(width_px = larghezza_px, height_px = altezza_px,
       width_in = larghezza_px / dpi, height_in = altezza_px / dpi, dpi = dpi)
}

# ---- Combined image (several plots in a single grid figure) ----
# Palette shared by the overlay plots and by the panels of the single fits
# (Batch and Model Comparison): same list in all 4 places, so a
# sample has the same colour in the overlay plot and in its panel.
# The three "single color" options give the same colour to all series:
# designed for the combined image, where each series has its own panel and
# there is no need to distinguish them by colour (in the overlay plot they would
# instead be indistinguishable).
PALETTE_FISSA_SERIE <- c("#e74c3c", "#2980b9", "#27ae60", "#f39c12", "#8e44ad", "#16a085", "#c0392b", "#34495e")
COLORI_SINGOLI_SERIE <- c(nero = "#000000", grigio_scuro = "#404040", rosso = "#c0392b")
colori_da_palette <- function(tipo, n) {
  if (is.null(tipo)) tipo <- "fissa"
  if (tipo %in% names(COLORI_SINGOLI_SERIE)) return(rep(COLORI_SINGOLI_SERIE[[tipo]], n))
  switch(tipo,
    "rainbow" = rainbow(n),
    "viridis" = hcl.colors(n, palette = "viridis"),
    "plasma" = hcl.colors(n, palette = "plasma"),
    "cividis" = hcl.colors(n, palette = "cividis"),
    "spectral" = hcl.colors(n, palette = "spectral"),
    "heat" = hcl.colors(n, palette = "heat"),
    rep_len(PALETTE_FISSA_SERIE, n)
  )
}
SCELTE_PALETTE_SERIE <- c(
  "Fixed Palette (best for few series)" = "fissa", "Rainbow" = "rainbow", "Viridis" = "viridis", "Plasma" = "plasma",
  "Cividis" = "cividis", "Spectral" = "spectral", "Heat" = "heat",
  "Black (single color \u2014 for combined images)" = "nero",
  "Dark Grey (single color \u2014 for combined images)" = "grigio_scuro",
  "Red (single color \u2014 for combined images)" = "rosso"
)
# Colour of the symbols: equal to that of the curve (historical behaviour) or
# a fixed colour, independent of the palette of the curves.
SCELTE_COLORE_PUNTI <- c("Same as line" = "uguale", "Black" = "#000000", "Dark Grey" = "#404040", "Red" = "#c0392b")
colori_punti_serie <- function(scelta, colori_curve) {
  if (is.null(scelta) || identical(scelta, "uguale")) colori_curve else rep(scelta, length(colori_curve))
}

# Style of the panel letters (A / a / (a), bold / normal /
# italic) - returns text and font (1 normal, 2 bold, 3 italic).
etichetta_pannello <- function(i) {
  lettera <- if (i <= 26) letters[i] else paste0(letters[((i - 1) %/% 26)], letters[((i - 1) %% 26) + 1])
  stile <- if (is.null(input$comp_stile_lettere)) "maiusc_grassetto" else input$comp_stile_lettere
  switch(stile,
    "maiusc_normale" = list(testo = toupper(lettera), font = 1),
    "minusc_corsivo" = list(testo = lettera, font = 3),
    "parentesi_corsivo" = list(testo = paste0("(", lettera, ")"), font = 3),
    "parentesi_normale" = list(testo = paste0("(", lettera, ")"), font = 1),
    "parentesi_dx_corsivo" = list(testo = paste0(lettera, ")"), font = 3),
    "parentesi_dx_normale" = list(testo = paste0(lettera, ")"), font = 1),
    list(testo = toupper(lettera), font = 2)
  )
}
# Computes rows/columns of the grid according to the global settings in
# "3. Plot Export": Auto (as square as possible), fixed number of
# columns, or fixed number of rows.
griglia_composita <- function(n_pannelli) {
  n_pannelli <- max(1, n_pannelli)
  modo <- if (is.null(input$comp_modo_layout)) "auto" else input$comp_modo_layout
  valore_intero <- function(v, predefinito) if (is.null(v) || is.na(v) || v < 1) predefinito else as.integer(round(v))
  if (modo == "colonne") {
    n_col <- min(valore_intero(input$comp_n_colonne, 3), n_pannelli)
    n_righe <- ceiling(n_pannelli / n_col)
  } else if (modo == "righe") {
    n_righe <- min(valore_intero(input$comp_n_righe, 2), n_pannelli)
    n_col <- ceiling(n_pannelli / n_righe)
  } else {
    n_col <- ceiling(sqrt(n_pannelli))
    n_righe <- ceiling(n_pannelli / n_col)
  }
  # Avoids completely empty rows: filling by rows, the rows actually
  # used are ceiling(n / columns) (e.g. 4 plots with 3 fixed rows ->
  # 2 columns -> 2 rows are enough, the third would remain empty); by
  # columns, the same applies to the columns. Only rows/columns
  # that would remain completely empty are removed, never panels or occupied places.
  if (identical(input$comp_riempimento, "colonne")) n_col <- ceiling(n_pannelli / n_righe)
  else n_righe <- ceiling(n_pannelli / n_col)
  c(righe = n_righe, colonne = n_col)
}

# Draws n_pannelli plots (funzione_disegno(i), i = 1..n_pannelli) in
# a single grid image and writes it to 'file', in the format (PDF/JPEG)
# and DPI already chosen in the sidebar. Each panel has the size given in
# "Panel size" - the total image is columns x width by rows x
# height, reduced proportionally if it exceeds the safety limit of
# 10000 px per side (the same already applied to every other download).
crea_immagine_composita <- function(file, n_pannelli, funzione_disegno) {
  griglia <- griglia_composita(n_pannelli)
  dpi <- dpi_attivo()
  pannello_w <- if (is.null(input$comp_pannello_w_px) || is.na(input$comp_pannello_w_px) || input$comp_pannello_w_px < 100) 1000 else input$comp_pannello_w_px
  pannello_h <- if (is.null(input$comp_pannello_h_px) || is.na(input$comp_pannello_h_px) || input$comp_pannello_h_px < 100) 800 else input$comp_pannello_h_px
  totale_w <- griglia[["colonne"]] * pannello_w
  totale_h <- griglia[["righe"]] * pannello_h
  fattore <- min(1, 10000 / totale_w, 10000 / totale_h)
  totale_w <- round(totale_w * fattore)
  totale_h <- round(totale_h * fattore)
  
  if (identical(input$formato_esportazione, "pdf")) pdf(file, width = totale_w / dpi, height = totale_h / dpi)
  else jpeg(file, width = totale_w, height = totale_h, res = dpi, quality = 95)
  on.exit(dev.off(), add = TRUE)
  
  # Grid of HALF cells: each panel occupies 2 half columns (filling
  # by rows) or 2 half rows (by columns). It serves to centre the last
  # incomplete row: with m panels on c places, it shifts by (c - m) half
  # cells, leaving the same empty space on the left and on the right. E.g. 7
  # plots on 3 columns: the seventh goes to the centre of the third row instead
  # of to the left (with mfrow/mfcol this is not possible, they always fill
  # from the start).
  n_righe <- griglia[["righe"]]; n_col <- griglia[["colonne"]]
  per_colonne <- identical(input$comp_riempimento, "colonne")
  if (!per_colonne) {
    matrice <- matrix(0L, nrow = n_righe, ncol = 2 * n_col)
    for (i in seq_len(n_pannelli)) {
      riga <- (i - 1) %/% n_col + 1
      pos <- (i - 1) %% n_col
      nella_riga <- if (riga < n_righe) n_col else n_pannelli - (n_righe - 1) * n_col
      spostamento <- n_col - nella_riga
      matrice[riga, spostamento + 2 * pos + 1:2] <- i
    }
  } else {
    matrice <- matrix(0L, nrow = 2 * n_righe, ncol = n_col)
    for (i in seq_len(n_pannelli)) {
      colonna <- (i - 1) %/% n_righe + 1
      pos <- (i - 1) %% n_righe
      nella_colonna <- if (colonna < n_col) n_righe else n_pannelli - (n_col - 1) * n_righe
      spostamento <- n_righe - nella_colonna
      matrice[spostamento + 2 * pos + 1:2, colonna] <- i
    }
  }
  layout(matrice)
  # layout() can shrink the text like mfrow - here it is not needed, because
  # the image grows with the number of panels: each one has the same space
  # as a single plot, therefore the same text.
  par(cex = 1)
  mostra_lettere <- isTRUE(input$comp_lettere)
  pos_lettere <- if (is.null(input$comp_pos_lettere)) "fuori" else input$comp_pos_lettere
  cex_lettere <- if (is.null(input$comp_cex_lettere) || is.na(input$comp_cex_lettere)) 1.5 else input$comp_cex_lettere
  
  for (i in seq_len(n_pannelli)) {
    tryCatch(funzione_disegno(i), error = function(e) {
      plot(1, type = "n", axes = FALSE, xlab = "", ylab = "", main = paste("Panel", i, "could not be drawn"))
    })
    if (mostra_lettere) {
      et <- etichetta_pannello(i)
      vecchio_xpd <- par(xpd = NA)
      if (pos_lettere == "dentro_sx") {
        # Inside the plot area, top left corner
        text(grconvertX(0.03, "npc", "user"), grconvertY(0.97, "npc", "user"), et$testo, font = et$font, cex = cex_lettere, adj = c(0, 1))
      } else if (pos_lettere == "dentro_dx") {
        # Inside the plot area, top right corner
        text(grconvertX(0.97, "npc", "user"), grconvertY(0.97, "npc", "user"), et$testo, font = et$font, cex = cex_lettere, adj = c(1, 1))
      } else {
        # Outside the plot area: top left corner of the
        # PANEL, independent of the margins of each drawing function.
        text(grconvertX(0.02, "nfc", "user"), grconvertY(0.97, "nfc", "user"), et$testo, font = et$font, cex = cex_lettere, adj = c(0, 1))
      }
      par(vecchio_xpd)
    }
  }
  invisible(NULL)
}

# File name of the combined download, with the same format chosen in the sidebar.
nome_file_composito <- function(prefisso) paste0(prefisso, "_combined.", if (identical(input$formato_esportazione, "pdf")) "pdf" else "jpg")

# "Same axis ranges in every panel" control for the panels of the single
# fits (Batch, Model Comparison).
assi_condivisi_composito <- function() if (is.null(input$comp_assi_condivisi)) TRUE else isTRUE(input$comp_assi_condivisi)

# Swaps the x and y columns of a data.frame: "Swap X and Y" option in the
# Data Input of Single Fit and Batch, for data entered or loaded in reverse
# order (y, x instead of x, y). The other columns, if present, remain
# unchanged. It must be applied to the raw data, BEFORE any transformation
# (Y pre-transformation, Distribution Density), which act on y.
# ---- Numerically stable inversion of the Hessian matrix (or JtJ) ----
# The covariance matrix is derived from it, and hence the standard errors.
# With parameters on very different scales (e.g. NIST Bennett5: b1 ~ -2500, b3 ~
# 0.9) the matrix is ill-conditioned and solve() rejects it as
# "numerically singular" (reciprocal condition number 1.1e-17 for
# Bennett5, below R's threshold of ~2.2e-16): the standard errors remained
# empty. Here the matrix is first scaled to a unit diagonal, inverted,
# and brought back to the original scale: mathematically identical result,
# numerically stable (diagonal equilibration, a standard technique of
# numerical linear algebra). Verified: on Bennett5 it agrees to 8 digits with
# the independent method via QR decomposition of the Jacobian (the one of
# nls() in R); on Rat43, well conditioned, it is identical digit by digit to
# the direct solve(). If the diagonal is not positive or there are non-finite
# values, it falls back to the direct solve() (previous behaviour).
# ---- Levenberg-Marquardt settings (minpack.lm::nls.lm) ----
# Used by the main fit, by the Monte Carlo bootstrap and by Batch, so
# they always remain consistent. Three corrections arising from the validation on the 26
# NIST StRD datasets:
#  - maxfev: previously it was not set and minpack.lm used its default,
#    100 x (parameters + 1) function evaluations (400 with 3 parameters).
#    Each iteration uses about (parameters + 1) of them for the numerical
#    Jacobian, so the fit stopped after ~100 iterations whatever
#    "Max Iterations" was: MGH10, Bennett5, MGH09 and MGH17 did not converge. Now
#    maxfev is high enough never to be the actual limit.
#  - maxiter: nls.lm reduces it to 1024 anyway (limit of the library),
#    warning only in the R console; here the ceiling is explicit and
#    stated in the interface.
#  - ftol/ptol: the default (~1.5e-8) stops the fit short of the precision
#    of the certified values (ENSO, Thurber, MGH09 at 3-4 correct digits);
#    with 1e-12 it reaches 5-7 digits.
MASSIMO_ITERAZIONI_LM <- 1024
controllo_lm <- function(maxiter, n_parametri, tolleranza = 1e-12) {
  iterazioni <- min(maxiter, MASSIMO_ITERAZIONI_LM)
  nls.lm.control(maxiter = iterazioni, maxfev = max(100000, iterazioni * (n_parametri + 1) * 10), ftol = tolleranza, ptol = tolleranza)
}

# ---- Residuals to be resampled in the residual bootstrap ----
# Davison & Hinkley (1997): modified residuals r_j = e_j / (1 - h_j)^(1/2)
# (section 6.2.1, eq. 6.9, p. 259), which have the same variance as the errors,
# then centred, r_j - mean(r) (section 6.2.3, Algorithm 6.1, pp. 261-262); for
# nonlinear models the leverages h_j come from the linear approximation, with
# the derivatives of the model at the estimates in place of the explanatory variables, and
# the adjustment of the mean is in general necessary (section 7.4, p. 355).
# The same quantities are needed for the noise of the new observations (prediction
# band; section 6.3.3, Algorithm 6.4, p. 284). Leverages from the Jacobian J:
# diagonal of J (J^T J)^-1 J^T. The modification with the leverages applies to least
# squares (J = NULL with the other losses: centring only). With 'modifica'
# disabled the raw residuals are returned, as in the previous
# versions.
residui_per_bootstrap <- function(residui, J = NULL, modifica = TRUE) {
  if (!isTRUE(modifica)) return(residui)
  if (!is.null(J) && nrow(J) == length(residui)) {
    h <- tryCatch(rowSums((J %*% inverti_hessiana(crossprod(J))) * J), error = function(e) NULL)
    # Leverages close to 1 (points that the model reproduces almost exactly):
    # upper limit to avoid divisions by values close to zero.
    if (!is.null(h) && all(is.finite(h))) residui <- residui / sqrt(1 - pmin(pmax(h, 0), 0.99))
  }
  residui - mean(residui)
}

# ---- Weighted regression: support functions ----
# Weights w_i = 1/yhat_i^zeta ("power of the mean" variance model:
# var(y) = sigma^2 f^zeta), computed from the fit and saved in res$pesi; res$rmse
# is then sigma. Without weights these functions return the usual values.
ponderazione_attiva <- function(res) isTRUE(res$ponderazione$attiva) && !is.null(res$pesi)
# Residuals for the diagnostics: with weights, the weighted residuals sqrt(w)(y - yhat),
# which have constant variance if the weights are correct.
residui_diagnostici <- function(res) if (ponderazione_attiva(res)) res$residui * sqrt(res$pesi) else res$residui
# Description of the weights for summary, tables and exports.
descrizione_ponderazione <- function(res) {
  if (!ponderazione_attiva(res)) return("None")
  pd <- res$ponderazione
  paste0("w = 1/\u0177^", signif(pd$zeta, 4),
         switch(pd$schema, zeta1 = " (variance proportional to the mean)", zeta2 = " (constant coefficient of variation)",
                repliche = sprintf(" (\u03b6 = 2b, b = %.3f, 95%% CI %.3f to %.3f, from the replicates)", pd$b, pd$b_ci[1], pd$b_ci[2]), ""),
         if (!is.null(pd$iterazioni_irls)) sprintf("; %d reweighting cycles", pd$iterazioni_irls) else "")
}
# Relative variance of a new observation where the model equals y_previsti:
# y_previsti^zeta with weights (NA where y_previsti <= 0), 1 without weights.
varianza_relativa <- function(res, y_previsti) {
  if (!ponderazione_attiva(res)) return(rep(1, length(y_previsti)))
  ifelse(is.finite(y_previsti) & y_previsti > 0, abs(y_previsti)^res$ponderazione$zeta, NA_real_)
}

# ---- Multiplier of the confidence band (linear method) ----
# Pointwise: t(1 - alpha/2; n - p). Simultaneous, if requested: the "1 - alpha
# approximate inference band" of Bates & Watts (1988, ch. 2),
#   f(x, theta) +/- s ||v^T R^-1|| sqrt(p F(p, n - p; alpha)),
# where s ||v^T R^-1|| = sqrt(v^T s^2 (V^T V)^-1 v) is the same standard
# error of the curve used for the pointwise band (delta method): only
# the multiplier changes. F(p, n - p; alpha) is the upper alpha quantile,
# i.e. qf(1 - alpha, p, n - p). The prediction band remains pointwise.
# General version, also used by the secondary models (Shelf-Life and
# Non-Isothermal): df = residual degrees of freedom, p = estimated parameters,
# level in percent. NA if the degrees of freedom are not valid.
moltiplicatore_banda <- function(df, p, livello, simultanea = FALSE) {
  if (is.null(df) || length(df) != 1 || !is.finite(df) || df <= 0 || !is.finite(livello)) return(NA_real_)
  a <- 1 - livello / 100
  if (isTRUE(simultanea) && p >= 1) sqrt(p * qf(1 - a, p, df)) else qt(1 - a / 2, df)
}
moltiplicatore_banda_confidenza <- function(res) {
  puntuale <- valore_critico(res$df)
  if (!isTRUE(input$banda_simultanea)) return(puntuale)
  m <- moltiplicatore_banda(res$df, length(res$parametri), input$livello_confidenza, TRUE)
  if (is.finite(m)) m else puntuale
}

# ---- Information criteria: AIC, AICc, BIC (Burnham & Anderson, 1998) ----
# Form for least squares with Gaussian errors: K = p + 1 estimated
# parameters (the p of the model plus the error variance),
#   AIC  = n ln(SSE/n) + 2K
#   AICc = AIC + 2K(K + 1)/(n - K - 1)
#   BIC  = n ln(SSE/n) + K ln(n)
# The form omits the constant n(1 + ln 2pi): the absolute values differ
# from those of R (AIC() on an nls fit), the differences between models do not. Previously
# K = p was counted, which weakened the correction of AICc with few points
# (n = 8: penalty of the third parameter 5.60 instead of 9.33). The indices
# presuppose maximum-likelihood estimates, i.e. least squares
# with Gaussian errors: with the other losses they are not computed.
# With weighted least squares (weights w_i, variance sigma^2/w_i) the
# Gaussian log-likelihood contains in addition (1/2) sum(ln w_i): sse is the
# weighted sum of squares and somma_log_pesi = sum(ln w_i) is subtracted (zero
# without weights, hence no change). In this way AIC remains comparable
# also between fits with different variance structures.
criteri_informazione <- function(sse, n, p, tipo_loss = "mse", somma_log_pesi = 0) {
  vuoto <- list(aic = NA_real_, aicc = NA_real_, bic = NA_real_)
  if (!identical(tipo_loss, "mse") || !is.finite(sse) || sse <= 0 || !is.finite(n) || n <= 0) return(vuoto)
  K <- p + 1
  base <- n * log(sse / n) - somma_log_pesi
  aic <- base + 2 * K
  list(aic = aic, aicc = if (n - K - 1 > 0) aic + 2 * K * (K + 1) / (n - K - 1) else NA_real_, bic = base + K * log(n))
}
NOTA_CRITERI_LOSS <- "Not shown with losses other than MSE: AIC, AICc and BIC assume least-squares (maximum-likelihood) estimates."

# ---- Names without underscores in the Excel files ----
# In the Excel files, which are read directly, the names of sheets and columns
# appear without underscores, as on screen; the CSV files keep the original
# names. Used by all the Excel exports of the app.
per_excel <- function(fogli) {
  if (is.data.frame(fogli)) fogli <- list(Sheet1 = fogli)
  fogli <- lapply(fogli, function(df) { if (is.data.frame(df)) colnames(df) <- gsub("_", " ", colnames(df)); df })
  names(fogli) <- make.unique(trimws(substr(gsub("_", " ", names(fogli)), 1, 31)), sep = " ")
  fogli
}

# ---- Correction for multiple comparisons (post-hoc) ----
# Same three choices in all post-hoc analyses (parameters in Batch and Model
# Comparison, shelf life in Batch and Model Comparison). Holm and Bonferroni
# control the probability of even a single false positive in the family
# of comparisons (FWER); Benjamini-Hochberg the expected proportion of false
# positives among the comparisons declared significant (FDR), less severe and more
# powerful with many comparisons. The correction is applied separately for
# each parameter.
SCELTE_CORREZIONE_MULTIPLA <- c("Holm (recommended)" = "holm", "Bonferroni (more conservative)" = "bonferroni",
                                "Benjamini-Hochberg (FDR, less conservative)" = "BH")
etichetta_correzione <- function(metodo) switch(metodo, holm = "Holm", bonferroni = "Bonferroni", BH = "Benjamini-Hochberg (false discovery rate)", metodo)
descrizione_correzione <- function(metodo) if (identical(metodo, "BH")) {
  " It controls the expected proportion of false positives among the comparisons declared significant (FDR), rather than the probability of any false positive."
} else ""

# ---- Minimum number of successful Monte Carlo iterations ----
# Below this threshold the Monte Carlo results (empirical intervals, bootstrap
# SE, distribution summary, bands) are not shown: on
# very few values they have no statistical meaning. Same threshold in
# Single Fit and Batch (where it already existed); previously Single Fit computed
# everything even with 2 successful iterations out of 40.
MINIMO_ITERAZIONI_MC <- 10

# ---- Algorithm actually used ----
# Levenberg-Marquardt minimizes only sums of squares: with a loss other
# than MSE Nelder-Mead is used, as the interface does (and states), which changes
# the selector by itself. It is needed by the engine to protect itself when the
# combination arrives anyway (e.g. from a loaded configuration): previously
# Single Fit failed with an incomprehensible error ('arg' should be one
# of ...) and Batch instead fell back on BFGS, inconsistently.
algoritmo_effettivo <- function(algoritmo, tipo_loss) if (identical(algoritmo, "LM") && !identical(tipo_loss, "mse")) "Nelder-Mead" else algoritmo

# ---- Settings of BFGS, L-BFGS-B and Nelder-Mead (optim) ----
# Used by the main fit, by the Monte Carlo bootstrap and by Batch. Previously
# only maxit was passed: without scaling, with parameters on very
# different scales the optimizers stopped before the optimum (NIST Misra1a,
# b1 ~ 239 and b2 ~ 0.00055: BFGS at 1.8 correct digits, L-BFGS-B at 1.3).
# Now: parscale = absolute value of the starting point (1 if zero) and
# relative tolerance 1e-12 for BFGS and Nelder-Mead; on Misra1a BFGS and
# L-BFGS-B reach 4.3 digits, Nelder-Mead from 4.9 to 7.8. For L-BFGS-B
# (which ignores reltol) R's default tolerance (factr) is left:
# with factr = 10, tried previously, almost half of the fits ended with
# code 52 (ABNORMAL_TERMINATION_IN_LNSRCH) and were discarded as non-
# converging, without any gain in accuracy (4.3 digits in both
# cases on 200 simulated fits; the improvement comes from the scaling).
# Nelder-Mead: in optim() maxit counts the function evaluations (one or
# two per step of the simplex), not the iterations as for Levenberg-Marquardt
# and BFGS; with 200 evaluations and tolerance 1e-12 it did not converge in 34 models
# of the registry out of 85. Therefore 10 times Max Iterations is used (2000 with the
# default value): 79/85 converging with the same precision; beyond that
# nothing is gained (10000: 79/85).
FATTORE_VALUTAZIONI_NELDER_MEAD <- 10

# Nelder-Mead restarts: the simplex can get stuck far from the minimum
# and declare convergence when the changes become small. The search
# restarts from the point found with a new simplex (parscale on the new point)
# until the loss no longer improves (relative change < 1e-10), at most
# 10 times. On the 52 NIST fits: accepted fits with at least 4 correct digits from 24 to
# 39, accepted but inaccurate from 16 to 4. Optional (checkbox in section 5,
# on by default). For the other methods, or without restarts, the call is
# exactly optim() as before.
MAX_RIPARTENZE_NELDER_MEAD <- 10
optim_con_ripartenze <- function(par, fn, ..., method, control, hessian = FALSE, ripartenze = FALSE) {
  if (!identical(method, "Nelder-Mead") || !isTRUE(ripartenze))
    return(optim(par = par, fn = fn, ..., method = method, hessian = hessian, control = control))
  f <- optim(par = par, fn = fn, ..., method = method, control = control)
  conteggi <- f$counts; n <- 0; ctrl <- control
  while (n < MAX_RIPARTENZE_NELDER_MEAD) {
    ctrl$parscale <- ifelse(is.finite(f$par) & abs(f$par) > 1e-8, abs(f$par), 1)
    g <- optim(par = f$par, fn = fn, ..., method = method, control = ctrl); n <- n + 1
    migliorato <- is.finite(g$value) && (f$value - g$value) > 1e-10 * max(abs(f$value), 1e-300)
    conteggi["function"] <- conteggi["function"] + g$counts["function"]
    if (is.finite(g$value) && g$value <= f$value) f <- g
    if (!migliorato) break
  }
  if (hessian) f$hessian <- tryCatch(optimHess(f$par, fn, ..., control = ctrl[intersect(names(ctrl), c("fnscale", "parscale", "ndeps"))]), error = function(e) NULL)
  f$counts <- conteggi; f$ripartenze <- n
  f
}
controllo_optim <- function(metodo, maxiter, partenza, tolleranza = NULL) {
  scala <- ifelse(is.finite(partenza) & abs(partenza) > 1e-8, abs(partenza), 1)
  ctrl <- list(maxit = if (identical(metodo, "Nelder-Mead")) maxiter * FATTORE_VALUTAZIONI_NELDER_MEAD else maxiter, parscale = scala)
  if (identical(metodo, "L-BFGS-B")) {
    # L-BFGS-B expresses the tolerance as a multiple of the machine
    # precision (factr); without an explicit value R's one (1e7) remains.
    if (!is.null(tolleranza)) ctrl$factr <- tolleranza / .Machine$double.eps
  } else {
    ctrl$reltol <- if (is.null(tolleranza)) 1e-12 else tolleranza
  }
  ctrl
}

# ---- Convergence tolerance settable by the user ----
# Field "Convergence Tolerance (exponent, 10^x)" of section 5: applies to the
# main fit, Monte Carlo and Batch. Profiles and secondary models stay
# at the fixed (tight) tolerances, because their intervals depend on the
# precision of the re-optimization. Default values and limits by
# algorithm: for L-BFGS-B the default -9 (1e-9) is close to R's factr (1e7,
# ~2.2e-9; same NIST and Monte Carlo results) and the limit -11 avoids tolerances at which about half of the fits
# would end with code 52 (abnormal line search).
TOLLERANZA_ESPONENTI <- list(
  "LM"          = list(predefinito = -12, minimo = -15, massimo = -4),
  "BFGS"        = list(predefinito = -12, minimo = -15, massimo = -4),
  "Nelder-Mead" = list(predefinito = -12, minimo = -15, massimo = -4),
  "L-BFGS-B"    = list(predefinito = -9,  minimo = -11, massimo = -4)
)
limiti_tolleranza <- function(algoritmo) {
  l <- TOLLERANZA_ESPONENTI[[algoritmo]]
  if (is.null(l)) TOLLERANZA_ESPONENTI[["LM"]] else l
}
# Valid exponent for the algorithm (default if empty, brought within the limits).
esponente_tolleranza <- function(valore, algoritmo) {
  l <- limiti_tolleranza(algoritmo)
  if (is.null(valore) || length(valore) != 1 || !is.finite(valore)) return(l$predefinito)
  min(max(round(valore), l$minimo), l$massimo)
}

# ---- Analytical Jacobian of the model (symbolic derivatives, deriv() of base R) ----
# Returns a function (parameters, x, fixed) -> n x p matrix, columns
# in the order of nomi_liberi. The derivatives are computed symbolically by
# deriv(), hence exact (up to machine rounding). If the
# formula contains functions that deriv() does not know (e.g. ifelse, abs, min,
# max) or the result is not finite, it falls back on the numerical Jacobian
# (jacobiano_numerico, central differences). The formula is evaluated as in
# valuta_formula_generica(): same environment (parameters, fixed, x).
crea_jacobiano_modello <- function(formula_stringa, nomi_liberi) {
  espressione <- tryCatch(str2lang(formula_stringa), error = function(e) NULL)
  gradiente <- if (is.null(espressione) || length(nomi_liberi) == 0) NULL else tryCatch(deriv(espressione, nomi_liberi), error = function(e) NULL)
  function(parametri, x, fissi = list()) {
    valori <- c(as.list(setNames(as.numeric(parametri), nomi_liberi)), as.list(fissi))
    if (!is.null(gradiente)) {
      risultato <- tryCatch(eval(gradiente, c(valori, list(x = x))), error = function(e) NULL)
      J <- if (is.null(risultato)) NULL else attr(risultato, "gradient")
      if (!is.null(J)) {
        # Formula that does not depend on x: deriv() returns a single row.
        if (nrow(J) == 1 && length(x) > 1) J <- matrix(rep(J, each = length(x)), nrow = length(x))
        if (all(is.finite(J))) { colnames(J) <- nomi_liberi; return(J) }
      }
    }
    f <- function(p) eval(espressione, c(setNames(as.list(p), nomi_liberi), as.list(fissi), list(x = x)))
    jacobiano_numerico(f, setNames(as.numeric(parametri), nomi_liberi))
  }
}

# ---- Numerical Jacobian of the model (central differences) ----
# Used for the least-squares covariance, s^2 (J^T J)^-1, with the
# algorithms other than Levenberg-Marquardt. Previously the numerical Hessian
# returned by optim was used (finite differences of a gradient that is itself
# numerical, i.e. approximate second derivatives): with correlated
# parameters its errors are amplified in the inversion, and the
# standard errors turned out very wrong even on easy datasets (NIST
# Misra1a with BFGS: about 20 times too small). The Jacobian requires
# only first derivatives, is much more accurate and is the standard method
# (Bates & Watts, 1988; it is what nls() and minpack.lm do). Step
# relative to the magnitude of each parameter (cube root of the
# machine precision), so it also works with very small
# or very large parameters.
jacobiano_numerico <- function(f, parametri) {
  passo_base <- .Machine$double.eps^(1/3)
  J <- sapply(seq_along(parametri), function(j) {
    h <- passo_base * max(abs(parametri[j]), 1e-8)
    p_piu <- parametri; p_meno <- parametri
    p_piu[j] <- parametri[j] + h; p_meno[j] <- parametri[j] - h
    (f(p_piu) - f(p_meno)) / (2 * h)
  })
  if (is.null(dim(J))) J <- matrix(J, ncol = length(parametri))
  colnames(J) <- names(parametri)
  J
}

# ---- Fit of the secondary models (Shelf-Life, Non-Isothermal) ----
# Least squares with Levenberg-Marquardt (minpack.lm), with the same
# settings as the main fit (controllo_lm) and, if provided, the analytical
# Jacobian of the model (crea_jacobiano_modello); otherwise nls.lm uses its
# internal numerical derivatives. Used for the point estimate and for the bootstrap
# fits. Previously: a single Nelder-Mead without scaling, which with
# parameters on very different scales (Arrhenius: Ea ~ 1e4-1e5, q ~ 10-30)
# often stopped far from the optimum. On 6 synthetic cases (Arrhenius,
# Eyring, Q10; 3-4 temperatures; days and minutes), starting from the default
# initial values, 5 cases reach 8.6-10.1 correct digits with respect
# to a reference fit; the sixth requires initial values of the right order
# of magnitude. modello(p) returns the predictions, y the observed
# values. Returns par, value (SSE) and convergence (0 if nls.lm
# ended by convergence, info codes 1-4), like optim.
fit_modello_secondario <- function(modello, y, partenza, jacobiano = NULL) {
  previsioni <- function(p) { v <- tryCatch(modello(p), error = function(e) NULL); if (is.null(v) || any(!is.finite(v))) NULL else v }
  residui <- function(p) { v <- previsioni(p); if (is.null(v)) rep(1e5, length(y)) else y - v }
  argomenti <- list(par = partenza, fn = residui, control = controllo_lm(1024, length(partenza)))
  if (!is.null(jacobiano)) argomenti$jac <- function(p) { J <- -jacobiano(p); J[!is.finite(J)] <- 0; J }
  fit <- tryCatch(do.call(nls.lm, argomenti), error = function(e) NULL)
  if (is.null(fit)) return(NULL)
  v <- previsioni(fit$par)
  if (is.null(v)) return(NULL)
  list(par = fit$par, value = sum((y - v)^2), convergence = if (fit$info %in% 1:4) 0L else as.integer(fit$info))
}

# ---- Covariance of a least-squares model, from the Jacobian ----
# s^2 (J^T J)^-1 with s^2 = SSE / degrees of freedom. Returns NULL (never
# an invalid matrix) if it cannot be computed or with non-positive variances.
covarianza_minimi_quadrati <- function(f_modello, parametri, sse, df_residuo, jacobiano = NULL) {
  if (!is.finite(sse) || df_residuo <= 0) return(NULL)
  J <- tryCatch(if (!is.null(jacobiano)) jacobiano(parametri) else jacobiano_numerico(f_modello, parametri), error = function(e) NULL)
  cov <- if (is.null(J)) NULL else tryCatch((sse / df_residuo) * inverti_hessiana(crossprod(J)), error = function(e) NULL)
  if (is.null(cov) || !all(is.finite(diag(cov)) & diag(cov) > 0)) return(NULL)
  dimnames(cov) <- list(names(parametri), names(parametri))
  cov
}

inverti_hessiana <- function(H) {
  H <- as.matrix(H)
  d <- diag(H)
  if (all(is.finite(H)) && all(d > 0)) {
    s <- sqrt(d)
    return(solve(H / outer(s, s)) / outer(s, s))
  }
  solve(H)
}

inverti_colonne_xy <- function(df) {
  if (is.null(df) || !all(c("x", "y") %in% names(df))) return(df)
  x_originale <- df$x
  df$x <- df$y
  df$y <- x_originale
  df
}

# ---- y-axis limits for bar charts with error bars ----
# barplot() draws the bars starting from zero, so zero must always be
# included; the margin (10% of the extreme value) must be added on the side OPPOSITE
# to zero: above for positive values, below for negative ones. Previously
# min * 0.9 / max * 1.1 was used, which with negative values narrowed
# the axis instead of widening it (e.g. NIST Bennett5, b1 ~ -2500: the lower part
# of the error bars was cut off) or left the error bars
# exactly on the edge. With positive values the result is identical to before.
limiti_asse_barre <- function(valori) {
  estremi <- range(c(0, valori), na.rm = TRUE, finite = TRUE)
  inferiore <- if (estremi[1] < 0) estremi[1] * 1.1 else 0
  superiore <- if (estremi[2] > 0) estremi[2] * 1.1 else 0
  if (inferiore == superiore) c(-1, 1) else c(inferiore, superiore)
}
# Same idea for an axis that must not include zero: widens by 10%
# outwards whatever the sign (min * 0.9 with a negative minimum
# would bring it closer to zero, cutting the plot).
allarga_estremo <- function(v, verso) if (verso == "giu") (if (v >= 0) v * 0.9 else v * 1.1) else (if (v >= 0) v * 1.1 else v * 0.9)

# ---- Title of the x axis under category names rotated by 90 degrees ----
# In category plots (bars, boxplots, violins) the names on the x axis are
# rotated (las = 2): a title in the standard position (line 3) would end up
# over long names. The longest name is measured, the lower margin is
# widened as needed and the title goes right below the names. Usage: call
# prepara_margine_nomi_ruotati() BEFORE drawing, then
# titolo_asse_x_ruotato() AFTERWARDS, with the value returned by the first.
# With con_titolo = FALSE (title hidden by the user) the margin
# shrinks to the names only, without leaving empty space below.
prepara_margine_nomi_ruotati <- function(nomi, cex_nomi = 0.8, mar_base = c(6, 4, 3, 1), con_titolo = TRUE) {
  righe_nomi <- max(c(0, strwidth(as.character(nomi), units = "inches", cex = cex_nomi)), na.rm = TRUE) / (par("csi") * par("mex"))
  mar <- mar_base
  mar[1] <- if (con_titolo) max(mar_base[1], righe_nomi + 3.2) else righe_nomi + 1.8
  par(mar = mar)
  righe_nomi
}
titolo_asse_x_ruotato <- function(testo, righe_nomi, mostra = TRUE) if (mostra) title(xlab = testo, line = righe_nomi + 1.8)
# "Show x-axis title" checkbox of the aesthetics panels: active if not yet created.
titolo_x_attivo <- function(valore) is.null(valore) || isTRUE(valore)

# ---- "One plot per parameter" sections (single scheme for the whole app) ----
# Same scheme as the Grid Search sections: each parameter has its own
# plot and its own "Download Plot", and next to the title there are "Download
# All (ZIP)" and "Download Combined Image". Used by Parameter Distributions
# (Single Fit), parameter histograms and boxplots (Batch), parameter
# boxplots (Model Comparison).
MASSIMO_PANNELLI_PARAMETRI <- 15

estensione_esportazione <- function() if (identical(input$formato_esportazione, "pdf")) "pdf" else "jpg"

# Server side: registers the pre-generated outputs (plot + download for
# each possible panel), the ZIP and the combined image. 'n_pannelli'
# and 'disegna' are functions (read at drawing time, not now):
# n_pannelli() returns how many panels there are (0 = nothing to
# show), disegna(k) draws panel k on the current device.
registra_sezione_pannelli <- function(id, n_pannelli, disegna, prefisso_file) {
  for (idx in seq_len(MASSIMO_PANNELLI_PARAMETRI)) local({
    k <- idx
    output[[paste0("grafico_", id, "_", k)]] <- renderPlot({
      if (k > n_pannelli()) return(invisible(NULL))
      par(family = "sans")
      disegna(k)
    }, res = 100)
    output[[paste0("scarica_", id, "_", k)]] <- downloadHandler(
      filename = function() paste0(prefisso_file, "_", k, ".", estensione_esportazione()),
      content = function(file) {
        dim_exp <- dimensioni_esportazione()
        if (identical(input$formato_esportazione, "pdf")) pdf(file, width = dim_exp$width_in, height = dim_exp$height_in)
        else jpeg(file, width = dim_exp$width_px, height = dim_exp$height_px, res = dim_exp$dpi)
        on.exit(dev.off(), add = TRUE)
        disegna(k)
      }
    )
  })
  output[[paste0("scarica_tutti_", id)]] <- downloadHandler(
    filename = function() paste0(prefisso_file, "_all.zip"),
    content = function(file) crea_zip_grafici(seq_len(max(1, n_pannelli())), prefisso_file, disegna, file),
    contentType = "application/zip"
  )
  output[[paste0("scarica_composito_", id)]] <- downloadHandler(
    filename = function() nome_file_composito(prefisso_file),
    content = function(file) crea_immagine_composita(file, max(1, n_pannelli()), disegna)
  )
  invisible(NULL)
}

# UI side: title with ZIP and combined image next to it, optional
# description, then the plots 3 per row with "Download Plot" under each one and
# the 🎨 button under the first (the settings apply to all of them).
ui_sezione_pannelli <- function(id, n, titolo, descrizione, id_estetica, altezza = "380px") {
  n <- min(n, MASSIMO_PANNELLI_PARAMETRI)
  blocchi <- lapply(seq_len(n), function(k) {
    column(4,
      plotOutput(paste0("grafico_", id, "_", k), height = altezza),
      div(style = "margin-top: 8px; margin-bottom: 16px;",
          downloadButton(paste0("scarica_", id, "_", k), "Download Plot", class = "btn-outline-secondary btn-sm"),
          if (k == 1 && !is.null(id_estetica)) actionButton(id_estetica, "\U0001F3A8", class = "btn-outline-secondary btn-sm", title = "Customize these plots"))
    )
  })
  righe <- lapply(seq(1, n, by = 3), function(i) do.call(fluidRow, blocchi[i:min(i + 2, n)]))
  tagList(
    tags$h4(style = "display: inline-block; margin-right: 10px;", titolo),
    downloadButton(paste0("scarica_tutti_", id), "Download All (ZIP)", class = "btn-outline-primary btn-sm"),
    downloadButton(paste0("scarica_composito_", id), "Download Combined Image", class = "btn-outline-primary btn-sm"),
    if (!is.null(descrizione)) p(style = "font-size: 12px; color: #566573; margin-top: 6px;", descrizione),
    righe
  )
}

