# ============================
# ENRICHED CSV AND EXCEL DATA EXPORT
# ============================
prepara_dati_export <- function() {
  res <- tryCatch(elaborazione(), error = function(e) NULL)
  if (is.null(res) || !res$successo) return(NULL)
  
  # 1. MODEL AND ALGORITHM INFO
  trasf_y_usata <- if (is.null(input$trasformazione_y) || input$trasformazione_y == "nessuna") "None (raw values)" else {
    scelte_trasf <- costruisci_scelte_trasformazione_y()
    nomi_scelte <- names(scelte_trasf)[scelte_trasf == input$trasformazione_y]
    if (length(nomi_scelte) > 0) nomi_scelte[1] else input$trasformazione_y
  }
  df_info <- data.frame(
    Property = c("Model Category", "Formula Used", "Y Pre-transformation", "Optimization Algorithm", "Loss Function", "Weighting", "Error Method",
                 "Max Iterations", "Convergence Tolerance",
                 "Monte Carlo Noise Type", "Monte Carlo Sigma Used", "Monte Carlo Successful Iterations", "Confidence Level (%)"),
    Value = c(input$tipo_modello, res$formula, trasf_y_usata, algoritmo_effettivo(input$algoritmo, input$tipo_loss), input$tipo_loss, descrizione_ponderazione(res), input$metodo_errore,
              as.character(input$maxiter_ottimizzazione),
              if (is.null(res$esponente_tolleranza)) "N/A" else paste0("1e", res$esponente_tolleranza),
              ifelse(is.null(res$tipo_rumore_mc) || is.na(res$tipo_rumore_mc), "N/A",
                     if (identical(res$tipo_rumore_mc, "bootstrap")) paste0("bootstrap (", if (isTRUE(res$residui_modificati)) "leverage-corrected, centred residuals; Davison & Hinkley, 1997" else "raw residuals", ")") else res$tipo_rumore_mc),
              ifelse(is.null(res$sigma_mc) || is.na(res$sigma_mc), "N/A", as.character(round(res$sigma_mc, 5))),
              ifelse(is.null(res$n_boot_totale) || is.na(res$n_boot_totale), "N/A", paste0(res$n_boot_successo, " / ", res$n_boot_totale)),
              as.character(input$livello_confidenza))
  )
  
  # 2. PARAMETERS
  crit_val <- valore_critico(res$df)  # Student's t (df=n-p), converges to Z for large samples
  df_params <- data.frame(Parameter = names(res$parametri), Estimate = as.numeric(res$parametri), Std_Error = as.numeric(res$errori))
  df_params$CI_Parametric_Lower <- df_params$Estimate - (crit_val * df_params$Std_Error)
  df_params$CI_Parametric_Upper <- df_params$Estimate + (crit_val * df_params$Std_Error)
  
  # With Monte Carlo, it also adds the EMPIRICAL interval (direct quantiles
  # of the bootstrap distribution), which unlike the parametric one
  # above does not assume symmetry.
  if (input$metodo_errore == "monte_carlo" && !is.null(res$mat_boot_params)) {
    p_inf <- (1 - input$livello_confidenza / 100) / 2
    p_sup <- 1 - p_inf
    df_params$CI_Empirical_Lower <- apply(res$mat_boot_params, 2, quantile, probs = p_inf, na.rm = TRUE)
    df_params$CI_Empirical_Upper <- apply(res$mat_boot_params, 2, quantile, probs = p_sup, na.rm = TRUE)
  }
  
  df_fissi <- if (!is.null(res$fissi) && length(res$fissi) > 0) {
    data.frame(Parameter = names(res$fissi), Fixed_Value = as.numeric(res$fissi))
  } else {
    data.frame(Parameter = character(0), Fixed_Value = numeric(0))
  }
  
  # 3. DIAGNOSTICS
  safe_extract <- function(x) { if (is.null(x) || length(x) == 0) NA else as.numeric(x[1]) }
  valori_diagnostici <- sapply(list(
    res$obs, res$df, res$r_corr, res$r2, res$r2_adj, res$rmse, 
    res$cv_rmse, res$sse, res$mse, res$aic, res$aicc, res$bic, res$iter
  ), safe_extract)
  
  df_diag <- data.frame(
    Metric = c("Observations (n)", "Degrees of Freedom", "Correlation (r)", "R-squared", "Adj R-squared",
               "RMSE", "CV_RMSE_perc", "SSE", "MSE", "AIC", "AICc", "BIC", "Iterations"),
    Value = valori_diagnostici
  )
  
  # 4. STANDARD PREDICTIONS (on the input points)
  df_pred <- data.frame(
    Obs = 1:res$obs, X_Value = res$x, Y_Observed = res$df_originale$y,
    Y_Predicted = res$y_pred, Residual = res$residui, Absolute_Error = abs(res$residui),
    Relative_Error_Perc = ifelse(res$df_originale$y != 0, (abs(res$residui) / abs(res$df_originale$y)) * 100, NA)
  )
  
  # 5. DENSE 1000-POINT CURVE
  x_dense <- seq(min(res$x), max(res$x), length.out = 1000)
  y_dense <- res$valuta(res$parametri, x_dense)
  df_dense <- data.frame(X_Grid_Value = x_dense, Y_Predicted_Curve = y_dense)
  
  # 6. ALL N BOOTSTRAP PARAMETER SETS (only if Monte Carlo was used)
  df_boot_params <- if (!is.null(res$mat_boot_params) && nrow(res$mat_boot_params) > 0) {
    mat_boot <- res$mat_boot_params
    colnames(mat_boot) <- names(res$parametri)
    cbind(data.frame(Iteration = seq_len(nrow(mat_boot))), as.data.frame(mat_boot))
  } else {
    data.frame(Iteration = integer(0))
  }
  
  # 7. BOOTSTRAP DISTRIBUTION SUMMARY & NORMALITY DIAGNOSTICS - Monte Carlo only.
  # Same function as the on-screen table (riepilogo_distribuzione_bootstrap
  # in rendering_output.R), so screen and export cannot diverge;
  # here the values remain numeric and complete.
  df_normalita <- if (!is.null(res$mat_boot_params) && nrow(res$mat_boot_params) > 0) {
    do.call(rbind, lapply(riepilogo_distribuzione_bootstrap(res), function(r) data.frame(
      Parameter = r$nome, Estimate = r$stima, Mean = r$media, Median = r$mediana, Bootstrap_SE = r$se_boot, Bias = r$bias,
      Abs_Bias_over_SE = r$rapporto,
      W_Statistic = if (is.null(r$test)) NA_real_ else unname(r$test$statistic), P_Value = if (is.null(r$test)) NA_real_ else r$test$p.value,
      Skewness = r$skew, Excess_Kurtosis = r$kurt, stringsAsFactors = FALSE)))
  } else {
    data.frame(Parameter = character(0))
  }
  
  # 8. PARAMETER CORRELATION MATRIX (Hessian for Linear method, bootstrap for Monte Carlo)
  mat_corr <- calcola_matrice_correlazione(res)
  df_correlazione <- if (!is.null(mat_corr)) {
    cbind(Parameter = rownames(mat_corr), as.data.frame(mat_corr))
  } else {
    data.frame(Parameter = character(0))
  }
  
  # 9. PARAMETER SENSITIVITY ANALYSIS (normalized, at every X of the dense curve)
  df_sensibilita <- tryCatch({
    n_par <- length(res$parametri)
    y_base <- res$valuta(res$parametri, x_dense)
    sens <- data.frame(X_Grid_Value = x_dense)
    for (j in seq_len(n_par)) {
      h_j <- passo_derivata(res$parametri[j])
      p_piu <- res$parametri; p_piu[j] <- p_piu[j] + h_j
      p_meno <- res$parametri; p_meno[j] <- p_meno[j] - h_j
      dydtheta <- (res$valuta(p_piu, x_dense) - res$valuta(p_meno, x_dense)) / (2 * h_j)
      sens[[paste0("Sensitivity_", names(res$parametri)[j])]] <- ifelse(abs(y_base) > 1e-10, dydtheta * (res$parametri[j] / y_base), NA)
    }
    sens
  }, error = function(e) data.frame(X_Grid_Value = numeric(0)))
  
  c(list(Model_Info = df_info, Parameters = df_params, Fixed_Parameters = df_fissi, Diagnostics = df_diag, 
       Simulated_Curve_1000pts = df_dense, Predictions = df_pred, Monte_Carlo_Bootstrap_Sets = df_boot_params,
       Bootstrap_Summary = df_normalita, Correlation_Matrix = df_correlazione, Sensitivity_Analysis = df_sensibilita),
    tabelle_diagnostica_residui(tryCatch(diagnostica_residui(res), error = function(e) NULL)))
}

# Data of the Loss Surface Explorer (grid search), exported separately
# because optional (they exist only if the user has actually launched
# at least one search in that section).
prepara_dati_grid_search_export <- function() {
  dati_grid <- tryCatch(griglia_attiva(), error = function(e) NULL)
  if (is.null(dati_grid) || !isTRUE(dati_grid$successo)) return(NULL)
  
  # "Long" format: one row for each combination of the two parameters
  griglia_lunga <- expand.grid(Par1_Value = dati_grid$seq1, Par2_Value = dati_grid$seq2)
  griglia_lunga$Loss_Fast <- as.vector(dati_grid$mat_loss)
  if (!is.null(dati_grid$mat_loss_rigorosa)) griglia_lunga$Loss_Rigorous <- as.vector(dati_grid$mat_loss_rigorosa)
  colnames(griglia_lunga)[1:2] <- c(dati_grid$par1, dati_grid$par2)
  
  df_info_grid <- data.frame(Property = c("Parameter 1", "Parameter 2"), Value = c(dati_grid$par1, dati_grid$par2))
  
  # CI comparison table (F-test/Classic/Monte Carlo) already computed
  # by the shared reactive - same source used by the on-screen table
  # and by the two bar charts, so the export is always consistent with
  # what is visible in the app. It automatically also includes any
  # other profiled parameters (if the checkbox "Also compute Model Comparison CI for
  # every other parameter" was ticked at the moment of Run Rigorous Profile),
  # since ci_marginali_grid_dati() now returns one row for each
  # available parameter, not only the 2 chosen for the grid.
  d_ci <- tryCatch(ci_marginali_grid_dati(), error = function(e) list(successo = FALSE))
  df_ci_confronto <- if (isTRUE(d_ci$successo)) {
    formatta_num <- function(v) if (is.na(v)) NA_real_ else round(v, 5)
    df_righe <- lapply(d_ci$righe, function(r) {
      riga <- data.frame(
        Parameter = r$par,
        Estimate = round(r$stima, 5),
        Profile_CI_Lower = formatta_num(r$profile_inf$valore),
        Profile_CI_Upper = formatta_num(r$profile_sup$valore),
        Classic_CI_Lower = formatta_num(r$classico_inf),
        Classic_CI_Upper = formatta_num(r$classico_sup),
        stringsAsFactors = FALSE
      )
      if (isTRUE(d_ci$ha_montecarlo)) {
        riga$MonteCarlo_CI_Lower <- formatta_num(r$mc_inf)
        riga$MonteCarlo_CI_Upper <- formatta_num(r$mc_sup)
      }
      riga
    })
    do.call(rbind, df_righe)
  } else {
    data.frame(Parameter = character(0))
  }
  
  list(Grid_Info = df_info_grid, Grid_Values = griglia_lunga, Grid_CI_Comparison = df_ci_confronto)
}

output$scarica_csv <- downloadHandler(
  filename = function() { paste0("regression_results_", Sys.Date(), ".csv") },
  content = function(file) {
    dati <- prepara_dati_export()
    if(is.null(dati)) return()
    cat("--- MODEL INFO ---\n", file = file)
    write.table(dati$Model_Info, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    cat("\n--- PARAMETER ESTIMATION RESULTS ---\n", file = file, append = TRUE)
    write.table(dati$Parameters, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    if (nrow(dati$Fixed_Parameters) > 0) {
      cat("\n--- FIXED PARAMETERS (EXCLUDED FROM OPTIMIZATION) ---\n", file = file, append = TRUE)
      write.table(dati$Fixed_Parameters, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    }
    cat("\n--- GOODNESS-OF-FIT DIAGNOSTICS ---\n", file = file, append = TRUE)
    write.table(dati$Diagnostics, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    cat("\n--- PREDICTIONS & RESIDUALS (OBSERVED DATA) ---\n", file = file, append = TRUE)
    write.table(dati$Predictions, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    cat("\n--- DENSE SIMULATED CURVE (1000 POINTS) ---\n", file = file, append = TRUE)
    write.table(dati$Simulated_Curve_1000pts, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    if (nrow(dati$Monte_Carlo_Bootstrap_Sets) > 0) {
      cat("\n--- MONTE CARLO BOOTSTRAP PARAMETER SETS (ALL ITERATIONS) ---\n", file = file, append = TRUE)
      write.table(dati$Monte_Carlo_Bootstrap_Sets, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    }
    if (nrow(dati$Bootstrap_Summary) > 0) {
      cat("\n--- BOOTSTRAP DISTRIBUTION SUMMARY & NORMALITY DIAGNOSTICS (MEAN, MEDIAN, BOOTSTRAP SE, BIAS, SHAPIRO-WILK, SKEWNESS, EXCESS KURTOSIS) ---\n", file = file, append = TRUE)
      write.table(dati$Bootstrap_Summary, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    }
    if (nrow(dati$Correlation_Matrix) > 0) {
      cat("\n--- PARAMETER CORRELATION MATRIX ---\n", file = file, append = TRUE)
      write.table(dati$Correlation_Matrix, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    }
    if (nrow(dati$Sensitivity_Analysis) > 0) {
      cat("\n--- PARAMETER SENSITIVITY ANALYSIS ---\n", file = file, append = TRUE)
      write.table(dati$Sensitivity_Analysis, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    }
    for (sez in list(c("Residual_Autocorrelation", "RESIDUAL DIAGNOSTICS: LAG-1 AUTOCORRELATION"), c("Runs_Test", "RESIDUAL DIAGNOSTICS: RUNS TEST"), c("Lack_of_Fit", "REPLICATE DIAGNOSTICS: LACK-OF-FIT TEST"),
                     c("Variance_Homogeneity", "REPLICATE DIAGNOSTICS: VARIANCE HOMOGENEITY TESTS"), c("Replicates", "REPLICATE DIAGNOSTICS: REPLICATES PER X"))) {
      if (!is.null(dati[[sez[1]]]) && nrow(dati[[sez[1]]]) > 0) {
        cat(paste0("\n--- ", sez[2], " ---\n"), file = file, append = TRUE)
        write.table(dati[[sez[1]]], file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE, na = "")
      }
    }
    dati_grid_export <- prepara_dati_grid_search_export()
    if (!is.null(dati_grid_export)) {
      cat("\n--- LOSS SURFACE EXPLORER (GRID SEARCH) ---\n", file = file, append = TRUE)
      write.table(dati_grid_export$Grid_Info, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
      cat("\n", file = file, append = TRUE)
      write.table(dati_grid_export$Grid_Values, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
      if (nrow(dati_grid_export$Grid_CI_Comparison) > 0) {
        cat("\n--- LOSS SURFACE EXPLORER: CONFIDENCE INTERVAL COMPARISON (PROFILE VS CLASSIC VS MONTE CARLO) ---\n", file = file, append = TRUE)
        write.table(dati_grid_export$Grid_CI_Comparison, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
      }
    }
  }
)

output$scarica_excel <- downloadHandler(
  filename = function() { paste0("regression_results_", Sys.Date(), ".xlsx") },
  content = function(file) {
    dati <- prepara_dati_export()
    if(is.null(dati)) return()
    dati_grid_export <- prepara_dati_grid_search_export()
    if (!is.null(dati_grid_export)) {
      dati$Grid_Search_Info <- dati_grid_export$Grid_Info
      dati$Grid_Search_Values <- dati_grid_export$Grid_Values
      if (nrow(dati_grid_export$Grid_CI_Comparison) > 0) dati$Grid_CI_Comparison <- dati_grid_export$Grid_CI_Comparison
    }
    writexl::write_xlsx(per_excel(dati), path = file)
  }
)

# ---- ZIP download of every plot currently available in Single Fit Analysis ----
output$scarica_tutti_grafici_zip <- downloadHandler(
  filename = function() paste0("graphical_analysis_plots_", Sys.Date(), ".zip"),
  content = function(file) {
    res <- tryCatch(elaborazione(), error = function(e) NULL)
    dim_exp <- dimensioni_esportazione()
    formato <- input$formato_esportazione
    
    cartella_tmp <- tempfile()
    dir.create(cartella_tmp)
    
    # Saves a single plot to file, in a safe way (does not block the whole
    # zip if a specific plot fails - it just skips it).
    salva_grafico <- function(nome_file, funzione_disegno) {
      percorso <- file.path(cartella_tmp, paste0(nome_file, ".", formato))
      tryCatch({
        if (formato == "pdf") pdf(percorso, width = dim_exp$width_in, height = dim_exp$height_in)
        else jpeg(percorso, width = dim_exp$width_px, height = dim_exp$height_px, res = dim_exp$dpi)
        funzione_disegno()
        dev.off()
      }, error = function(e) {
        if (!is.null(dev.list())) dev.off()
      })
    }
    
    if (!is.null(res) && isTRUE(res$successo)) {
      df_dati <- dati()
      salva_grafico("01_main_fit_plot", function() disegna_grafico_fit(df_dati, res))
      salva_grafico("02_residuals_plot", function() disegna_grafico_residui(res))
      salva_grafico("03_qq_plot", function() disegna_grafico_qq(res))
      salva_grafico("03b_lag_plot", function() disegna_grafico_lag(res))
      salva_grafico("03c_variance_structure_plot", function() disegna_grafico_sd_media(res))
      if (input$metodo_errore == "monte_carlo") {
        salva_grafico("04_parameter_distributions", function() disegna_grafico_distribuzioni(res))
        salva_grafico("05_bootstrap_parameter_cloud", function() disegna_pairs_bootstrap(res))
      }
      salva_grafico("06_sensitivity_analysis", function() disegna_grafico_sensibilita(res))
      
      dati_grid <- tryCatch(griglia_attiva(), error = function(e) NULL)
      if (!is.null(dati_grid) && isTRUE(dati_grid$successo)) {
        salva_grafico("07_loss_surface_3d", function() disegna_grid_3d(dati_grid))
        salva_grafico("08_loss_surface_contour", function() disegna_grid_contour(dati_grid, res))
        d_ci_zip <- tryCatch(ci_marginali_grid_dati(), error = function(e) list(successo = FALSE))
        if (isTRUE(d_ci_zip$successo)) {
          for (idx_ci in seq_along(d_ci_zip$righe)) {
            local({
              idx_locale <- idx_ci
              salva_grafico(sprintf("%02d_loss_surface_ci_comparison_%s", 8 + idx_locale, d_ci_zip$righe[[idx_locale]]$par),
                           function() disegna_barre_ci_grid(idx_locale))
            })
          }
        }
      }
    }
    
    file_generati <- list.files(cartella_tmp)
    if (length(file_generati) == 0) {
      writeLines("No plots available yet: run a successful optimization first.", file.path(cartella_tmp, "README.txt"))
      file_generati <- list.files(cartella_tmp)
    }
    
    cartella_corrente <- getwd()
    on.exit(setwd(cartella_corrente))
    setwd(cartella_tmp)
    zip::zip(zipfile = file, files = file_generati)
  }
)
# ============================
# GRAPHICAL FUNCTIONS
# ============================
disegna_grafico_simulazione <- function(res) {
  titolo_main <- if(input$mostra_titolo) "Interactive Modeler: Initial Guess Curve Preview" else ""
  if (is.null(res)) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type = "n", main = if(input$mostra_titolo) "Click 'Simulate...' to preview" else "", axes = FALSE, xlab = "", ylab = "")
    return(invisible(NULL))
  }
  if (!res$successo) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type = "n", main = if(input$mostra_titolo) "Simulation halted due to errors." else "", axes = FALSE, xlab = "", ylab = "")
    return(invisible(NULL))
  }
  
  pt_col  <- if(is.null(input$pt_col_sim)) "#bdc3c7" else input$pt_col_sim
  ln_col  <- if(is.null(input$ln_col_sim)) "#e74c3c" else input$ln_col_sim
  pt_cex  <- if(is.null(input$pt_cex_sim)) 1.4 else input$pt_cex_sim
  ln_lwd  <- if(is.null(input$ln_lwd_sim)) 3.5 else input$ln_lwd_sim
  grid_on <- if(is.null(input$mostra_griglia)) TRUE else input$mostra_griglia
  pt_pch  <- as.numeric(if(is.null(input$pt_pch_sim)) "16" else input$pt_pch_sim)
  fnt_cex <- if(is.null(input$fnt_cex_sim)) 1.0 else input$fnt_cex_sim
  mostra_legenda_sim <- if(is.null(input$sim_mostra_legenda)) TRUE else input$sim_mostra_legenda
  
  par(mar = c(5, 5, if(input$mostra_titolo) 4 else 2, 2) + 0.1)
  limiti_x <- range(res$x)
  mostra_punti_dati <- if (is.null(input$sim_mostra_punti_dati)) TRUE else input$sim_mostra_punti_dati
  mostra_punti <- mostra_punti_dati && !is.null(res$punti_exp) && nrow(res$punti_exp) > 0
  
  if (range_personalizzato_attivo(input$range_y_min_sim, input$range_y_max_sim)) {
    limiti_y <- c(input$range_y_min_sim, input$range_y_max_sim)
  } else {
    limiti_y <- range(res$y[is.finite(res$y)])
    if (mostra_punti) limiti_y <- range(c(limiti_y, res$punti_exp$y[is.finite(res$punti_exp$y)]), na.rm = TRUE)
  }
  
  plot(1, type = "n", xlim = limiti_x, ylim = limiti_y, xlab = interpreta_etichetta(input$label_x), ylab = interpreta_etichetta(input$label_y),
       main = titolo_main, cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1, las = 1)
  if(grid_on) grid()
  
  # History of the previous curves (if the "Keep previous curves" option is
  # active) - drawn BEFORE the current curve, in a lighter
  # colour, so they remain visible as a "trace" under the current curve
  # without covering it.
  storico <- tryCatch(storico_curve_simulate(), error = function(e) NULL)
  if (!is.null(storico) && length(storico) > 0) {
    for (curva_vecchia in storico) {
      lines(curva_vecchia$x, curva_vecchia$y, col = adjustcolor(ln_col, alpha.f = 0.25), lwd = max(1, ln_lwd - 1))
    }
  }
  
  cex_legenda_sim <- if (is.null(input$sim_cex_legenda)) 1.0 else input$sim_cex_legenda
  pos_legenda_sim <- if (is.null(input$sim_pos_legenda)) "topright" else input$sim_pos_legenda
  if (mostra_punti) {
    points(res$punti_exp$x, res$punti_exp$y, col = pt_col, pch = pt_pch, cex = pt_cex)
    if (mostra_legenda_sim) {
      legend(pos_legenda_sim, legend = c("Simulated Curve", "Experimental Points"), 
             col = c(ln_col, pt_col), lty = c(1, NA), pch = c(NA, pt_pch), lwd = c(ln_lwd, NA), bty = "o", bg = "white", cex = cex_legenda_sim)
    }
  } else if (mostra_legenda_sim) {
    legend(pos_legenda_sim, legend = "Simulated Curve", col = ln_col, lty = 1, lwd = ln_lwd, bty = "o", bg = "white", cex = cex_legenda_sim)
  }
  lines(res$x, res$y, col = ln_col, lwd = ln_lwd, lty = 1)
}

# ---- Confidence and prediction bands of the main plot ----
# Returns the x grid, the curve and the requested bands (NULL if not
# requested or not available). Monte Carlo method: percentiles of the bootstrap curves
# (confidence) and of the curves with added noise (prediction).
# Linear method: delta method with gradient by central differences; the confidence
# band uses moltiplicatore_banda_confidenza() (pointwise or simultaneous,
# Bates & Watts 1988), the prediction band always the pointwise t.
calcola_bande_grafico <- function(res) {
  if (is.null(res) || !is.list(res) || !isTRUE(res$successo)) return(NULL)
  x_seq <- res$x_griglia; y_seq <- res$valuta(res$parametri, x_seq)
  p_inf <- (1 - input$livello_confidenza / 100) / 2; p_sup <- 1 - p_inf
  mc <- identical(input$metodo_errore, "monte_carlo")
  out <- list(x = x_seq, y = y_seq)
  se_curva <- function() {
    G <- sapply(seq_along(res$parametri), function(j) {
      h_j <- passo_derivata(res$parametri[j])
      pp <- res$parametri; pp[j] <- pp[j] + h_j; pm <- res$parametri; pm[j] <- pm[j] - h_j
      (res$valuta(pp, x_seq) - res$valuta(pm, x_seq)) / (2 * h_j)
    })
    if (is.null(dim(G))) G <- matrix(G, ncol = length(res$parametri))
    sqrt(rowSums((G %*% res$cov) * G))
  }
  lineare_ok <- !is.null(res$cov) && all(res$errori > 0, na.rm = TRUE)
  # Reason why a requested band is not available, shown in the plot
  # (previously the band was omitted without any explanation).
  motivo_assente <- if (mc && is.null(res$curve_boot) && !lineare_ok) "Monte Carlo results not available"
                    else if (!mc && !lineare_ok) (if (isTRUE(res$criteri_non_disponibili)) "loss other than MSE (use Monte Carlo)" else "standard errors not available")
                    else NULL
  errore_banda <- NULL
  if (isTRUE(input$mostra_pi)) tryCatch({
    if (mc && !is.null(res$pred_boot)) {
      out$pi_inf <- apply(res$pred_boot, 2, quantile, probs = p_inf, na.rm = TRUE)
      out$pi_sup <- apply(res$pred_boot, 2, quantile, probs = p_sup, na.rm = TRUE)
    } else if (lineare_ok) {
      se_tot <- sqrt(se_curva()^2 + res$rmse^2 * varianza_relativa(res, y_seq)); z <- valore_critico(res$df)
      out$pi_inf <- y_seq - z * se_tot; out$pi_sup <- y_seq + z * se_tot
    }
  }, error = function(e) errore_banda <<- conditionMessage(e))
  if (isTRUE(input$mostra_ci)) tryCatch({
    if (mc && !is.null(res$curve_boot)) {
      out$ci_inf <- apply(res$curve_boot, 2, quantile, probs = p_inf, na.rm = TRUE)
      out$ci_sup <- apply(res$curve_boot, 2, quantile, probs = p_sup, na.rm = TRUE)
      out$ci_tipo <- "monte_carlo"
    } else if (lineare_ok) {
      m <- moltiplicatore_banda_confidenza(res); se <- se_curva()
      out$ci_inf <- y_seq - m * se; out$ci_sup <- y_seq + m * se
      out$ci_tipo <- "lineare"
    }
  }, error = function(e) errore_banda <<- conditionMessage(e))
  richieste <- c(if (isTRUE(input$mostra_ci) && is.null(out$ci_inf)) "confidence", if (isTRUE(input$mostra_pi) && is.null(out$pi_inf)) "prediction")
  if (length(richieste)) out$nota <- paste0("No ", paste(richieste, collapse = "/"), " band: ",
                                           if (!is.null(motivo_assente)) motivo_assente
                                           else if (!is.null(errore_banda)) paste0("computation error (", substr(errore_banda, 1, 45), ")") else "not available")
  out
}

disegna_grafico_fit <- function(df, res) {
  titolo_main <- if(input$mostra_titolo) "Model Visualization" else ""
  
  pt_col   <- if(is.null(input$pt_col_fit)) "#005088" else input$pt_col_fit
  ln_col   <- if(is.null(input$ln_col_fit)) "#e74c3c" else input$ln_col_fit
  pt_cex   <- if(is.null(input$pt_cex_fit)) 1.5 else input$pt_cex_fit
  ln_lwd   <- if(is.null(input$ln_lwd_fit)) 3 else input$ln_lwd_fit
  grid_on  <- if(is.null(input$mostra_griglia)) TRUE else input$mostra_griglia
  pt_pch   <- as.numeric(if(is.null(input$pt_pch_fit)) "16" else input$pt_pch_fit)
  fnt_cex  <- if(is.null(input$fnt_cex_fit)) 1.0 else input$fnt_cex_fit
  ci_alpha <- if(is.null(input$ci_alpha_fit)) 0.3 else input$ci_alpha_fit
  ln_lty   <- as.numeric(if(is.null(input$ln_lty_fit)) "1" else input$ln_lty_fit)
  
  par(mar = c(5, 5, if(input$mostra_titolo) 4 else 2, 2) + 0.1)
  limiti_x <- calcola_limiti(input$range_x_min, input$range_x_max, df$x)
  z_val <- valore_critico(res$df)  # Student's t (df=n-p), converges to Z for large samples
  
  # Bands computed only once, before the plot: they are needed both for the automatic
  # limits of the y axis and for the drawing. Previously the limits considered
  # only the data (plus an approximate margin for the prediction band), and
  # the confidence band could go outside the plot.
  bande <- calcola_bande_grafico(res)
  if (range_personalizzato_attivo(input$range_y_min, input$range_y_max)) {
    limiti_y <- c(input$range_y_min, input$range_y_max)
  } else {
    tutti_y <- df$y[is.finite(df$y)]
    if (!is.null(bande)) {
      dentro <- bande$x >= limiti_x[1] & bande$x <= limiti_x[2]
      tutti_y <- c(tutti_y, unlist(lapply(bande[c("ci_inf", "ci_sup", "pi_inf", "pi_sup")], function(v) if (is.null(v)) NULL else v[dentro])))
      tutti_y <- tutti_y[is.finite(tutti_y)]
    }
    limiti_y <- if (length(tutti_y) > 0) range(tutti_y) else c(0, 1)
  }
  
  plot(df$x, df$y, main = titolo_main, col = pt_col, pch = pt_pch, cex = pt_cex, 
       cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1, las = 1,
       xlab = interpreta_etichetta(input$label_x), ylab = interpreta_etichetta(input$label_y), xlim = limiti_x, ylim = limiti_y)
  if(grid_on) grid()
  
  if (!is.null(res) && is.list(res) && res$successo) {
    x_seq <- res$x_griglia
    y_seq <- res$valuta(res$parametri, x_seq)
    p_inf <- (1 - input$livello_confidenza / 100) / 2
    p_sup <- 1 - p_inf
    
    if (!is.null(bande$nota)) mtext(bande$nota, side = 3, line = 0.2, cex = 0.75 * fnt_cex, col = "#d35400")
    if (!is.null(bande$pi_inf)) {
      colore_pi <- rgb(0.95, 0.76, 0.76, ci_alpha)
      polygon(c(x_seq, rev(x_seq)), c(bande$pi_sup, rev(bande$pi_inf)), col = colore_pi, border = NA)
      lines(x_seq, bande$pi_sup, col = ln_col, lty = 4, lwd = 1.2)
      lines(x_seq, bande$pi_inf, col = ln_col, lty = 4, lwd = 1.2)
    }
    if (!is.null(bande$ci_inf)) {
      if (identical(bande$ci_tipo, "monte_carlo")) {
        polygon(c(x_seq, rev(x_seq)), c(bande$ci_sup, rev(bande$ci_inf)), col = rgb(0.1, 0.7, 0.1, ci_alpha / 2), border = NA)
        lines(x_seq, bande$ci_sup, col = "darkgreen", lty = 3); lines(x_seq, bande$ci_inf, col = "darkgreen", lty = 3)
      } else {
        polygon(c(x_seq, rev(x_seq)), c(bande$ci_sup, rev(bande$ci_inf)), col = rgb(0.7, 0.7, 0.7, ci_alpha), border = NA)
        lines(x_seq, bande$ci_sup, col = "gray50", lty = 3); lines(x_seq, bande$ci_inf, col = "gray50", lty = 3)
      }
    }
    lines(x_seq[is.finite(y_seq)], y_seq[is.finite(y_seq)], col = ln_col, lwd = ln_lwd, lty = ln_lty)
  }
}

# titolo_forzato: title to be always shown (Batch, combined images);
# limiti_personalizzati = FALSE ignores the axis limits set for
# Single Fit. With the default values the plot is the usual one.
disegna_grafico_residui <- function(res, titolo_forzato = NULL, limiti_personalizzati = TRUE) {
  titolo_main <- if (!is.null(titolo_forzato)) titolo_forzato else if(input$mostra_titolo) "Residual Analysis Diagnostics" else ""
  if (is.null(res) || !res$successo) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type="n", main=if(input$mostra_titolo) "Waiting for optimization..." else "", axes=FALSE, xlab="", ylab="")
    return(invisible(NULL))
  }
  
  pt_col  <- if(is.null(input$pt_col_res)) "#2c3e50" else input$pt_col_res
  ln_col  <- if(is.null(input$ln_col_res)) "#e74c3c" else input$ln_col_res
  pt_cex  <- if(is.null(input$pt_cex_res)) 1.3 else input$pt_cex_res
  grid_on <- if(is.null(input$mostra_griglia)) TRUE else input$mostra_griglia
  pt_pch  <- as.numeric(if(is.null(input$pt_pch_res)) "17" else input$pt_pch_res)
  fnt_cex <- if(is.null(input$fnt_cex_res)) 1.0 else input$fnt_cex_res
  ln_lty_res <- as.numeric(if(is.null(input$ln_lty_res)) "2" else input$ln_lty_res)
  ln_lwd_res <- if(is.null(input$ln_lwd_res)) 2 else input$ln_lwd_res
  
  df <- res$df_originale
  # With weighted regression: weighted residuals sqrt(w)(y - yhat).
  dg <- tryCatch(diagnostica_residui(res), error = function(e) NULL)
  pesato <- ponderazione_attiva(res)
  res$residui <- residui_diagnostici(res)
  par(mar = c(5, 5, if(input$mostra_titolo || !is.null(titolo_forzato)) 4 else 2, 2) + 0.1)
  limiti_x <- if (limiti_personalizzati) calcola_limiti(input$range_x_min, input$range_x_max, df$x) else calcola_limiti(NA, NA, df$x)
  
  if (limiti_personalizzati && range_personalizzato_attivo(input$range_y_min_res, input$range_y_max_res)) {
    limiti_y_res <- c(input$range_y_min_res, input$range_y_max_res)
  } else {
    limiti_y_res <- NULL
  }
  
  # Points always; optional connecting line, always in the order of x
  # (previously type = "b" connected the residuals in the order of the data, with vertical
  # zigzags between replicates and jumps back and forth with unsorted data).
  # With replicates: by default no line between the single residuals, and the mean
  # of the residuals per x (systematic trend, i.e. lack of fit).
  repliche <- isTRUE(dg$ha_repliche)
  collega <- if (is.null(input$res_collega_punti)) !repliche else isTRUE(input$res_collega_punti)
  mostra_medie <- repliche && (is.null(input$res_mostra_medie) || isTRUE(input$res_mostra_medie))
  plot(res$x, res$residui, type = "p", main = titolo_main, col = pt_col, pch = pt_pch, cex = pt_cex, 
       cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1, las = 1,
       xlab = interpreta_etichetta(input$label_x), ylab = if (pesato) "Weighted residual \u221aw (Observed - Predicted)" else "Residual (Observed - Predicted)", xlim = limiti_x, ylim = limiti_y_res)
  if (collega) { o <- order(res$x); lines(res$x[o], res$residui[o], col = pt_col) }
  abline(h = 0, col = ln_col, lty = ln_lty_res, lwd = ln_lwd_res)
  if (mostra_medie) {
    lines(dg$medie_per_x$x, dg$medie_per_x$media, col = ln_col, lwd = 1.5)
    points(dg$medie_per_x$x, dg$medie_per_x$media, pch = 23, col = ln_col, bg = ln_col, cex = pt_cex)
    legend("topright", legend = "Mean residual per x", pch = 23, pt.bg = ln_col, col = ln_col, lwd = 1.5, bty = "n", cex = 0.8 * fnt_cex)
  }
  if(grid_on) grid()
}

disegna_grafico_qq <- function(res, titolo_forzato = NULL, limiti_personalizzati = TRUE) {
  titolo_main <- if (!is.null(titolo_forzato)) titolo_forzato else if(input$mostra_titolo) "Normal Q-Q Plot of Residuals" else ""
  if (is.null(res) || !res$successo) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type="n", main=if(input$mostra_titolo) "Waiting for optimization..." else "", axes=FALSE, xlab="", ylab="")
    return(invisible(NULL))
  }
  
  pt_col  <- if(is.null(input$pt_col_qq)) "#2c3e50" else input$pt_col_qq
  ln_col  <- if(is.null(input$ln_col_qq)) "#e74c3c" else input$ln_col_qq
  pt_cex  <- if(is.null(input$pt_cex_qq)) 1.3 else input$pt_cex_qq
  grid_on <- if(is.null(input$mostra_griglia)) TRUE else input$mostra_griglia
  pt_pch  <- as.numeric(if(is.null(input$pt_pch_qq)) "17" else input$pt_pch_qq)
  fnt_cex <- if(is.null(input$fnt_cex_qq)) 1.0 else input$fnt_cex_qq
  ln_lty_qq <- as.numeric(if(is.null(input$ln_lty_qq)) "2" else input$ln_lty_qq)
  ln_lwd_qq <- if(is.null(input$ln_lwd_qq)) 2 else input$ln_lwd_qq
  
  par(mar = c(5, 5, if(input$mostra_titolo || !is.null(titolo_forzato)) 4 else 2, 2) + 0.1)
  residui_qq <- residui_diagnostici(res)
  residui_validi <- residui_qq[is.finite(residui_qq)]
  
  if (length(residui_validi) < 3) {
    plot(1, type="n", main="Insufficient residuals for Q-Q plot.", axes=FALSE, xlab="", ylab="")
    return(invisible(NULL))
  }
  
  qq_dati <- qqnorm(residui_validi, plot.it = FALSE)
  
  limiti_x_qq <- if (limiti_personalizzati && range_personalizzato_attivo(input$range_x_min_qq, input$range_x_max_qq)) c(input$range_x_min_qq, input$range_x_max_qq) else NULL
  limiti_y_qq <- if (limiti_personalizzati && range_personalizzato_attivo(input$range_y_min_qq, input$range_y_max_qq)) c(input$range_y_min_qq, input$range_y_max_qq) else NULL
  
  plot(qq_dati$x, qq_dati$y, main = titolo_main, col = pt_col, pch = pt_pch, cex = pt_cex,
       cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1, las = 1,
       xlab = "Theoretical Quantiles", ylab = if (ponderazione_attiva(res)) "Sample Quantiles (Weighted residuals)" else "Sample Quantiles (Residuals)", xlim = limiti_x_qq, ylim = limiti_y_qq)
  if(grid_on) grid()
  qqline(residui_validi, col = ln_col, lwd = ln_lwd_qq, lty = ln_lty_qq)
}

# ---- Parameter Distributions (Monte Carlo), one panel per parameter ----
# Number of available panels (0 = section hidden: no fit, or fit
# without Monte Carlo).
n_pannelli_distribuzioni_sf <- function() {
  res <- tryCatch(elaborazione(), error = function(e) NULL)
  if (is.null(res) || !isTRUE(res$successo) || is.null(res$mat_boot_params)) 0L else ncol(res$mat_boot_params)
}

# Draws the bootstrap distribution of parameter i (histogram, density
# and vertical line at the point estimate). Used by the single plots, by
# their downloads, by the ZIP, by the combined image and by the single figure
# of "Download All Plots (ZIP)" - a single place in which the drawing is
# defined.
disegna_distribuzione_pannello <- function(i, res = tryCatch(elaborazione(), error = function(e) NULL)) {
  par(mar = c(4.5, 4.5, if (isTRUE(input$mostra_titolo)) 3 else 1, 1))
  if (is.null(res) || !isTRUE(res$successo) || is.null(res$mat_boot_params) || i > ncol(res$mat_boot_params)) {
    plot(1, type = "n", axes = FALSE, xlab = "", ylab = "", main = "Available only with Monte Carlo method.")
    return(invisible(NULL))
  }
  bar_col <- if (is.null(input$bar_col_dist)) "#f39c12" else input$bar_col_dist
  dns_col <- if (is.null(input$dens_col_dist)) "black" else input$dens_col_dist
  vln_col <- if (is.null(input$vln_col_dist)) "black" else input$vln_col_dist
  vln_lty_dist <- as.numeric(if (is.null(input$vln_lty_dist)) "2" else input$vln_lty_dist)
  vln_lwd_dist <- if (is.null(input$vln_lwd_dist)) 2 else input$vln_lwd_dist
  fnt_cex <- if (is.null(input$fnt_cex_dist)) 1.0 else input$fnt_cex_dist
  n_bins_dist <- if (is.null(input$n_bins_dist)) 30 else input$n_bins_dist
  
  dati_param <- res$mat_boot_params[, i]
  simbolo <- interpreta_etichetta(simbolo_visualizzazione(names(res$parametri)[i]))
  if (all(is.na(dati_param))) {
    plot(1, type = "n", axes = FALSE, xlab = "", ylab = "", main = "No valid bootstrap values for this parameter.")
    return(invisible(NULL))
  }
  titolo_locale <- if (isTRUE(input$mostra_titolo)) {
    if (is.character(simbolo)) paste("Distribution of", simbolo) else bquote("Distribution of" ~ .(simbolo))
  } else ""
  xlab_locale <- if (is.character(simbolo)) paste("Parameter", simbolo, "Value") else bquote("Parameter" ~ .(simbolo) ~ "Value")
  hist(dati_param, breaks = n_bins_dist, probability = TRUE, main = titolo_locale,
       xlab = xlab_locale,
       col = bar_col, border = "white", las = 1, cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1)
  if (is.null(input$mostra_densita_dist) || isTRUE(input$mostra_densita_dist)) lines(density(dati_param, na.rm = TRUE), col = dns_col, lwd = 2)
  if (is.null(input$mostra_vln_dist) || isTRUE(input$mostra_vln_dist)) abline(v = res$parametri[i], col = vln_col, lwd = vln_lwd_dist, lty = vln_lty_dist)
}

# Single figure with all parameters (2 columns), used only by "Download
# All Plots (ZIP)" of Single Fit (export_dati.R), which saves one figure per
# type of plot. Reuses disegna_distribuzione_pannello() for each panel.
disegna_grafico_distribuzioni <- function(res) {
  if (is.null(res) || !res$successo) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type="n", main=if(input$mostra_titolo) "Waiting for optimization..." else "", axes=FALSE, xlab="", ylab="")
    return(invisible(NULL))
  }
  if (is.null(res$mat_boot_params)) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type="n", main=if(input$mostra_titolo) "Available only with Monte Carlo method." else "", axes=FALSE, xlab="", ylab="")
    return(invisible(NULL))
  }
  n_params <- ncol(res$mat_boot_params)
  cols <- min(2, n_params)
  rows <- ceiling(n_params / cols)
  par(mfrow = c(rows, cols))
  for (i in seq_len(n_params)) disegna_distribuzione_pannello(i, res)
  par(mfrow = c(1, 1))
}

# ============================
# PARAMETER SENSITIVITY ANALYSIS
# ============================
# Normalized (dimensionless) local sensitivity around the optimal estimate:
# S_j(x) = (dy/dtheta_j) * (theta_j / y(x)), interpretable as "percentage
# change of y for a 1% change in parameter j", at each x.
# Reuses the same helper (passo_derivata) already used for the CI/PI bands and the
# Delta method - no new computation, only a different presentation.
disegna_grafico_sensibilita <- function(res) {
  if (is.null(res) || !res$successo) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type = "n", main = "Run a successful optimization first.", axes = FALSE, xlab = "", ylab = "")
    return(invisible(NULL))
  }
  
  x_seq <- res$x_griglia
  n_par <- length(res$parametri)
  nomi_par <- names(res$parametri)
  y_base <- res$valuta(res$parametri, x_seq)
  
  sensibilita <- matrix(NA_real_, nrow = length(x_seq), ncol = n_par)
  for (j in seq_len(n_par)) {
    h_j <- passo_derivata(res$parametri[j])
    p_piu <- res$parametri; p_piu[j] <- p_piu[j] + h_j
    p_meno <- res$parametri; p_meno[j] <- p_meno[j] - h_j
    dydtheta <- (res$valuta(p_piu, x_seq) - res$valuta(p_meno, x_seq)) / (2 * h_j)
    # Protection against division by y_base ~ 0 (points where the model passes through zero)
    sensibilita[, j] <- ifelse(abs(y_base) > 1e-10, dydtheta * (res$parametri[j] / y_base), NA)
  }
  
  tipo_palette_sens <- if (is.null(input$sens_palette)) "fissa" else input$sens_palette
  colori_usati <- switch(tipo_palette_sens,
    "rainbow" = rainbow(n_par),
    "viridis" = hcl.colors(n_par, palette = "viridis"),
    "plasma" = hcl.colors(n_par, palette = "plasma"),
    "cividis" = hcl.colors(n_par, palette = "cividis"),
    "spectral" = hcl.colors(n_par, palette = "spectral"),
    "heat" = hcl.colors(n_par, palette = "heat"),
    rep_len(c("#e74c3c", "#2980b9", "#27ae60", "#f39c12", "#8e44ad", "#16a085", "#c0392b", "#34495e"), n_par)
  )
  
  fnt_cex   <- if (is.null(input$fnt_cex_sens)) 1.0 else input$fnt_cex_sens
  grid_on   <- if (is.null(input$mostra_griglia)) TRUE else input$mostra_griglia
  ln_lwd    <- if (is.null(input$ln_lwd_sens)) 2.5 else input$ln_lwd_sens
  mostra_curva <- if (is.null(input$mostra_curva_sens)) TRUE else input$mostra_curva_sens
  mostra_legenda_sens <- if (is.null(input$mostra_legenda_sens)) TRUE else input$mostra_legenda_sens
  
  titolo <- if (input$mostra_titolo) "Local Parameter Sensitivity Analysis" else ""
  # Enlarged right margin to make room for the second axis (predicted curve)
  par(mar = c(5, 5, if (input$mostra_titolo) 4 else 2, if (mostra_curva) 5 else 2) + 0.1)
  plot(1, type = "n", xlim = range(x_seq), ylim = range(sensibilita, na.rm = TRUE, finite = TRUE),
       main = titolo, xlab = interpreta_etichetta(input$label_x), ylab = "Normalized Sensitivity (% change in y per 1% change in parameter)", 
       las = 1, cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1)
  if (grid_on) grid(col = "gray90", lty = "dotted")
  abline(h = 0, col = "gray50", lty = 1)
  for (j in seq_len(n_par)) {
    lines(x_seq, sensibilita[, j], col = colori_usati[j], lwd = ln_lwd)
  }
  cex_legenda_sens <- if (is.null(input$sens_cex_legenda)) 0.85 else input$sens_cex_legenda
  pos_legenda_sens <- if (is.null(input$sens_pos_legenda)) "topright" else input$sens_pos_legenda
  if (mostra_legenda_sens) legend(pos_legenda_sens, legend = costruisci_legenda_simboli(nomi_par), col = colori_usati, lwd = ln_lwd, bty = "o", cex = cex_legenda_sens, bg = "white")
  
  # Predicted curve overlaid as a visual reference (dashed grey,
  # secondary axis on the right: units and scale different from the sensitivity, a
  # shared axis would make no sense).
  if (mostra_curva) {
    par(new = TRUE)
    plot(x_seq, y_base, type = "l", col = "gray50", lty = 2, lwd = 1.5, axes = FALSE, xlab = "", ylab = "",
         xlim = range(x_seq))
    axis(4, las = 1, col.axis = "gray50", col = "gray50", cex.axis = fnt_cex * 0.9)
    mtext("Predicted Y (reference curve)", side = 4, line = 3, col = "gray50", cex = fnt_cex * 0.85)
  }
}

# ============================
# PARAMETER CORRELATION MATRIX (numeric table)
# ============================
# From the Hessian (Linear method, cov2cor on res$cov) or from the bootstrap (Monte
# Carlo, cor() on the matrix of sampled parameters) - whichever is
# available depending on the chosen error method.

# Shared helper (used by the numeric table):
# returns the correlation matrix, or NULL if it cannot be computed.
calcola_matrice_correlazione <- function(res) {
  if (input$metodo_errore == "monte_carlo" && !is.null(res$mat_boot_params) && nrow(res$mat_boot_params) >= 10) {
    mat_corr <- tryCatch(cor(res$mat_boot_params, use = "pairwise.complete.obs"), error = function(e) NULL)
  } else if (!is.null(res$cov) && !anyNA(res$cov)) {
    mat_corr <- tryCatch(cov2cor(res$cov), error = function(e) NULL)
  } else {
    return(NULL)
  }
  if (is.null(mat_corr) || anyNA(mat_corr)) return(NULL)
  colnames(mat_corr) <- rownames(mat_corr) <- names(res$parametri)
  mat_corr
}

# ============================
# PAIRWISE BOOTSTRAP SCATTER PLOT MATRIX
# ============================
# Cloud of bootstrap points for each pair of parameters, using pairs() of
# base R: automatically shows ALL pairwise combinations in a single
# grid, without needing to choose which pair to see.
disegna_pairs_bootstrap <- function(res) {
  if (is.null(res) || !res$successo || input$metodo_errore != "monte_carlo" || is.null(res$mat_boot_params)) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type = "n", main = "Available only after a successful Monte Carlo optimization.", axes = FALSE, xlab = "", ylab = "")
    return(invisible(NULL))
  }
  mat_boot <- res$mat_boot_params
  colnames(mat_boot) <- names(res$parametri)
  mat_boot <- mat_boot[complete.cases(mat_boot), , drop = FALSE]
  if (nrow(mat_boot) < 10 || ncol(mat_boot) < 2) {
    par(mar = c(5, 5, 4, 2) + 0.1)
    plot(1, type = "n", main = "Not enough valid bootstrap draws, or only one free parameter.", axes = FALSE, xlab = "", ylab = "")
    return(invisible(NULL))
  }
  titolo <- if (input$mostra_titolo) "Bootstrap Parameter Cloud (Pairwise)" else ""
  pt_col   <- if (is.null(input$pt_col_pairs)) "#2980b9" else input$pt_col_pairs
  pt_cex   <- if (is.null(input$pt_cex_pairs)) 0.8 else input$pt_cex_pairs
  pt_alpha <- if (is.null(input$pt_alpha_pairs)) 0.4 else input$pt_alpha_pairs
  mostra_contour <- if (is.null(input$mostra_contour_pairs)) TRUE else input$mostra_contour_pairs
  
  # Custom panel: draws the points as before, and if requested overlays
  # the density contour lines (bivariate Gaussian kernel estimate,
  # base R only - see kde2d_base()).
  col_contour <- if (is.null(input$col_contour_pairs)) "#2c3e50" else input$col_contour_pairs
  lty_contour <- if (is.null(input$lty_contour_pairs)) 1 else as.numeric(input$lty_contour_pairs)
  lwd_contour <- if (is.null(input$lwd_contour_pairs)) 1 else input$lwd_contour_pairs
  
  pannello_punti_contour <- function(x, y, ...) {
    points(x, y, pch = 16, cex = pt_cex, col = adjustcolor(pt_col, alpha.f = pt_alpha))
    if (mostra_contour) {
      dens <- kde2d_base(x, y)
      if (!is.null(dens)) {
        contour(dens$x, dens$y, dens$z, add = TRUE, drawlabels = FALSE, col = col_contour, lty = lty_contour, lwd = lwd_contour)
      }
    }
  }
  
  pairs(mat_boot, labels = costruisci_legenda_simboli(colnames(mat_boot)),
        panel = pannello_punti_contour, main = titolo, gap = 0.5)
}

# ============================
# ENRICHED MODEL FORMULA DISPLAY
# ============================
# Draws the model formula centred, using plotmath (Greek letters,
# superscripts/subscripts) when the Parameter Display Symbols have been set.
# No axis: it is just text centred on an empty canvas.
# Base R has no native function for rectangles with rounded corners
# (rect() draws only sharp corners) - I build it by approximating each
# corner with a circular arc of radius "raggio" (25 points each),
# connected into a single polygon. Shared by the three "boxed" equations
# of the app (main fit, Shelf Life Batch, Shelf Life Model Comparison).
disegna_rettangolo_arrotondato <- function(x0, y0, x1, y1, raggio, ...) {
  n <- 25
  t_bl <- seq(pi, 3 * pi / 2, length.out = n)
  bl <- cbind(x0 + raggio + raggio * cos(t_bl), y0 + raggio + raggio * sin(t_bl))
  t_br <- seq(3 * pi / 2, 2 * pi, length.out = n)
  br <- cbind(x1 - raggio + raggio * cos(t_br), y0 + raggio + raggio * sin(t_br))
  t_tr <- seq(0, pi / 2, length.out = n)
  tr <- cbind(x1 - raggio + raggio * cos(t_tr), y1 - raggio + raggio * sin(t_tr))
  t_tl <- seq(pi / 2, pi, length.out = n)
  tl <- cbind(x0 + raggio + raggio * cos(t_tl), y1 - raggio + raggio * sin(t_tl))
  punti <- rbind(bl, br, tr, tl)
  polygon(punti[, 1], punti[, 2], ...)
}

disegna_formula_modello <- function(res) {
  par(mar = c(0.2, 0.2, 0.2, 0.2))
  plot.new()
  if (is.null(res) || !isTRUE(res$successo)) {
    disegna_rettangolo_arrotondato(0, 0, 1, 1, raggio = 0.06, col = "#f8f9fa", border = "#dee2e6", lwd = 1.5)
    text(0.5, 0.5, "Run a successful optimization to see the model equation here.", cex = 1.0, col = "#7f8c8d")
    return(invisible(NULL))
  }
  # "Card" background consistent with the style already used for the "Active
  # function" box in the sidebar (same light green/teal border), instead of the
  # plain white background of before - gives the equation a distinct visual
  # frame, instead of floating on a bare background.
  disegna_rettangolo_arrotondato(0, 0, 1, 1, raggio = 0.06, col = "#f0faf8", border = "#18bc9c", lwd = 2)
  colore_testo <- "black"
  
  testo_sostituito <- costruisci_testo_formula_sostituita(res)
  testo_base <- if (!is.null(testo_sostituito)) testo_sostituito else res$formula
  divisione <- dividi_formula_lunga(testo_base)
  
  # Text size adaptive based on the LONGEST resulting line
  # (no longer on the total length) - a formula split into two
  # balanced lines needs less shrinking than would be needed
  # to fit entirely on a single line.
  lunghezza_riferimento <- max(nchar(divisione$riga1), if (!is.null(divisione$riga2)) nchar(divisione$riga2) else 0)
  # Reference threshold for resizing the font - the
  # container is 8/12 of the page wide (almost the whole main
  # column, not a narrow space), so even a single line
  # of 100-130 characters fits comfortably at full size. A single
  # constant for 1 and 2 lines, since even the longest line resulting
  # from a split into 2 (e.g. Integrated Baranyi Model, longest line 117
  # characters) is of the same order as a whole 1-line formula
  # (e.g. Reparameterized Baranyi, 117 characters) - there is no reason to
  # treat them differently.
  riferimento_cex <- 130
  cex_adattivo <- if (lunghezza_riferimento <= riferimento_cex) 1.7 else max(0.55, 1.7 * (riferimento_cex / lunghezza_riferimento)^0.6)
  
  if (is.null(divisione$riga2)) {
    espr1 <- tryCatch(str2expression(paste0("y == ", divisione$riga1)), error = function(e) NULL)
    if (!is.null(espr1) && length(espr1) == 1) {
      tryCatch({
        text(0.5, 0.5, espr1[[1]], cex = cex_adattivo, font = 3, col = colore_testo)
      }, error = function(e) {
        text(0.5, 0.5, paste("y =", res$formula), cex = min(cex_adattivo, 1.2), family = "mono", col = colore_testo)
      })
    } else {
      text(0.5, 0.5, paste("y =", res$formula), cex = min(cex_adattivo, 1.2), family = "mono", col = colore_testo)
    }
  } else {
    # Line 1: "y = [first part]" - line 2: continues from the operator
    # ("+"/"-") that caused the split, without repeating "y =".
    espr1 <- tryCatch(str2expression(paste0("y == ", divisione$riga1)), error = function(e) NULL)
    espr2 <- tryCatch(str2expression(divisione$riga2), error = function(e) NULL)
    if (!is.null(espr1) && length(espr1) == 1 && !is.null(espr2) && length(espr2) == 1) {
      tryCatch({
        text(0.5, 0.64, espr1[[1]], cex = cex_adattivo, font = 3, col = colore_testo)
        text(0.5, 0.36, espr2[[1]], cex = cex_adattivo, font = 3, col = colore_testo)
      }, error = function(e) {
        text(0.5, 0.5, paste("y =", res$formula), cex = min(cex_adattivo, 1.2), family = "mono", col = colore_testo)
      })
    } else {
      text(0.5, 0.5, paste("y =", res$formula), cex = min(cex_adattivo, 1.2), family = "mono", col = colore_testo)
    }
  }
}
# =============================================================================
# RESIDUAL AND REPLICATE DIAGNOSTICS (Single Fit)
# =============================================================================
# 2x2 grid below the model plot: Residual Analysis, Q-Q plot (already
# existing), Lag plot and plot of the standard deviation against the mean
# (new), and below the grid the tests on the replicates. Everything computed from the
# result of the fit (elaborazione()), without modifying it.
#
# Sources of the procedures:
#  - pure error and lack-of-fit test: van Boekel
#    (2008), ch. 7 and section 7.4.3 (SS_pe with n - f degrees of freedom, f = number
#    of distinct values of x; SS_lof = SSr - SS_pe with f - p; F = ratio of the
#    mean squares, in an ANOVA table); approximate in nonlinear
#    models like the other F-based procedures (Bates & Watts, 1988);
#  - homogeneity of variance: Bartlett and Brown-Forsythe tests (absolute
#    deviations from the median). Levene (deviations from the mean) was excluded:
#    with 3-4 replicates per x it gives 15-20% false positives instead of 5%;
#  - standard deviation - mean relationship: Carroll & Ruppert (1988), section
#    3.3.6, p. 89 (Rodbard's method: regression of log(SD) on log(mean)
#    in the "power-of-the-mean" model, with Raab's correction for the number
#    of replicates); without enough replicates, the plot of the studentized
#    residuals |r|^(2/3) against log(predicted values), section 2.7, pp. 29-31;
#  - lag plot and first-order autocorrelation: NIST/SEMATECH e-Handbook
#    of Statistical Methods; approximate bands +/- 1.96/sqrt(m).
# =============================================================================

# ---- Runs test on the signs of the residuals (van Boekel, 2008, section 7.8) ----
# e: residuals already ordered (by x; means per x if there are replicates). Zero
# residuals excluded. Expected runs R_r = 2 n_p n_n / (n_p + n_n) + 1; variance
# 2 n_p n_n (2 n_p n_n - n_p - n_n) / [(n_p + n_n)^2 (n_p + n_n - 1)]: in the
# book the denominator is printed with (n_p - n_n - 1), a misprint (negative
# or wrong variances; the standard formula agrees with simulation).
# Z_tf = (n_R - R_r + 0.5)/sigma (too few runs if strongly negative),
# Z_tm = (n_R - R_r - 0.5)/sigma (too many if strongly positive); van Boekel
# reports their absolute values and suggests 3 standard deviations as threshold,
# unreachable with fewer than about 14 points. For this reason the judgement is based
# on the exact p-value (Swed & Eisenhart distribution), one-sided.
runs_test_residui <- function(e) {
  e <- e[is.finite(e) & e != 0]; segni <- sign(e)
  np <- sum(segni > 0); nn <- sum(segni < 0); N <- np + nn
  if (np == 0 || nn == 0) return(list(disponibile = FALSE, motivo = "all residuals have the same sign", np = np, nn = nn))
  nR <- 1 + sum(segni[-1] != segni[-N])
  Rr <- 2 * np * nn / N + 1
  s <- sqrt(2 * np * nn * (2 * np * nn - np - nn) / (N^2 * (N - 1)))
  # Exact distribution of the number of runs, given n_p and n_n.
  prob_r <- function(r) { k <- r %/% 2
    if (r %% 2 == 0) 2 * choose(np - 1, k - 1) * choose(nn - 1, k - 1)
    else choose(np - 1, k - 1) * choose(nn - 1, k) + choose(np - 1, k) * choose(nn - 1, k - 1) }
  rr <- 2:N; pr <- sapply(rr, prob_r) / choose(N, np)
  list(disponibile = TRUE, np = np, nn = nn, n_runs = nR, attese = Rr, sigma = s,
       z_tf = (nR - Rr + 0.5) / s, z_tm = (nR - Rr - 0.5) / s,
       p_poche = sum(pr[rr <= nR]), p_troppe = sum(pr[rr >= nR]), p_minimo = min(pr[1], 1))
}

# Residuals for the runs test and for the lag plot: ordered by x; with replicates, the
# mean of the residuals per x (the order of the replicates at the same x is unknown).
# Also used in Model Comparison, to treat all models in the same way.
residui_ordinati_per_x <- function(x, e) {
  ok <- is.finite(x) & is.finite(e); x <- x[ok]; e <- e[ok]; ch <- signif(x, 12); u <- sort(unique(ch))
  if (length(u) < length(ch)) sapply(u, function(v) mean(e[ch == v])) else e[order(x)]
}

# ---- Exponent of the variance function from the replicates ------------------
# Used by the SD vs mean plot and by the engine (zeta = 2b for the weights
# 1/yhat^zeta): same code, therefore same estimate. repl = rows of the
# table per x with at least 2 replicates.
calcola_sd_media <- function(repl) {
  correzione_raab <- function(m) 0.5 * (digamma((m - 1) / 2) - log((m - 1) / 2))
  ok_sd <- repl$SD > 0 & repl$Mean > 0 & is.finite(repl$SD)
  if (sum(ok_sd) < 3) list(disponibile = FALSE, motivo = if (nrow(repl) < 3) "at least three x values with replicates are needed" else "at least three groups with positive mean and SD are needed",
                                          esclusi = nrow(repl) - sum(ok_sd))
    else {
      d <- repl[ok_sd, ]; d$log_SD_corr <- log(d$SD) - correzione_raab(d$n); d$SD_corr <- exp(d$log_SD_corr)
      fit <- lm(log_SD_corr ~ log(Mean), data = d); ci <- suppressWarnings(confint(fit)[2, ])
      b <- unname(coef(fit)[2])
      riferimenti <- c("0 (constant variance)" = 0, "0.5 (variance proportional to the mean)" = 0.5, "1 (constant coefficient of variation)" = 1)
      dentro <- names(riferimenti)[riferimenti >= ci[1] & riferimenti <= ci[2]]
      list(disponibile = TRUE, dati = d, a = exp(unname(coef(fit)[1])), b = b, ci = unname(ci), gruppi = nrow(d), esclusi = nrow(repl) - nrow(d), compatibili = dentro,
           repliche_diverse = length(unique(d$n)) > 1)
    }
}
stima_potenza_varianza <- function(x, y) {
  g <- raggruppa_per_x(x, y, rep(0, length(x)), y)
  calcola_sd_media(g$tab[g$tab$n >= 2, , drop = FALSE])
}

# ---- Grouping of the observations by value of x -----------------------------
# x compared after rounding to 12 significant digits, so as not to separate
# equal values that differ only by representation errors.
raggruppa_per_x <- function(x, y, residui, previsti) {
  ok <- is.finite(x) & is.finite(y) & is.finite(residui)
  x <- x[ok]; y <- y[ok]; residui <- residui[ok]; previsti <- previsti[ok]
  chiave <- signif(x, 12)
  livelli <- sort(unique(chiave))
  tab <- do.call(rbind, lapply(livelli, function(v) {
    i <- which(chiave == v)
    data.frame(x = x[i[1]], n = length(i), Mean = mean(y[i]), SD = if (length(i) > 1) sd(y[i]) else NA_real_,
               CV_percent = if (length(i) > 1 && mean(y[i]) != 0) 100 * sd(y[i]) / abs(mean(y[i])) else NA_real_,
               Predicted = mean(previsti[i]), Mean_Residual = mean(residui[i]))
  }))
  list(tab = tab, x = x, y = y, residui = residui, chiave = chiave, n = length(x), m = length(livelli))
}

# ---- Computation of all the diagnostics -------------------------------------
diagnostica_residui <- function(res) {
  if (is.null(res) || !isTRUE(res$successo) || is.null(res$df_originale)) return(NULL)
  df <- res$df_originale
  previsti <- df$y - res$residui
  g <- raggruppa_per_x(df$x, df$y, res$residui, previsti)
  tab <- g$tab; p <- length(res$parametri)
  repl <- tab[tab$n >= 2, , drop = FALSE]
  out <- list(gruppi = g, tabella = tab, n = g$n, m = g$m, p = p, n_x_replicati = nrow(repl),
              n_oss_replicate = sum(repl$n), ha_repliche = nrow(repl) >= 1)
  # Weighted regression: the diagnostics based on the residuals use the weighted
  # residuals sqrt(w)(y - yhat), with w = 1/yhat^zeta; homogeneity of variance
  # and the SD vs mean plot remain on the observed data, because they serve to
  # choose the weights. Without weights e_usati coincides with the usual residuals.
  pesato <- ponderazione_attiva(res)
  w_g <- if (pesato) 1 / (g$y - g$residui)^res$ponderazione$zeta else NULL
  e_usati <- if (pesato) g$residui * sqrt(w_g) else g$residui
  out$pesato <- pesato
  out$medie_per_x <- if (pesato) data.frame(x = tab$x, media = sapply(sort(unique(g$chiave)), function(v) mean(e_usati[g$chiave == v])))
                     else data.frame(x = tab$x, media = tab$Mean_Residual)
  
  # Pure error: dispersion of the replicates around their own mean (with
  # weights, weighted sum: the weight is constant within each value of x).
  out$ss_pe <- if (pesato) sum(sapply(split(seq_along(g$y), g$chiave), function(i) w_g[i[1]] * sum((g$y[i] - mean(g$y[i]))^2)))
               else sum(sapply(split(g$y, g$chiave), function(v) sum((v - mean(v))^2)))
  out$df_pe <- g$n - g$m
  
  # Lack-of-fit test: SSE = SS_pe + SS_lof, F = (SS_lof/(m-p)) /
  # (SS_pe/(n-m)). Requires replicates (n > m), m > p and the MSE loss (with the
  # other losses the SSE is not the minimized quantity).
  out$lof <- if (!out$ha_repliche || out$df_pe < 1) list(disponibile = FALSE, motivo = "no replicates")
    else if (g$m <= p) list(disponibile = FALSE, motivo = sprintf("not enough distinct x values (%d) for %d parameters", g$m, p))
    else if (isTRUE(res$criteri_non_disponibili)) list(disponibile = FALSE, motivo = "it requires the MSE loss")
    else {
      sse <- sum(e_usati^2); ss_lof <- max(sse - out$ss_pe, 0); df_lof <- g$m - p
      F <- (ss_lof / df_lof) / (out$ss_pe / out$df_pe)
      list(disponibile = TRUE, sse = sse, ss_lof = ss_lof, df_lof = df_lof, ss_pe = out$ss_pe, df_pe = out$df_pe,
           F = F, p = pf(F, df_lof, out$df_pe, lower.tail = FALSE), s_pe = sqrt(out$ss_pe / out$df_pe), rmse = res$rmse)
    }
  
  # Homogeneity of variance among the groups with at least 2 replicates (at least
  # 2 groups are needed): Bartlett and Brown-Forsythe (one-way ANOVA on the absolute
  # deviations from the median of each group).
  i_rep <- g$chiave %in% signif(repl$x, 12)
  out$omogeneita <- if (nrow(repl) < 2) list(disponibile = FALSE, motivo = if (nrow(repl) == 1) "only one x value has replicates" else "no replicates")
    else tryCatch({
      yy <- g$y[i_rep]; gg <- factor(g$chiave[i_rep])
      bt <- bartlett.test(yy, gg)
      # Brown-Forsythe: one-way analysis of variance on the absolute deviations
      # from the median, only on the groups with at least 4 replicates. With 2 replicates
      # the median coincides with the mean of the pair and the two deviations are
      # identical (within-group variability zero, infinite F, p = 0); with 3
      # the median coincides with one value, which has zero deviation, and the test
      # never rejects (0% rejections in simulation). With 4 replicates: 7%.
      g4 <- names(which(table(gg) >= 4))
      bf <- if (length(g4) >= 2) {
        i4 <- gg %in% g4; y4 <- yy[i4]; f4 <- droplevels(gg[i4])
        z <- abs(y4 - ave(y4, f4, FUN = median)); a <- suppressWarnings(anova(lm(z ~ f4)))
        c(statistica = a$`F value`[1], df1 = a$Df[1], df2 = a$Df[2], p = a$`Pr(>F)`[1], gruppi = length(g4))
      } else NULL
      list(disponibile = TRUE, gruppi = nlevels(gg),
           bartlett = c(statistica = unname(bt$statistic), df = unname(bt$parameter), p = bt$p.value),
           brown_forsythe = bf)
    }, error = function(e) list(disponibile = FALSE, motivo = conditionMessage(e)))
  
  # Standard deviation - mean relationship (Carroll & Ruppert, 1988, section
  # 3.3.6, p. 89): log(SD) = log(a) + b log(mean), on the groups with replicates,
  # SD > 0 and mean > 0 (at least 3 groups are needed). Raab's correction: with normal
  # data E[log s] = log(sigma) + c(m), with c(m) = [digamma((m-1)/2) -
  # log((m-1)/2)]/2 (-0.635, -0.289, -0.184 for m = 2, 3, 4, as in the book);
  # c(m) is subtracted from each log(SD). With the same number of replicates in all
  # groups only the intercept changes; with different numbers the slope b
  # would otherwise be biased.
  out$sd_media <- calcola_sd_media(repl)
  
  # Residual plot for the variance structure without replicates
  # (Carroll & Ruppert, 1988, section 2.7, pp. 29-31, Figure 2.1-2.3):
  # |r|^(2/3) of the studentized residuals r = e / (s sqrt(1 - h)), with the leverages h
  # from the Jacobian, against the logarithm of the predicted values (only predicted > 0).
  # |r|^(2/3) is the cube root of the square: Wilson-Hilferty
  # transformation, which with constant variance and normal data makes a
  # chi-square variable nearly normal.
  out$spread <- tryCatch({
    prev <- g$y - g$residui; s <- sqrt(sum(e_usati^2) / max(g$n - p, 1))
    J <- tryCatch(crea_jacobiano_modello(res$formula, names(res$parametri))(res$parametri, g$x, res$fissi), error = function(e) NULL)
    if (pesato && !is.null(J)) J <- J * sqrt(w_g)
    h <- if (!is.null(J) && nrow(J) == g$n) tryCatch(pmin(pmax(rowSums((J %*% inverti_hessiana(crossprod(J))) * J), 0), 0.99), error = function(e) NULL) else NULL
    studentizzati <- !is.null(h) && all(is.finite(h))
    r <- e_usati / (s * if (studentizzati) sqrt(1 - h) else 1)
    ok <- prev > 0 & is.finite(r)
    list(disponibile = sum(ok) >= 3, x = log(prev[ok]), y = abs(r[ok])^(2/3), studentizzati = studentizzati, esclusi = sum(!ok))
  }, error = function(e) list(disponibile = FALSE))
  
  # First-order autocorrelation of the residuals ordered by x; with replicates,
  # of the mean residuals per x (the order of the replicates at the same x is unknown).
  e <- if (out$ha_repliche) out$medie_per_x$media else e_usati[order(g$x)]
  out$runs <- runs_test_residui(e)
  out$lag <- list(e = e, su_medie = out$ha_repliche, m = length(e),
                  r1 = if (length(e) >= 3 && var(e) > 0) acf(e, lag.max = 1, plot = FALSE)$acf[2] else NA_real_,
                  banda = if (length(e) >= 3) 1.96 / sqrt(length(e)) else NA_real_)
  out
}

diagnostica_corrente <- reactive({
  res <- tryCatch(elaborazione(), error = function(e) NULL)
  tryCatch(diagnostica_residui(res), error = function(e) NULL)
})
ha_repliche_correnti <- function() isTRUE(tryCatch(diagnostica_corrente()$ha_repliche, error = function(e) FALSE))

# Subtitle that shrinks just enough to fit within the width of the
# figure (narrow panels of the combined images); if there is room it stays
# at the requested size, so the single plots do not change.
mtext_adattato <- function(testo, cex, col) {
  larghezza <- strwidth(testo, units = "inches", cex = cex); disponibile <- 0.97 * par("fin")[1]
  if (is.finite(larghezza) && larghezza > disponibile) cex <- cex * disponibile / larghezza
  mtext(testo, side = 3, line = 0.2, cex = cex, col = col)
}

# ---- Empty plot with message ------------------------------------------------
grafico_messaggio <- function(titolo, testo, mostra = isTRUE(input$mostra_titolo)) {
  par(mar = c(5, 5, if (mostra) 4 else 2, 2) + 0.1)
  plot(1, type = "n", axes = FALSE, xlab = "", ylab = "", main = if (mostra) titolo else "")
  text(1, 1, testo, cex = 0.95, col = "#7f8c8d")
}

# ---- Lag plot (style of the residual plot) ----------------------------------
disegna_grafico_lag <- function(res, titolo_forzato = NULL) {
  titolo <- if (is.null(titolo_forzato)) "Lag Plot of Residuals" else titolo_forzato
  mostra_t <- !is.null(titolo_forzato) || isTRUE(input$mostra_titolo)
  if (is.null(res) || !isTRUE(res$successo)) return(grafico_messaggio(titolo, "Waiting for optimization...", mostra_t))
  dg <- diagnostica_residui(res); L <- dg$lag
  if (L$m < 3) return(grafico_messaggio(titolo, "At least three residuals are needed.", mostra_t))
  pt_col  <- if (is.null(input$pt_col_res)) "#2c3e50" else input$pt_col_res
  ln_col  <- if (is.null(input$ln_col_res)) "#e74c3c" else input$ln_col_res
  pt_cex  <- if (is.null(input$pt_cex_res)) 1.3 else input$pt_cex_res
  pt_pch  <- as.numeric(if (is.null(input$pt_pch_res)) "17" else input$pt_pch_res)
  fnt_cex <- if (is.null(input$fnt_cex_res)) 1.0 else input$fnt_cex_res
  ln_lty  <- as.numeric(if (is.null(input$ln_lty_res)) "2" else input$ln_lty_res)
  grid_on <- if (is.null(input$mostra_griglia)) TRUE else input$mostra_griglia
  e <- L$e; m <- length(e)
  etichetta <- if (L$su_medie) "mean residual per x" else "residual"
  par(mar = c(5, 5, if (mostra_t) 4 else 2, 2) + 0.1)
  lim <- range(e) + c(-1, 1) * 0.05 * diff(range(e))
  plot(e[-m], e[-1], main = if (mostra_t) titolo else "", col = pt_col, pch = pt_pch, cex = pt_cex,
       cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1, las = 1, xlim = lim, ylim = lim,
       xlab = paste0("Previous ", etichetta, " (i - 1)"), ylab = paste0("Current ", etichetta, " (i)"))
  abline(h = 0, v = 0, col = ln_col, lty = ln_lty)
  if (grid_on) grid()
  testo <- sprintf("Lag-1 autocorrelation r1 = %.3f (approx. 95%% bounds \u00b1%.3f)%s", L$r1, L$banda, if (m < 10) " \u2014 fewer than 10 values: little information" else "")
  if (!isFALSE(input$res_mostra_sottotitolo)) mtext_adattato(testo, cex = 0.75 * fnt_cex, col = if (is.finite(L$r1) && abs(L$r1) > L$banda) "#d35400" else "#566573")
}

# ---- Variance structure (style of the Q-Q plot) -----------------------------
# With enough replicates: SD (corrected for the number of replicates) against
# mean, on a logarithmic scale, with the estimated line. Otherwise: |r|^(2/3) of the
# studentized residuals against log(predicted values), with a lowess curve.
disegna_grafico_sd_media <- function(res, titolo_forzato = NULL) {
  mostra_t <- !is.null(titolo_forzato) || isTRUE(input$mostra_titolo)
  if (is.null(res) || !isTRUE(res$successo)) return(grafico_messaggio(if (is.null(titolo_forzato)) "Variance Structure" else titolo_forzato, "Waiting for optimization...", mostra_t))
  dg <- diagnostica_residui(res)
  pt_col  <- if (is.null(input$pt_col_qq)) "#2c3e50" else input$pt_col_qq
  ln_col  <- if (is.null(input$ln_col_qq)) "#e74c3c" else input$ln_col_qq
  pt_cex  <- if (is.null(input$pt_cex_qq)) 1.3 else input$pt_cex_qq
  pt_pch  <- as.numeric(if (is.null(input$pt_pch_qq)) "17" else input$pt_pch_qq)
  fnt_cex <- if (is.null(input$fnt_cex_qq)) 1.0 else input$fnt_cex_qq
  ln_lty  <- as.numeric(if (is.null(input$ln_lty_qq)) "2" else input$ln_lty_qq)
  ln_lwd  <- if (is.null(input$ln_lwd_qq)) 2 else input$ln_lwd_qq
  grid_on <- if (is.null(input$mostra_griglia)) TRUE else input$mostra_griglia
  s <- dg$sd_media; sp <- dg$spread
  if (isTRUE(s$disponibile)) {
    titolo <- if (is.null(titolo_forzato)) "Replicate SD vs Mean" else titolo_forzato
    par(mar = c(5, 5, if (mostra_t) 4 else 2, 2) + 0.1)
    plot(s$dati$Mean, s$dati$SD_corr, log = "xy", main = if (mostra_t) titolo else "", col = pt_col, pch = pt_pch, cex = pt_cex,
         cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1, las = 1, xlab = "Mean of replicates (log scale)", ylab = "SD of replicates, bias-corrected (log scale)")
    xs <- exp(seq(log(min(s$dati$Mean)), log(max(s$dati$Mean)), length.out = 100))
    lines(xs, s$a * xs^s$b, col = ln_col, lty = ln_lty, lwd = ln_lwd)
    if (grid_on) grid(equilogs = FALSE)
    if (!isFALSE(input$qq_mostra_sottotitolo)) mtext_adattato(sprintf("SD = a \u00b7 mean^b,  b = %.2f (95%% CI %.2f to %.2f);  \u03b6 = 2b = %.2f (%.2f to %.2f)", s$b, s$ci[1], s$ci[2], 2 * s$b, 2 * s$ci[1], 2 * s$ci[2]), cex = 0.75 * fnt_cex, col = "#566573")
  } else if (isTRUE(sp$disponibile)) {
    titolo <- if (is.null(titolo_forzato)) "Variance Structure (residuals)" else titolo_forzato
    par(mar = c(5, 5, if (mostra_t) 4 else 2, 2) + 0.1)
    plot(sp$x, sp$y, main = if (mostra_t) titolo else "", col = pt_col, pch = pt_pch, cex = pt_cex,
         cex.axis = fnt_cex, cex.lab = fnt_cex * 1.1, las = 1, xlab = "ln(predicted value)",
         ylab = if (sp$studentizzati) expression("|studentized residual|"^{2/3}) else expression("|residual / s|"^{2/3}))
    if (length(unique(sp$x)) >= 4) { lw <- lowess(sp$x, sp$y); lines(lw, col = ln_col, lty = ln_lty, lwd = ln_lwd) }
    if (grid_on) grid()
    if (!isFALSE(input$qq_mostra_sottotitolo)) mtext_adattato("No replicates: a flat trend indicates constant variance, a rising trend variance increasing with the mean", cex = 0.72 * fnt_cex, col = "#566573")
  } else {
    grafico_messaggio(if (is.null(titolo_forzato)) "Variance Structure" else titolo_forzato, if (dg$ha_repliche && !isTRUE(sp$disponibile)) paste0("Not available: ", s$motivo, ".") else "Not available: at least three positive predicted values are needed.")
  }
}

output$grafico_lag <- renderPlot({ par(family = "sans"); disegna_grafico_lag(tryCatch(elaborazione(), error = function(e) NULL)) })
output$grafico_sd_media <- renderPlot({ par(family = "sans"); disegna_grafico_sd_media(tryCatch(elaborazione(), error = function(e) NULL)) })

scarica_grafico_diagnostico <- function(nome, funzione) downloadHandler(
  filename = function() paste0(nome, ".", input$formato_esportazione),
  content = function(file) {
    res <- tryCatch(elaborazione(), error = function(e) NULL)
    dim_exp <- dimensioni_esportazione()
    if (input$formato_esportazione == "pdf") pdf(file, width = dim_exp$width_in, height = dim_exp$height_in)
    else jpeg(file, width = dim_exp$width_px, height = dim_exp$height_px, res = dim_exp$dpi)
    par(family = "sans"); funzione(res); dev.off()
  })
output$scarica_grafico_lag <- scarica_grafico_diagnostico("lag_plot", disegna_grafico_lag)
output$scarica_grafico_sd_media <- scarica_grafico_diagnostico("variance_structure_plot", disegna_grafico_sd_media)

# ---- Tables (interface and exports) -----------------------------------------
tabelle_diagnostica_residui <- function(dg) {
  vuoto <- data.frame(Note = character(0))
  if (is.null(dg)) return(list(Residual_Autocorrelation = vuoto, Runs_Test = vuoto, Replicates = vuoto, Lack_of_Fit = vuoto, Variance_Homogeneity = vuoto))
  L <- dg$lag
  autoc <- data.frame(Residuals_Used = if (L$su_medie) "Mean residual per x (replicates)" else "Residuals ordered by x", Values = L$m,
                      Lag1_Autocorrelation = signif(L$r1, 4), Approx_95_Bound = signif(L$banda, 4),
                      Outside_Bounds = if (is.finite(L$r1)) abs(L$r1) > L$banda else NA, stringsAsFactors = FALSE)
  repl <- if (dg$ha_repliche) { t <- dg$tabella; t[] <- lapply(t, function(v) if (is.numeric(v)) signif(v, 6) else v); names(t)[names(t) == "CV_percent"] <- "CV_%"; t } else vuoto
  lof <- if (isTRUE(dg$lof$disponibile)) with(dg$lof, data.frame(
      Source = c("Lack of fit", "Pure error", "Residual (total)"), SS = signif(c(ss_lof, ss_pe, sse), 6), DF = c(df_lof, df_pe, df_lof + df_pe),
      Mean_Square = signif(c(ss_lof / df_lof, ss_pe / df_pe, sse / (df_lof + df_pe)), 6), F = c(signif(F, 4), NA, NA), P_Value = c(signif(p, 4), NA, NA)))
    else data.frame(Note = paste0("Lack-of-fit test not available: ", dg$lof$motivo, "."))
  om <- if (isTRUE(dg$omogeneita$disponibile)) with(dg$omogeneita, {
      righe <- data.frame(Test = "Bartlett", Statistic = signif(bartlett[["statistica"]], 4), DF = sprintf("%g", bartlett[["df"]]),
                          P_Value = signif(bartlett[["p"]], 4), Groups = gruppi, stringsAsFactors = FALSE)
      riga_scarti <- function(r, nome) if (!is.null(r)) data.frame(Test = nome, Statistic = signif(r[["statistica"]], 4),
                          DF = sprintf("%g, %g", r[["df1"]], r[["df2"]]), P_Value = signif(r[["p"]], 4), Groups = r[["gruppi"]], stringsAsFactors = FALSE)
        else data.frame(Test = nome, Statistic = NA, DF = "", P_Value = NA, Groups = NA, stringsAsFactors = FALSE)
      rbind(righe, riga_scarti(brown_forsythe, "Brown-Forsythe (deviations from the median)")) })
    else data.frame(Note = paste0("Variance homogeneity tests not available: ", dg$omogeneita$motivo, "."))
  R <- dg$runs
  runs <- if (isTRUE(R$disponibile)) data.frame(Residuals_Used = autoc$Residuals_Used, Positive = R$np, Negative = R$nn, Observed_Runs = R$n_runs,
                  Expected_Runs = signif(R$attese, 4), SD_Runs = signif(R$sigma, 4), Z_Too_Few = signif(R$z_tf, 4), Z_Too_Many = signif(R$z_tm, 4),
                  P_Too_Few_Exact = signif(R$p_poche, 4), P_Too_Many_Exact = signif(R$p_troppe, 4), stringsAsFactors = FALSE)
    else data.frame(Note = paste0("Runs test not available: ", R$motivo, "."))
  list(Residual_Autocorrelation = autoc, Runs_Test = runs, Replicates = repl, Lack_of_Fit = lof, Variance_Homogeneity = om)
}

# Robust even if the table is missing (no valid fit): returns NULL
# instead of failing (previously: "colnames" error after an unsuccessful fit).
senza_underscore <- function(df) { if (!is.data.frame(df)) return(NULL); colnames(df) <- gsub("_", " ", colnames(df)); df }
output$tabella_runs <- renderTable({ senza_underscore(tabelle_diagnostica_residui(diagnostica_corrente())$Runs_Test) }, na = "")
output$tabella_lof <- renderTable({ senza_underscore(tabelle_diagnostica_residui(diagnostica_corrente())$Lack_of_Fit) }, na = "")
output$tabella_omogeneita <- renderTable({ senza_underscore(tabelle_diagnostica_residui(diagnostica_corrente())$Variance_Homogeneity) }, na = "")
output$tabella_repliche <- renderTable({ senza_underscore(tabelle_diagnostica_residui(diagnostica_corrente())$Replicates) }, na = "", digits = 6)

# ---- Section below the grid -------------------------------------------------
nota <- function(...) p(style = "font-size: 12px; color: #566573; margin: 4px 0 10px 0;", ...)
# Title of a table with the "Copy to Clipboard" button, as in the other
# tables of the app (JavaScript function copiaTabellaClipboard in ui.R).
titolo_con_copia <- function(titolo, id_tabella, livello = tags$h5) {
  id_bottone <- paste0("btn_copia_", id_tabella)
  tags$div(style = "display: flex; align-items: center; gap: 10px; margin-top: 10px; margin-bottom: 4px;",
    livello(style = "margin: 0;", titolo),
    tags$button(id = id_bottone, "\U0001F4CB Copy to Clipboard", class = "btn btn-outline-secondary btn-sm", style = "padding-top: 2px; padding-bottom: 2px;",
                onclick = sprintf("copiaTabellaClipboard('%s', '%s')", id_tabella, id_bottone)))
}

# id: names of the tables (those of Single Fit by default; Batch passes its own).
ID_TABELLE_SINGLE_FIT <- list(runs = "tabella_runs", lof = "tabella_lof", omogeneita = "tabella_omogeneita", repliche = "tabella_repliche")
sezione_runs <- function(dg, id = ID_TABELLE_SINGLE_FIT) {
  R <- dg$runs
  tagList(
    titolo_con_copia("Residual Randomness: Runs Test", id$runs, tags$h4),
    tableOutput(id$runs),
    if (isTRUE(R$disponibile)) nota(
      sprintf("%d runs of residuals with the same sign, %.2f expected if the residuals are randomly distributed%s. ", R$n_runs, R$attese, if (dg$lag$su_medie) " (mean residual per x, since the data contain replicates)" else ""),
      if (R$p_poche < 0.05) "Too few runs (exact p < 0.05): the residuals form systematic groups of the same sign, which suggests that the model does not follow the shape of the data. "
      else if (R$p_troppe < 0.05) "Too many runs (exact p < 0.05): the residuals alternate in sign more than expected by chance. "
      else "No evidence of non-random residuals (exact p \u2265 0.05). ",
      if (R$p_minimo > 0.05) sprintf("With these %d residuals even the most extreme pattern would give p = %.3f, so the test cannot detect a systematic pattern. ", R$np + R$nn, R$p_minimo) else "",
      "Test as described by van Boekel (2008, section 7.8), who suggests treating |Z| larger than about 3 as a signal; this cut-off cannot be reached with fewer than about 14 residuals, so the exact one-sided p-values are given as well.")
  )
}
output$diagnostica_repliche_ui <- renderUI({
  dg <- diagnostica_corrente()
  if (is.null(dg)) return(NULL)
  tagList(sezione_runs(dg), sezione_repliche(dg))
})
sezione_repliche <- function(dg, id = ID_TABELLE_SINGLE_FIT) {
  if (!dg$ha_repliche) return(nota(tags$strong("Replicate diagnostics: "), "not available, no repeated x values in the data. ",
    "The fourth plot shows the variance structure from the studentized residuals instead (|r|^(2/3) against the logarithm of the predicted values; Carroll & Ruppert, 1988, section 2.7)."))
  sm <- dg$sd_media
  tagList(
    tags$h4("Replicate Diagnostics"),
    nota(sprintf("%d of %d distinct x values have replicates (%d of %d observations).", dg$n_x_replicati, dg$m, dg$n_oss_replicate, dg$n)),
    titolo_con_copia("Lack-of-Fit Test", id$lof),
    tableOutput(id$lof),
    if (isTRUE(dg$lof$disponibile)) nota(
      sprintf("Pure-error standard deviation %.4g (from the replicates) vs residual standard error %.4g. ", dg$lof$s_pe, dg$lof$rmse),
      if (dg$lof$p < 0.05) "The residuals are larger than the scatter of the replicates explains (p < 0.05): the model does not describe the data adequately."
      else "No evidence of lack of fit: the residuals are consistent with the scatter of the replicates (p \u2265 0.05).",
      " The test assumes constant variance: with clearly non-constant variance (see below) it can signal lack of fit even when the model is correct. Test as described by van Boekel (2008, section 7.4.3); for nonlinear models it is approximate, as are the other F-based procedures (Bates & Watts, 1988)."),
    titolo_con_copia("Variance Homogeneity", id$omogeneita),
    tableOutput(id$omogeneita),
    if (isTRUE(dg$omogeneita$disponibile)) nota(
      "Bartlett's test assumes normally distributed data; the Brown-Forsythe test is robust to non-normality",
      if (is.null(dg$omogeneita$brown_forsythe)) " but needs at least two x values with four or more replicates (with two or three replicates the deviations from the median are degenerate and the test cannot detect differences)" else "",
      ". With few replicates per x both tests have low power: a non-significant result does not prove that the variance is constant, so read them together with the SD vs Mean plot."),
    if (isTRUE(sm$disponibile)) nota(tags$strong("SD vs Mean: "),
      sprintf("b = %.2f (95%% CI %.2f to %.2f) from %d groups%s, regressing ln(SD) on ln(mean) with ln(SD) corrected for the number of replicates (Carroll & Ruppert, 1988, section 3.3.6). ", sm$b, sm$ci[1], sm$ci[2], sm$gruppi, if (sm$esclusi > 0) sprintf(" (%d excluded: non-positive mean or SD)", sm$esclusi) else ""),
      if (max(sm$dati$n) <= 3) "With two or three replicates per x the estimate of b is imprecise. " else "",
      if (length(sm$compatibili)) paste0("The interval includes: ", paste(sm$compatibili, collapse = "; "), ".") else "The interval includes none of the reference values 0, 0.5 and 1.",
      sprintf(" Equivalently, \u03b6 = 2b = %.2f (95%% CI %.2f to %.2f) in the variance model var(y) = \u03c3\u00b2\u00b7\u0177^\u03b6, which can be used for the weighting in section 5 (option \u201c\u03b6 = 2b from the replicates\u201d).", 2 * sm$b, 2 * sm$ci[1], 2 * sm$ci[2]),
      " Reference values: b = 0, ordinary least squares are appropriate; b = 0.5, variance proportional to the mean; b = 1, constant coefficient of variation (consider the ln(y) pre-transformation).")
    else nota(tags$strong("SD vs Mean: "), paste0("not available, ", sm$motivo, ".")),
    titolo_con_copia("Replicates", id$repliche),
    tableOutput(id$repliche)
  )
}

