  br <- batch_risultati()
  if (is.null(br) || is.null(br$loss_usata) || identical(br$loss_usata, "mse")) return(NULL)
  p(style = "font-size: 11px; color: #e67e22; margin-top: -6px;", tags$strong("AIC, AICc and BIC: "), NOTA_CRITERI_LOSS)
