# ---- Compact Letter Display (CLD) ----
# Classic format of ANOVA post-hoc tests (e.g. Tukey HSD): two samples
# share a letter if and only if they were NOT found significantly
# different. Standard greedy algorithm: goes through the samples in order, forms a
# group with all those mutually compatible (no significant pair
# within it), assigns a letter, repeats on the remaining ones -
# computed separately for each parameter, since the differences
# can vary from one parameter to another.
assegna_lettere_cld <- function(nomi_campioni, coppie_significative) {
  n <- length(nomi_campioni)
  alfabeto <- letters
  
  e_significativa <- function(a, b) {
    (a %in% names(coppie_significative) && b %in% coppie_significative[[a]]) ||
    (b %in% names(coppie_significative) && a %in% coppie_significative[[b]])
  }
  # Compatible = NOT significantly different. IMPORTANT: vicini() must
  # exclude the node itself - including it (however true "compatible with
  # itself" may be statistically) would prevent Bron-Kerbosch from ever reducing
  # the set P, causing infinite recursion.
  e_compatibile <- function(a, b) !e_significativa(a, b)
  
  vicini <- function(v, insieme) Filter(function(u) u != v && e_compatibile(v, u), insieme)
  
  # Bron-Kerbosch (without pivoting): enumerates ALL the MAXIMAL cliques of the
  # compatibility graph - unlike a simple greedy grouping
  # "assign a letter and move on", this correctly handles
  # non-transitive cases (e.g. sample C compatible with both
  # A and B, but A and B incompatible with each other: C must appear in
  # BOTH cliques/letters, not only in the first one found).
  clique_trovate <- list()
  bron_kerbosch <- function(R, P, X) {
    if (length(P) == 0 && length(X) == 0) {
      clique_trovate[[length(clique_trovate) + 1]] <<- R
      return(invisible(NULL))
    }
    P_corrente <- P
    for (v in P) {
      bron_kerbosch(c(R, v), intersect(P_corrente, vicini(v, nomi_campioni)), intersect(X, vicini(v, nomi_campioni)))
      P_corrente <- setdiff(P_corrente, v)
      X <- c(X, v)
    }
  }
  bron_kerbosch(character(0), nomi_campioni, character(0))
  
  # Sorts the cliques for reproducibility (same order of letters at every
  # run): by first element in common with the original order of the
  # samples, then by size.
  ordine_indice <- function(clique) min(match(clique, nomi_campioni))
  clique_trovate <- clique_trovate[order(sapply(clique_trovate, ordine_indice))]
  
  lettere_assegnate <- setNames(vector("list", n), nomi_campioni)
  for (nc in nomi_campioni) lettere_assegnate[[nc]] <- character(0)
  for (i in seq_along(clique_trovate)) {
    lettera <- alfabeto[i]
    for (c in clique_trovate[[i]]) lettere_assegnate[[c]] <- c(lettere_assegnate[[c]], lettera)
  }
  sapply(nomi_campioni, function(c) paste(sort(lettere_assegnate[[c]]), collapse = ""))
}

batch_tabella_cld_df <- reactive({
  ris <- tryCatch(batch_posthoc_risultato(), error = function(e) NULL)
  br <- batch_risultati()
  if (is.null(ris) || !isTRUE(ris$successo) || is.null(br)) return(NULL)
  
  nomi_campioni <- input$batch_campioni_posthoc
  
  righe <- lapply(seq_along(ris$nomi_parametri_grezzi), function(i) {
    nome_par_grezzo <- ris$nomi_parametri_grezzi[i]
    nome_par_etichettato <- ris$nomi_parametri_etichettati[i]
    sotto <- ris$posthoc[ris$posthoc$Parameter == nome_par_etichettato, ]
    coppie_sig <- list()
    for (j in seq_len(nrow(sotto))) {
      if (identical(sotto$Significant[j], "ns") || identical(sotto$Significant[j], "N/A")) next
      a <- sotto$Sample_A[j]; b <- sotto$Sample_B[j]
      coppie_sig[[a]] <- c(coppie_sig[[a]], b)
    }
    lettere <- assegna_lettere_cld(nomi_campioni, coppie_sig)
    valori <- sapply(nomi_campioni, function(c) br$risultati[[c]]$parametri[[nome_par_grezzo]])
    # unname(): the parameter name arrived with a label, which data.frame()
    # tried to use as row names (warning "row.names ... discarded").
    data.frame(Parameter = unname(nome_par_etichettato), Sample = nomi_campioni, Value = round(unname(valori), 5), Group = lettere,
               stringsAsFactors = FALSE, row.names = NULL)
  })
  do.call(rbind, righe)
})

output$batch_tabella_cld <- renderTable({
  df <- batch_tabella_cld_df()
  if (is.null(df)) return(NULL)
  df
}, striped = TRUE, hover = TRUE, bordered = TRUE, na = "N/A", digits = 4)

output$scarica_batch_csv <- downloadHandler(
  filename = function() paste0("batch_elaboration_", Sys.Date(), ".csv"),
  content = function(file) {
    br <- batch_risultati()
    df_par <- batch_tabella_parametri_df()
    df_diag <- batch_tabella_diagnostica_df()
    if (is.null(df_par)) return()
    ris_test <- tryCatch(batch_test_parametri_risultato(), error = function(e) NULL)
    df_test <- if (!is.null(ris_test) && isTRUE(ris_test$successo)) ris_test$tabella[, setdiff(colnames(ris_test$tabella), "P_Value_Raw")] else data.frame()
    ris_posthoc <- tryCatch(batch_posthoc_risultato(), error = function(e) NULL)
    trasf_y_usata <- if (is.null(input$batch_trasformazione_y) || input$batch_trasformazione_y == "nessuna") "None (raw values)" else {
      scelte_trasf <- costruisci_scelte_trasformazione_y()
      nomi_scelte <- names(scelte_trasf)[scelte_trasf == input$batch_trasformazione_y]
      if (length(nomi_scelte) > 0) nomi_scelte[1] else input$batch_trasformazione_y
    }
    
    cat("--- INFO ---\n", file = file)
    cat(paste0("Y Pre-transformation (applied to all samples): ", trasf_y_usata, "\n"), file = file, append = TRUE)
    cat(paste0("Model: ", input$tipo_modello, "\n"), file = file, append = TRUE)
    cat(paste0("Loss Function: ", input$tipo_loss, "\n"), file = file, append = TRUE)
    cat(paste0("Weighting: ", if (isTRUE(br$pesi_batch$attiva)) descrizione_pesi_batch(br$pesi_batch) else "None", "\n"), file = file, append = TRUE)
    cat("\n--- PARAMETER ESTIMATION RESULTS (ALL SAMPLES) ---\n", file = file, append = TRUE)
    write.table(df_par, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    cat("\n--- FITTING PARAMETERS & GOODNESS-OF-FIT DIAGNOSTICS (ALL SAMPLES) ---\n", file = file, append = TRUE)
    write.table(df_diag, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    df_bdr <- riepilogo_diagnostica_per_export()
    if (!is.null(df_bdr)) {
      cat("\n--- RESIDUAL DIAGNOSTICS (ALL SAMPLES) ---\n", file = file, append = TRUE)
      write.table(df_bdr, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE, na = "")
    }
    if (nrow(df_test) > 0) {
      cat("\n--- PARAMETER SIGNIFICANCE TEST (2 SAMPLES) ---\n", file = file, append = TRUE)
      write.table(df_test, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
    }
    if (!is.null(ris_posthoc) && isTRUE(ris_posthoc$successo)) {
      cat("\n--- POST-HOC COMPARISON: OMNIBUS TEST (COCHRAN'S Q, 3+ SAMPLES) ---\n", file = file, append = TRUE)
      write.table(ris_posthoc$omnibus, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
      cat("\n--- POST-HOC COMPARISON: PAIRWISE (", toupper(etichetta_correzione(ris_posthoc$metodo_correzione)), " CORRECTED WITHIN EACH PARAMETER) ---\n", file = file, append = TRUE, sep = "")
      write.table(ris_posthoc$posthoc, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
      df_cld <- batch_tabella_cld_df()
      if (!is.null(df_cld)) {
        cat("\n--- POST-HOC COMPARISON: COMPACT LETTER DISPLAY ---\n", file = file, append = TRUE)
        write.table(df_cld, file, sep = ",", row.names = FALSE, append = TRUE, col.names = TRUE)
      }
    }
  }
)

output$scarica_batch_excel <- downloadHandler(
  filename = function() paste0("batch_elaboration_", Sys.Date(), ".xlsx"),
  content = function(file) {
    br <- batch_risultati()
    df_par <- batch_tabella_parametri_df()
    df_diag <- batch_tabella_diagnostica_df()
    if (is.null(df_par)) return()
    trasf_y_usata <- if (is.null(input$batch_trasformazione_y) || input$batch_trasformazione_y == "nessuna") "None (raw values)" else {
      scelte_trasf <- costruisci_scelte_trasformazione_y()
      nomi_scelte <- names(scelte_trasf)[scelte_trasf == input$batch_trasformazione_y]
      if (length(nomi_scelte) > 0) nomi_scelte[1] else input$batch_trasformazione_y
    }
    df_info <- data.frame(Property = c("Y Pre-transformation (applied to all samples)", "Model", "Loss Function", "Weighting"),
                          Value = c(trasf_y_usata, input$tipo_modello, input$tipo_loss,
                                    if (isTRUE(br$pesi_batch$attiva)) descrizione_pesi_batch(br$pesi_batch) else "None"), stringsAsFactors = FALSE)
    ris_test <- tryCatch(batch_test_parametri_risultato(), error = function(e) NULL)
    df_test <- if (!is.null(ris_test) && isTRUE(ris_test$successo)) ris_test$tabella[, setdiff(colnames(ris_test$tabella), "P_Value_Raw")] else data.frame()
    ris_posthoc <- tryCatch(batch_posthoc_risultato(), error = function(e) NULL)
    fogli <- list(Info = df_info, Parameter_Estimates = df_par, Diagnostics = df_diag)
    df_bdr <- riepilogo_diagnostica_per_export()
    if (!is.null(df_bdr)) fogli$Residual_Diagnostics <- df_bdr
    if (nrow(df_test) > 0) fogli$Significance_Test <- df_test
    if (!is.null(ris_posthoc) && isTRUE(ris_posthoc$successo)) {
      fogli$PostHoc_Omnibus <- ris_posthoc$omnibus
      fogli$PostHoc_Pairwise <- ris_posthoc$posthoc
      df_cld <- batch_tabella_cld_df()
      if (!is.null(df_cld)) fogli$PostHoc_CLD <- df_cld
    }
    writexl::write_xlsx(per_excel(fogli), path = file)
  }
)

# =============================================================================
# RESIDUAL DIAGNOSTICS IN BATCH
# =============================================================================
# Below the "Goodness-of-Fit Diagnostics" table of Batch: "Compute
# residual diagnostics" button, summary table (one row per sample), selector
# of a sample or of "All samples" (arrangement by sample or by type of
# plot), single downloads, combined images and ZIP in folders.
# Reuses without modifying them the diagnostic functions of Single Fit
# (diagnostica_residui.R): each sample is transformed into the same form
# as the Single Fit result by res_da_campione_batch(). Prefix of the
# identifiers: bdr_ ("batch_diag_" is already used for the sorting of the
# goodness-of-fit table).
# =============================================================================

TIPI_GRAFICI_DIAGNOSTICI <- list(
  residui  = list(etichetta = "Residuals",          file = "residuals",          disegna = function(r, t = NULL) disegna_grafico_residui(r, t, limiti_personalizzati = FALSE)),
  qq       = list(etichetta = "Normal Q-Q plot",    file = "qq_plot",            disegna = function(r, t = NULL) disegna_grafico_qq(r, t, limiti_personalizzati = FALSE)),
  lag      = list(etichetta = "Lag plot",           file = "lag_plot",           disegna = function(r, t = NULL) disegna_grafico_lag(r, t)),
  varianza = list(etichetta = "Variance structure", file = "variance_structure", disegna = function(r, t = NULL) disegna_grafico_sd_media(r, t))
)
ID_TABELLE_BATCH <- list(runs = "bdr_tab_runs", lof = "bdr_tab_lof", omogeneita = "bdr_tab_omogeneita", repliche = "bdr_tab_repliche")
SCELTA_TUTTI_CAMPIONI <- "__tutti__"

nome_file_sicuro <- function(x) gsub("^_+|_+$", "", gsub("[^A-Za-z0-9._-]+", "_", x))

# A Batch sample in the form of the Single Fit result: data used
# in the fit (after any transformations), residuals recomputed from the formula
# exactly as in Batch, free and fixed parameters, weights.
res_da_campione_batch <- function(r, formula, fissi, loss) {
  if (is.null(r) || !isTRUE(r$successo) || is.null(r$x) || is.null(r$y)) return(NULL)
  prev <- tryCatch(valuta_formula_generica(formula, c(as.list(r$parametri), fissi), r$x), error = function(e) NULL)
  if (is.null(prev) || length(prev) != length(r$y) || any(!is.finite(prev))) return(NULL)
  list(successo = TRUE, df_originale = data.frame(x = r$x, y = r$y), x = r$x, residui = r$y - prev,
       parametri = r$parametri, formula = formula, fissi = fissi, criteri_non_disponibili = !identical(loss, "mse"),
       rmse = r$rmse, df = r$df, ponderazione = r$ponderazione, pesi = r$pesi)
}

# Summary table: one row per sample, numbers only.
riepilogo_diagnostica_batch <- function(lista_res) {
  righe <- lapply(names(lista_res), function(nm) {
    r <- lista_res[[nm]]
    if (is.null(r)) return(data.frame(Sample = nm, N = NA_integer_, Note = "fit failed or not available", stringsAsFactors = FALSE))
    dg <- tryCatch(diagnostica_residui(r), error = function(e) NULL)
    if (is.null(dg)) return(data.frame(Sample = nm, N = NA_integer_, Note = "diagnostics not available", stringsAsFactors = FALSE))
    riga <- data.frame(Sample = nm, N = dg$n,
      Lag1_Autocorrelation = signif(dg$lag$r1, 3), Lag1_Bound = signif(dg$lag$banda, 3),
      Runs_Z_Too_Few = if (isTRUE(dg$runs$disponibile)) signif(dg$runs$z_tf, 3) else NA_real_,
      Runs_P_Too_Few = if (isTRUE(dg$runs$disponibile)) signif(dg$runs$p_poche, 3) else NA_real_,
      LOF_F = if (isTRUE(dg$lof$disponibile)) signif(dg$lof$F, 4) else NA_real_,
      LOF_P = if (isTRUE(dg$lof$disponibile)) signif(dg$lof$p, 3) else NA_real_,
      Bartlett_P = if (isTRUE(dg$omogeneita$disponibile)) signif(dg$omogeneita$bartlett[["p"]], 3) else NA_real_,
      Brown_Forsythe_P = if (isTRUE(dg$omogeneita$disponibile) && !is.null(dg$omogeneita$brown_forsythe)) signif(dg$omogeneita$brown_forsythe[["p"]], 3) else NA_real_,
      b = if (isTRUE(dg$sd_media$disponibile)) signif(dg$sd_media$b, 3) else NA_real_,
      Zeta_2b = if (isTRUE(dg$sd_media$disponibile)) signif(2 * dg$sd_media$b, 3) else NA_real_,
      stringsAsFactors = FALSE)
    if (ponderazione_attiva(r)) riga$Weighting_Zeta <- signif(r$ponderazione$zeta, 4)
    riga
  })
  rbind_riempi_na(righe)
}

# Version for the screen: p < 0.05 and autocorrelation outside the band in
# orange, column names without underscores.
riepilogo_per_schermo <- function(df) {
  if (is.null(df)) return(NULL)
  evidenzia <- function(v, cond) ifelse(is.na(v), "", ifelse(cond & !is.na(cond), sprintf("<span style='color:#d35400;font-weight:bold;'>%s</span>", format(v)), format(v)))
  out <- df
  for (cl in intersect(c("Runs_P_Too_Few", "LOF_P", "Bartlett_P", "Brown_Forsythe_P"), names(df))) out[[cl]] <- evidenzia(df[[cl]], df[[cl]] < 0.05)
  if ("Lag1_Autocorrelation" %in% names(df)) out$Lag1_Autocorrelation <- evidenzia(df$Lag1_Autocorrelation, abs(df$Lag1_Autocorrelation) > df$Lag1_Bound)
  for (cl in names(out)) if (!is.character(out[[cl]])) out[[cl]] <- ifelse(is.na(out[[cl]]), "", format(out[[cl]]))
  colnames(out) <- gsub("_", " ", colnames(out))
  out
}

# ---- State ----
bdr_stato <- reactiveVal(NULL)
bdr_osservatori_stile <- character(0)
# A new Run of Batch invalidates the diagnostics previously computed.
observeEvent(batch_risultati(), { bdr_stato(NULL) }, ignoreInit = TRUE, ignoreNULL = FALSE)
bdr_valido <- function() { s <- bdr_stato(); if (!is.null(s) && identical(s$br, batch_risultati())) s else NULL }

dimensioni_bdr <- function() dimensioni_esportazione()
apri_dispositivo_bdr <- function(percorso, fattore_w = 1, fattore_h = 1) {
  d <- dimensioni_bdr()
  if (identical(input$formato_esportazione, "pdf")) pdf(percorso, width = d$width_in * fattore_w, height = d$height_in * fattore_h)
  else jpeg(percorso, width = round(d$width_px * fattore_w), height = round(d$height_px * fattore_h), res = d$dpi, quality = 95)
}
estensione_bdr <- function() if (identical(input$formato_esportazione, "pdf")) "pdf" else "jpg"

# ---- Computation ----
observeEvent(input$bdr_calcola, {
  br <- batch_risultati()
  if (is.null(br) || length(br$risultati) == 0) { showNotification("Run the Batch Elaboration first.", type = "warning"); return() }
  lista_res <- lapply(br$risultati, function(r) res_da_campione_batch(r, br$formula, br$fissi, br$loss_usata))
  names(lista_res) <- names(br$risultati)
  riepilogo <- riepilogo_diagnostica_batch(lista_res)
  nomi_ok <- names(lista_res)[!sapply(lista_res, is.null)]
  if (length(nomi_ok) == 0) { showNotification("No successfully fitted samples: residual diagnostics are not available.", type = "warning"); return() }
  bdr_stato(list(br = br, res = lista_res[nomi_ok], riepilogo = riepilogo, nomi = nomi_ok))
  
  # Style buttons of "All samples": residuals and lag plot open the panel
  # of the residuals, Q-Q plot and variance structure that of the Q-Q plot.
  # Each observer is created only once, even when recomputing.
  for (i in seq_along(nomi_ok)) for (tp in names(TIPI_GRAFICI_DIAGNOSTICI)) local({
    id <- paste0("bdr_allest_", i, "_", tp); pannello <- if (tp %in% c("residui", "lag")) "Residuals Plot" else "Q-Q Plot"
    if (!id %in% bdr_osservatori_stile) { bdr_osservatori_stile <<- c(bdr_osservatori_stile, id); observeEvent(input[[id]], { apri_estetica(pannello) }, ignoreInit = TRUE) }
  })
  # Plots and downloads for "All samples": one output per sample and type,
  # with the same identifier in both arrangements.
  for (i in seq_along(nomi_ok)) for (tp in names(TIPI_GRAFICI_DIAGNOSTICI)) local({
    ii <- i; tt <- tp; nm <- nomi_ok[ii]
    output[[paste0("bdr_all_", ii, "_", tt)]] <- renderPlot({
      s <- bdr_valido(); if (is.null(s)) return(NULL)
      par(family = "sans"); TIPI_GRAFICI_DIAGNOSTICI[[tt]]$disegna(s$res[[nm]], if (identical(input$bdr_disposizione, "tipo")) nm else NULL)
    })
    output[[paste0("bdr_alldl_", ii, "_", tt)]] <- downloadHandler(
      filename = function() paste0(nome_file_sicuro(nm), "_", TIPI_GRAFICI_DIAGNOSTICI[[tt]]$file, ".", estensione_bdr()),
      content = function(file) { s <- bdr_valido(); apri_dispositivo_bdr(file); on.exit(dev.off()); par(family = "sans")
        TIPI_GRAFICI_DIAGNOSTICI[[tt]]$disegna(s$res[[nm]], paste(TIPI_GRAFICI_DIAGNOSTICI[[tt]]$etichetta, "\u2013", nm)) })
  })
})

